		EQUIP_OWNED_TEAM_ONCE = false, --// Separately authorized equip-only test: freeze one owned-team plan, then end permanently for this controller.
		LOG_TEAM_DETAILS = false, --// Print a detailed comparison once per changed plan; OC:PrintPetTeam() also exposes it on demand.
		MAXIMUM_EQUIP_ATTEMPT_SECONDS = 120, --// Wall-clock limit includes pauses; never retry or automatically restore a partial team.
		MINIMUM_EQUIP_COMMAND_INTERVAL_SECONDS = 1, --// Conservative OC pacing; native/server equip cooldown remains unknown.
		MAXIMUM_SESSION_EQUIP_COMMANDS = 4, --// Bound native equip/unequip commands for this loaded controller, including uncertain requests.
		MAXIMUM_TEAM_EVALUATIONS = 300, --// Bound native projected-team comparisons per analysis; results are a heuristic, not a guaranteed global optimum.
		ANALYSIS_INTERVAL_SECONDS = 15, --// Refresh read-only analytics through the existing planner, without another automation loop.
		EQUIP_CONFIRMATION_TIMEOUT_SECONDS = 10, --// Hold subsequent commands until actual equipped-ID multiplicity acknowledges the request.
		AUTO_DELETE_PETS = false, --// Reserved; destructive inventory operations are disabled.
		AUTO_CRAFT_SHINY = false, --// Reserved; the current build never consumes duplicate pets.
		AUTO_FUSE_PETS = false, --// Reserved; the current build never submits pets to machines.
	},
	HATCH_SETTINGS = {
		HATCH_ONE_EGG_ONCE = false, --// Isolated, explicitly authorized single hatch; Stop or one dispatched egg permanently consumes this controller's authorization.
		MAXIMUM_PLAN_CANDIDATES = 3, --// Compact EGG_PLAN output; full evaluated outcomes remain in GetStatus().
		LOG_EGG_DETAILS = false, --// Optional full evaluated client-pool outcomes, including rejected candidates.
		SELECTED_EGGS = {}, --// Empty permits recommendations but authorizes no hatch location or spending.
		ALLOWED_CURRENCIES = { "Coins" }, --// Only these nonpremium currencies may be spent by an explicitly enabled hatch session.
		MAXIMUM_EGG_COST = 0, --// Explicit per-egg ceiling in native currency units; zero prevents spending.
		MAXIMUM_SESSION_COST = 0, --// Request-cost cap in the session's one authorized currency; uncertain requests consume budget for this loaded controller.
		MAXIMUM_SESSION_HATCHES = 1, --// Count requested eggs, including unconfirmed requests; Stop/Resume cannot reset this ledger.
		MAXIMUM_BATCH_HATCHES = 1, --// Bound each batch by native capacity, remaining session budget and actual free slots.
		MAXIMUM_SESSION_SECONDS = 60, --// End location ownership after this wall-clock session limit, including pauses.
		MINIMUM_REQUEST_INTERVAL_SECONDS = 5, --// Additional pacing floor; native duration and NextEggOpenAt must also permit a request.
		CONFIRMATION_TIMEOUT_SECONDS = 15, --// Wait for actual expected-pool inventory gains; timeout halts this session without automatic retry.
		PRESERVE_PROGRESSION_RESERVE = true, --// Fully protect the next native world gate cost as well as configured currency reserves.
		ENABLE_BACKGROUND_PICKUPS = true, --// Reuse existing stationary collection at the owned egg location where native area/ID evidence permits it.
		MAXIMUM_EGGS_ANALYZED = 40, --// Bound scene-present permanent egg projections; excluded and unknown candidates remain visible.
	},
	EGG_TRAVEL_SETTINGS = {
		ENABLE_SELECTED_EGG_TRAVEL = false, --// Own exactly one explicitly selected egg task; this enables no hatching or spending.
		ENABLE_DIRECT_POSITIONING = false, --// Opt in to one guarded HRP CFrame assignment using observed safe floor geometry; not a native egg teleport.
		ENABLE_NATIVE_ISLAND_TRAVEL = false, --// Permit verified unlocked native island/return travel for this selected egg only.
		ARRIVAL_TIMEOUT_SECONDS = 12, --// Bound each native/final arrival stage; scheduler permits at most twice this plus two seconds, with no repeated corrections.
		STABILITY_SECONDS = 1, --// Require continuous observed proximity after positioning; assignment alone is not arrival.
		MAXIMUM_ATTEMPTS_PER_SELECTION = 1, --// Consume an attempt before dispatch; missing/corrected arrival requires explicit rearming.
		MAXIMUM_LOCATION_SECONDS = 120, --// Bound an intentional egg location lease, including pauses.
		SELECTION_REVISION = 0, --// Increment explicitly to authorize a new attempt at the same egg after manual movement or failure.
	},
	PLAYTIME_SETTINGS = {
		AUTO_CLAIM_PLAYTIME = false, --// Claim only native eligible sparse unclaimed playtime indices; no other reward systems.
		CHECK_INTERVAL_SECONDS = 10, --// Pace eligibility checks; received changes and upcoming thresholds remain relevant.
		CLAIM_INTERVAL_SECONDS = 5, --// Minimum interval between acknowledged playtime operations; never retry an uncertain request.
		CONFIRMATION_TIMEOUT_SECONDS = 15, --// Wait for the exact received claimed key; invocation is not a reward acknowledgement.
	},
	MYSTERY_BOX_SETTINGS = {
		AUTO_OPEN_MYSTERY_BOXES = false, --// Only already-owned ordinary Mystery Boxes; no purchases, rare/event/Infinity boxes.
		BOX_RESERVE = 0, --// Preserve this many ordinary boxes before every operation.
		MAXIMUM_SESSION_BOXES = 1, --// First active test consumes at most one; charged requests persist across Pause/Resume/reloads.
		MAXIMUM_BATCH_BOXES = 1, --// Conservative supported operation is one box; later continuation still uses individually verified openings.
		OPEN_INTERVAL_SECONDS = 5, --// Pace subsequent verified ordinary openings when continuation is explicitly enabled.
		CONFIRMATION_TIMEOUT_SECONDS = 20, --// An unconfirmed debit/spawn/reward halts without duplicate opening.
		ENABLE_AUTOMATIC_CONTINUATION = false, --// Opt in later to more individually verified openings within the owner-selected allowance.
		SESSION_KEY = "ORDINARY_BOX_TEST", --// Explicit consumption ledger identity; changing it cannot clear an unresolved account operation.
	},
	ANTIAFK_SETTINGS = {
		ENABLE_ANTI_AFK = false, --// Periodic scheduler task only; Pause/Stop/Destroy suppress simulated input.
		METHOD = "VIRTUAL_INPUT_SCROLL_LOCK", --// Requires runtime SendKeyEvent; rejects assigned ScrollLock, releases synchronously; no Space/R or mouse clicks.
		INTERVAL_SECONDS = 120, --// Delay between eligible input pulses; sent input does not prove long-duration idle prevention.
	},
	STATUS_UI_SETTINGS = {
		ENABLE_STATUS_UI = true, --// Display the foundation panel and OC controls.
		SHOW_ACCOUNT_BALANCES = true, --// Show real balances and bubble capacity; missing values display unavailable.
		SHOW_PROGRESSION = true, --// Show the evidence-based progression category and unlock counts.
		SHOW_PREREQUISITES = true, --// Show why the next objective is blocked or ready.
		SHOW_DIAGNOSTICS = true, --// Show missing data and game dependency failures.
		SHOW_PETS = true, --// Display equipped pet IDs and inventory pet records.
		SHOW_INVENTORY = true, --// Display received potion and powerup inventory entries.
		SHOW_UPGRADES = true, --// Display owned gum, flavors, and received Mastery upgrades.
		SHOW_MASTERY = true, --// Display received levels and verified next tier costs.
		SHOW_WORLDS = true, --// Display actual unlocked world and island names.
		SHOW_FARMING = true, --// Show the chosen activity, useful currency, current island, and native collection constraint.
		SHOW_FARMING_RATES = true, --// Show per-currency observed earnings and sample time, including combined activity attribution.
		SHOW_ISLAND_CANDIDATES = true, --// Show measured versus estimated candidate earnings and travel evidence.
		MAXIMUM_DISPLAY_ENTRIES = 30, --// Bound each inventory display; GetStatus retains the complete read snapshot.
		PANEL_WIDTH_PIXELS = 390, --// Set the maximum panel width; small viewports scale down.
		PANEL_HEIGHT_PIXELS = 420, --// Set the maximum panel height; content can scroll.
	},
	DIAGNOSTIC_SETTINGS = {
		ENABLE_DEBUG_LOGGING = false, --// Restore detailed diagnostics under the existing LOG_* controls; false prints compact summaries and meaningful events.
		SUMMARY_INTERVAL_SECONDS = 15, --// Print one read-only summary at this interval through existing status updates; no new timer or gameplay loop.
		LOG_MOVEMENT_DIAGNOSTICS = true, --// Report bounded path recovery and final blockers without per-frame progress spam.
		LOG_UPGRADE_DIAGNOSTICS = true, --// Explain each considered catalog upgrade's budgets, projected effects, payback and blocking conditions.
		LOG_PICKUP_DIAGNOSTICS = true, --// Print rate-limited scan, classification, rejection, range and balance-result summaries.
		LOG_PICKUP_DETAIL_PATHS = false, --// Include a bounded number of problem paths only when diagnosing rejected or missing targets.
		LOG_ISLAND_DISCOVERY = true, --// Explain every catalog/zone island's unlocks, mapping, destination, counts and exclusion reason.
		ENABLE_CONSOLE_LOGGING = true, --// Print prefixed control, account, dependency, and objective diagnostics.
		LOG_ACCOUNT_DETAILS = true, --// Print bounded pet, inventory, unlock, upgrade, and Mastery details on changes.
		LOG_DEPENDENCIES = true, --// Print game module load status changes and errors.
		MINIMUM_LOG_INTERVAL_SECONDS = 5, --// Rate limit account diagnostics while preserving the latest changed snapshot.
		MAXIMUM_LOG_ENTRIES = 30, --// Limit each detailed console inventory list; PrintAccount accepts an explicit limit.
	},
}

end

-- src/OCFoundation/OCController.luau
factories["OCController"] = function()
--!nonstrict
local AccountStateReader = requireOC("AccountStateReader")
local OCBrain = requireOC("OCBrain")
local TaskScheduler = requireOC("TaskScheduler")
local AccountPresentation = requireOC("AccountPresentation")
local FarmingCoordinator = requireOC("FarmingCoordinator")
local GameKnowledge = requireOC("GameKnowledge")
local WorldProgressionManager = requireOC("WorldProgressionManager")
local PetManager = requireOC("PetManager")
local EggTravelManager = requireOC("EggTravelManager")
local RewardsManager = requireOC("RewardsManager")
local AntiAFKManager = requireOC("AntiAFKManager")

local OCController = {}
OCController.__index = OCController

local function validate(config)
	for _, name in ipairs({ "GENERAL_SETTINGS", "ACCOUNT_SETTINGS", "BRAIN_SETTINGS", "RESOURCE_SETTINGS",
		"TASK_SETTINGS", "BUBBLE_SETTINGS", "FALL_EVENT_SETTINGS", "PET_SETTINGS", "STATUS_UI_SETTINGS", "DIAGNOSTIC_SETTINGS",
		"FARMING_SETTINGS", "ISLAND_SETTINGS", "PICKUP_SETTINGS", "UPGRADE_SETTINGS", "WORLD_SETTINGS", "HATCH_SETTINGS",
		"EGG_TRAVEL_SETTINGS", "PLAYTIME_SETTINGS", "MYSTERY_BOX_SETTINGS", "ANTIAFK_SETTINGS" }) do
		assert(type(config[name]) == "table", "Missing configuration category: " .. name)
	end
	for category, entries in pairs(config) do
		assert(type(category) == "string" and category:match("^[A-Z][A-Z_]*_SETTINGS$"), "Invalid configuration category")
		assert(type(entries) == "table", category .. " must be a table")
		for key, value in pairs(entries) do
			assert(type(key) == "string" and key:match("^[A-Z][A-Z_]*$"), "Invalid configuration setting")
			if key:match("^ENABLE_") or key:match("^AUTO_") or key:match("^READ_") or key:match("^SHOW_") or key == "OC_ENABLED" then
				assert(type(value) == "boolean", category .. "." .. key .. " must be true or false")
			elseif type(value) == "number" then
				assert(value == value and value >= 0 and value < math.huge, category .. "." .. key .. " must be finite and nonnegative")
			elseif type(value) == "table" then
				local count = 0
				for index, item in pairs(value) do
					assert(type(index) == "number" and index >= 1 and index % 1 == 0 and type(item) == "string", key .. " must be an array of strings")
					count += 1
				end
				assert(count == #value, key .. " must be a contiguous array")
			end
		end
	end
	for _, value in ipairs({ config.ACCOUNT_SETTINGS.MODULE_LOAD_TIMEOUT_SECONDS, config.ACCOUNT_SETTINGS.ACCOUNT_LOAD_TIMEOUT_SECONDS,
		config.ACCOUNT_SETTINGS.SNAPSHOT_REFRESH_SECONDS, config.TASK_SETTINGS.TASK_TIMEOUT_SECONDS, config.TASK_SETTINGS.MAXIMUM_PENDING_TASKS }) do
		assert(type(value) == "number" and value >= 1, "Timeouts, refresh intervals, and queue limits must be at least one")
	end
	assert(type(config.ACCOUNT_SETTINGS.MINIMUM_SNAPSHOT_INTERVAL_SECONDS) == "number" and config.ACCOUNT_SETTINGS.MINIMUM_SNAPSHOT_INTERVAL_SECONDS >= 0,
		"MINIMUM_SNAPSHOT_INTERVAL_SECONDS must be numeric and nonnegative")
	assert(config.GENERAL_SETTINGS.PROGRESSION_PROFILE == "FULL_AUTO_PROGRESSION", "Only FULL_AUTO_PROGRESSION is implemented")
	assert(config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO > 0 and config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO <= 1, "Sell threshold must be in (0, 1]")
	assert(config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION > 0 and config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION <= 1, "Upgrade budget fraction must be in (0, 1]")
	assert(config.STATUS_UI_SETTINGS.PANEL_WIDTH_PIXELS >= 280 and config.STATUS_UI_SETTINGS.PANEL_HEIGHT_PIXELS >= 280, "Panel dimensions must be at least 280 pixels")
	for _, limit in ipairs({ config.STATUS_UI_SETTINGS.MAXIMUM_DISPLAY_ENTRIES, config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES,
		config.TASK_SETTINGS.MAXIMUM_PENDING_TASKS }) do
		assert(limit >= 1 and limit % 1 == 0, "Entry and queue limits must be positive integers")
	end
	for _, value in ipairs({ config.FARMING_SETTINGS.OBSERVATION_INTERVAL_SECONDS, config.FARMING_SETTINGS.ACTION_SLICE_SECONDS,
		config.FARMING_SETTINGS.MINIMUM_RATE_SAMPLE_SECONDS, config.FARMING_SETTINGS.RATE_WINDOW_SECONDS,
		config.PICKUP_SETTINGS.COLLECTION_REFRESH_SECONDS, config.PICKUP_SETTINGS.ZONE_REFRESH_SECONDS, config.PICKUP_SETTINGS.PREFAB_REFRESH_SECONDS,
		config.PICKUP_SETTINGS.PATH_TIMEOUT_SECONDS, config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS,
		config.ISLAND_SETTINGS.PICKUP_PROBE_TIMEOUT_SECONDS, config.ISLAND_SETTINGS.ISLAND_EXPLORATION_RETRY_SECONDS,
		config.UPGRADE_SETTINGS.PURCHASE_CONFIRMATION_TIMEOUT_SECONDS, config.BUBBLE_SETTINGS.SELL_CONFIRMATION_TIMEOUT_SECONDS }) do
		assert(value >= 1, "Farming observation, sample, slice, and timeout intervals must be at least one second")
	end
	assert(config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS >= 0.5, "Native blowing cooldown must be at least 0.5 seconds")
	assert(config.UPGRADE_SETTINGS.MAXIMUM_GOAL_RESERVE_BALANCE_FRACTION <= 1, "Goal reserve balance fraction must be in [0, 1]")
	for _, key in ipairs({ "MAXIMUM_SESSION_WORLD_UNLOCKS", "MAXIMUM_UNLOCK_ATTEMPTS", "MAXIMUM_TRAVEL_ATTEMPTS", "MAXIMUM_ISLAND_DISCOVERY_ATTEMPTS" }) do
		local value = config.WORLD_SETTINGS[key]
		assert(value >= 1 and value % 1 == 0, key .. " must be a positive integer")
	end
	assert(config.WORLD_SETTINGS.ISLAND_DISCOVERY_CONTACT_SECONDS >= 0.05 and config.WORLD_SETTINGS.ISLAND_DISCOVERY_CONTACT_SECONDS <= 0.5,
		"Discovery contact duration must be in [0.05,0.5] seconds")
	assert(config.WORLD_SETTINGS.ISLAND_DISCOVERY_CONFIRMATION_TIMEOUT_SECONDS >= 1
		and config.WORLD_SETTINGS.ISLAND_DISCOVERY_CONFIRMATION_TIMEOUT_SECONDS <= 30
		and config.WORLD_SETTINGS.ISLAND_DISCOVERY_INTERVAL_SECONDS >= 10
		and config.WORLD_SETTINGS.ISLAND_DISCOVERY_RETRY_COOLDOWN_SECONDS >= 10,
		"Discovery confirmation must be in [1,30] seconds; attempt interval/retry at least ten seconds")
	assert(config.WORLD_SETTINGS.UNLOCK_CONFIRMATION_TIMEOUT_SECONDS >= 1 and config.WORLD_SETTINGS.UNLOCK_RETRY_COOLDOWN_SECONDS >= 10,
		"World unlock confirmation must be at least one second and retry at least ten seconds")
	assert(config.WORLD_SETTINGS.FUNDING_HORIZON_HOURS > 0 and config.WORLD_SETTINGS.ECONOMIC_LOG_INTERVAL_SECONDS >= 5,
		"Funding diagnostic horizon must be positive and economic log interval at least five seconds")
	assert(config.DIAGNOSTIC_SETTINGS.SUMMARY_INTERVAL_SECONDS >= 5, "Console summary interval must be at least five seconds")
	assert(config.WORLD_SETTINGS.TRAVEL_STABILIZATION_SECONDS >= 0.4
		and config.WORLD_SETTINGS.TRAVEL_STABILIZATION_SECONDS < config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS,
		"Progression travel stabilization must fit inside the native travel confirmation window")
	assert(config.PICKUP_SETTINGS.MAXIMUM_PATH_RECOMPUTES % 1 == 0 and config.PICKUP_SETTINGS.MAXIMUM_PATH_RECOMPUTES <= 3, "Path recomputes must be an integer in [0, 3]")
	assert(config.PICKUP_SETTINGS.WAYPOINT_STALL_SECONDS >= 1 and config.PICKUP_SETTINGS.MOVE_REISSUE_SECONDS >= 1, "Movement stall and reissue intervals must be at least one second")
	assert(config.PICKUP_SETTINGS.MINIMUM_WAYPOINT_PROGRESS_STUDS > 0, "Waypoint progress threshold must be positive")
	assert(config.FARMING_SETTINGS.RATE_WINDOW_SECONDS >= config.FARMING_SETTINGS.MINIMUM_RATE_SAMPLE_SECONDS, "Rate window is smaller than the minimum sample")
	assert(config.PICKUP_SETTINGS.MAXIMUM_CLUSTER_CANDIDATES >= 1 and config.PICKUP_SETTINGS.MAXIMUM_CLUSTER_CANDIDATES % 1 == 0, "Cluster candidate limit must be a positive integer")
	assert(config.PICKUP_SETTINGS.MAXIMUM_CLUSTER_CANDIDATES <= 64, "Cluster candidate limit must not exceed 64")
	assert(config.PICKUP_SETTINGS.ZONE_MATCH_TOLERANCE_STUDS <= 2, "Zone boundary tolerance must not exceed two studs")
	assert(config.ISLAND_SETTINGS.ARRIVAL_PICKUP_GRACE_SECONDS < config.ISLAND_SETTINGS.PICKUP_PROBE_TIMEOUT_SECONDS, "Arrival grace must be smaller than the pickup trial timeout")
	local pets, hatch = config.PET_SETTINGS, config.HATCH_SETTINGS
	local eggTravel, playtime, boxes, idle = config.EGG_TRAVEL_SETTINGS, config.PLAYTIME_SETTINGS,
		config.MYSTERY_BOX_SETTINGS, config.ANTIAFK_SETTINGS
	for _, value in ipairs({ eggTravel.ARRIVAL_TIMEOUT_SECONDS, eggTravel.STABILITY_SECONDS, eggTravel.MAXIMUM_LOCATION_SECONDS,
		playtime.CHECK_INTERVAL_SECONDS, playtime.CLAIM_INTERVAL_SECONDS, playtime.CONFIRMATION_TIMEOUT_SECONDS,
		boxes.OPEN_INTERVAL_SECONDS, boxes.CONFIRMATION_TIMEOUT_SECONDS }) do
		assert(value >= 1, "Local feature intervals and timeouts must be at least one second")
	end
	assert(eggTravel.STABILITY_SECONDS < eggTravel.ARRIVAL_TIMEOUT_SECONDS, "Egg stability window must fit inside arrival timeout")
	for _, value in ipairs({ eggTravel.MAXIMUM_ATTEMPTS_PER_SELECTION, boxes.MAXIMUM_SESSION_BOXES, boxes.MAXIMUM_BATCH_BOXES }) do
		assert(value >= 1 and value % 1 == 0, "Local feature operation limits must be positive integers")
	end
	assert(boxes.BOX_RESERVE % 1 == 0 and eggTravel.SELECTION_REVISION % 1 == 0, "Box reserve and selection revision must be integers")
	assert(type(boxes.SESSION_KEY) == "string" and #boxes.SESSION_KEY > 0 and #boxes.SESSION_KEY <= 80, "Box session key must be a bounded nonempty string")
	assert(idle.METHOD == "VIRTUAL_INPUT_SCROLL_LOCK" and idle.INTERVAL_SECONDS >= 60, "Anti-AFK requires guarded ScrollLock method and at least sixty seconds")
	assert(table.find({ "AUTO", "Coins", "Gems", "Bubbles", "Tickets", "Pearls" }, pets.OBJECTIVE_CURRENCY), "Unknown pet objective currency")
	for _, value in ipairs({ pets.MAXIMUM_SESSION_EQUIP_COMMANDS, pets.MAXIMUM_TEAM_EVALUATIONS,
		hatch.MAXIMUM_SESSION_HATCHES, hatch.MAXIMUM_BATCH_HATCHES, hatch.MAXIMUM_EGGS_ANALYZED, hatch.MAXIMUM_PLAN_CANDIDATES }) do
		assert(value >= 1 and value % 1 == 0, "Pet/hatch count and analysis limits must be positive integers")
	end
	assert(pets.MAXIMUM_TEAM_EVALUATIONS <= 1000 and hatch.MAXIMUM_EGGS_ANALYZED <= 64 and hatch.MAXIMUM_BATCH_HATCHES <= 12, "Pet analysis/batch limits exceed supported bounds")
	assert(pets.ANALYSIS_INTERVAL_SECONDS >= 5 and pets.EQUIP_CONFIRMATION_TIMEOUT_SECONDS >= 1
		and pets.MAXIMUM_EQUIP_ATTEMPT_SECONDS >= 1 and pets.MINIMUM_EQUIP_COMMAND_INTERVAL_SECONDS >= 1
		and hatch.CONFIRMATION_TIMEOUT_SECONDS >= 1 and hatch.MAXIMUM_SESSION_SECONDS >= 1
		and hatch.MINIMUM_REQUEST_INTERVAL_SECONDS >= 1, "Pet/hatch intervals must be bounded and positive")
	assert(type(hatch.PRESERVE_PROGRESSION_RESERVE) == "boolean", "PRESERVE_PROGRESSION_RESERVE must be boolean")
	assert(type(hatch.HATCH_ONE_EGG_ONCE) == "boolean" and type(hatch.LOG_EGG_DETAILS) == "boolean", "Single-hatch/detail flags must be boolean")
	assert(hatch.MAXIMUM_PLAN_CANDIDATES <= 6, "Compact egg plan supports at most six candidates")
	if hatch.HATCH_ONE_EGG_ONCE then
		local reason = requireOC("PetPolicy").HatchIsolation(config)
		assert(not reason, reason)
	end
	for _, currency in ipairs(hatch.ALLOWED_CURRENCIES) do assert(table.find({ "Coins", "Gems", "Tickets", "Pearls" }, currency), "Unsupported hatch currency") end
	if pets.AUTO_HATCH or pets.AUTO_EQUIP then assert(pets.ENABLE_PET_INTELLIGENCE, "Pet actions require ENABLE_PET_INTELLIGENCE") end
	assert(type(pets.EQUIP_OWNED_TEAM_ONCE) == "boolean" and type(pets.LOG_TEAM_DETAILS) == "boolean", "Owned-team test/detail flags must be boolean")
	if pets.EQUIP_OWNED_TEAM_ONCE then
		assert(pets.AUTO_EQUIP and not pets.AUTO_HATCH and pets.OBJECTIVE_CURRENCY == "Coins", "One-time owned-team test requires explicit Coins equipment authorization and hatching OFF")
		for category, keys in pairs({
			WORLD_SETTINGS = { "ENABLE_WORLD_PROGRESSION", "AUTO_DISCOVER_ISLANDS", "AUTO_UNLOCK_WORLDS", "AUTO_TRAVEL_FOR_PROGRESSION", "AUTO_FARM_UNLOCK_REQUIREMENTS" },
			FARMING_SETTINGS = { "AUTO_RESOURCE_FARM", "AUTO_FARM_FALLBACK" },
			ISLAND_SETTINGS = { "AUTO_TRAVEL_BEST_ISLAND", "AUTO_EXPLORE_UNLOCKED_ISLANDS" },
			BUBBLE_SETTINGS = { "AUTO_BLOW_BUBBLES", "AUTO_SELL_BUBBLES", "AUTO_BUY_GUM", "AUTO_BUY_FLAVORS", "ENABLE_SIMULTANEOUS_BLOWING" },
			UPGRADE_SETTINGS = { "ENABLE_SMART_UPGRADES", "ENABLE_CAPACITY_UPGRADES", "ENABLE_FLAVOR_UPGRADES", "AUTO_EQUIP_OWNED_UPGRADES" },
		}) do
			for _, key in ipairs(keys) do assert(not config[category][key], "Equip-only test requires " .. category .. "." .. key .. " OFF") end
		end
		assert(hatch.MAXIMUM_EGG_COST == 0 and hatch.MAXIMUM_SESSION_COST == 0 and not hatch.ENABLE_BACKGROUND_PICKUPS, "Equip-only test requires zero hatch budgets and background collection OFF")
	end
	if pets.AUTO_HATCH then
		assert(#hatch.SELECTED_EGGS > 0 and hatch.MAXIMUM_EGG_COST > 0 and hatch.MAXIMUM_SESSION_COST > 0, "Hatching requires explicit egg selection and positive spending budgets")
		assert(#hatch.ALLOWED_CURRENCIES == 1, "Each bounded hatch session must authorize exactly one currency")
	end
	-- Destructive and later-phase executors remain unavailable.
	for _, category in ipairs({ "PET_SETTINGS", "FALL_EVENT_SETTINGS" }) do
		for key, value in pairs(config[category]) do
			if (key:match("^AUTO_") or key == "ENABLE_FALL_EVENT") and value and key ~= "AUTO_HATCH" and key ~= "AUTO_EQUIP" then
				error("[OC] " .. category .. "." .. key .. " is reserved; its executor is not implemented")
			end
		end
	end
end

function OCController.new(config, player)
	validate(config)
	local self = setmetatable({}, OCController)
	self.Config = config
	self.Changed = Instance.new("BindableEvent")
	self.Reader = AccountStateReader.new(config, player)
	self.Knowledge = GameKnowledge.new(self.Reader)
	self.Brain = OCBrain.new(config)
	self.Scheduler = TaskScheduler.new(config.TASK_SETTINGS)
	self.State = "STOPPED"
	self.Generation = 0
	self.Plan = nil
	self.Error = nil
	self.Destroyed = false
	self.LastPlanAt = -math.huge
	self.Connections = {}
	self.Snapshot = self.Reader:GetSnapshot()
	self.Farming = FarmingCoordinator.new(self, player)
	self.WorldProgression = WorldProgressionManager.new(self)
	self.Pets = PetManager.new(self)
	self.EggTravel = EggTravelManager.new(self)
	self.Rewards = RewardsManager.new(self)
	self.AntiAFK = AntiAFKManager.new(self)
	self.Farming.Mechanics.LocalFeatureController = self
	self.Farming.Metrics.AttributionBlockedProvider = function() return self:RewardAttributionBlocked() end
	self.Farming.Mechanics.PetLocationOwnerProvider = function()
		return self.Pets.Hatch.Location ~= nil or self.EggTravel:OwnsLocation()
	end
	table.insert(self.Connections, self.Reader.Changed.Event:Connect(function(snapshot)
		self.Snapshot = snapshot
		self.Rewards:Observe()
		self.EggTravel:Observe()
		self:_diagnoseSnapshot(snapshot)
		self:_notify()
		self:_requestPlan(false)
	end))
	table.insert(self.Connections, self.Scheduler.Changed.Event:Connect(function() self:_notify() end))
	table.insert(self.Connections, self.Scheduler.Completed.Event:Connect(function(id, status, result, reason, definition)
		if self.Destroyed or self.State ~= "RUNNING" then return end
		if id == "OC_GAMEPLAY" then
			if definition and definition.Generation == self.Generation then
				if definition.Owner == "REWARDS" then self.Rewards:Completed(status, result, reason)
				elseif definition.Owner == "EGG_TRAVEL" then self.EggTravel:Completed(status, result, reason)
				elseif definition.Owner == "ANTI_AFK" then self.AntiAFK:Completed(status, result, reason)
				elseif definition.Owner == "WORLD_PROGRESSION" then self.WorldProgression:Completed(status, result, reason)
				elseif definition.Owner == "PETS" then self.Pets:Completed(status, result, reason)
				else self.Farming:Completed(status, result, reason) end
				self.Reader:Refresh()
				self:_requestPlan(true)
			end
			return
		end
		if id ~= "ANALYZE_ACCOUNT" then return end
		if status == "COMPLETED" and type(result) == "table" and result.Generation == self.Generation then
			if result.SnapshotRevision < self.Snapshot.Revision then self:_requestPlan(true) return end
			self.Plan = result
			self.Error = nil
			self.LastPlanAt = os.clock()
			local goal = result.Objective
			if self.LastObjectiveId ~= goal.Id then
				self.LastObjectiveId = goal.Id
				self:Log("GOAL", goal.Id .. " | " .. goal.Title .. " | " .. goal.Reason)
				self:Log("PROGRESSION", result.Progression .. " | " .. result.ProgressionEvidence)
				if #goal.Prerequisites > 0 then self:Log("PREREQUISITES", table.concat(goal.Prerequisites, "; ")) end
			end
			local localOwner, localDecision = self.Brain:SelectLocalFeature(self, result)
			local petOwns, petDecision
			if not localOwner then petOwns, petDecision = self.Pets:Select(result) end
			local owns, decision
			if not localOwner and not petOwns then owns, decision = self.WorldProgression:Select(result) end
			local taskDefinition
			if localOwner then
				if self.Farming.Activity then self.Farming:Halt(true) end
				local manager = ({ REWARDS = self.Rewards, EGG_TRAVEL = self.EggTravel, ANTI_AFK = self.AntiAFK })[localOwner]
				taskDefinition = manager:Definition(localDecision, self.Generation)
			elseif petOwns then
				if self.Farming.Activity then self.Farming:Halt(true) end
				taskDefinition = self.Pets:Definition(petDecision, self.Generation)
			elseif owns then
				self.Farming:Halt(true)
				taskDefinition = self.WorldProgression:Definition(decision, self.Generation)
			else
				decision = self.Farming:Select(result)
				taskDefinition = self.Farming:Definition(decision, self.Generation)
			end
			if taskDefinition then
				local accepted, errorMessage = self.Scheduler:Submit(taskDefinition)
				if not accepted then self.Error = errorMessage self:Log("FARM][ERROR", errorMessage) end
			end
		elseif status == "FAILED" then self.Error = tostring(result) self:Log("DIAGNOSTIC", self.Error)
		elseif status == "CANCELLED" and reason == "Task timed out" then self.Error = reason self:Log("DIAGNOSTIC", reason) end
		self:_notify()
	end))
	-- Reading remains available while controls are stopped; no gameplay is executed.
	self.Reader:Start()
	self.Farming:StartObservations()
	return self
end

function OCController:Log(kind, message, explicitDetail)
	local settings = self.Config.DIAGNOSTIC_SETTINGS
	if not settings.ENABLE_CONSOLE_LOGGING then return end
	message = tostring(message)
	if not settings.ENABLE_DEBUG_LOGGING and not explicitDetail then
		local immediate = kind == "INIT" or kind == "SCOPE" or kind == "CONTROL" or kind == "GOAL" or kind == "SUMMARY"
			or kind == "ISLAND][VERIFIED" or kind == "WORLD][VERIFIED" or kind == "UPGRADE][VERIFIED" or kind == "FARM][RETURN"
			or kind == "PET][ANALYSIS" or kind == "PET][VERIFIED" or kind == "PET][TEAM_PLAN" or kind == "PET][EQUIP_RESULT"
			or kind == "EGG_PLAN" or kind == "HATCH_RESULT"
			or kind == "EGG_TRAVEL" or kind == "PLAYTIME_RESULT" or kind == "BOX_RESULT" or kind == "ANTI_AFK"
			or kind == "REWARD][RESULT" or kind == "REWARD][UNCONFIRMED"
		if kind == "FARM][TRAVEL" then immediate = not message:match("^Request ") end
		local blocker = kind == "FARM][FALLBACK" or kind == "WORLD][GATE_APPROACH" or kind == "DIAGNOSTIC" or kind == "UNAVAILABLE"
			or kind:find("ERROR", 1, true) ~= nil or kind == "ISLAND][CONTACT" or kind == "PET][BLOCKER"
		if kind == "WORLD][DECISION" then blocker = message:match("^WAIT ") ~= nil end
		if kind == "WORLD][RESULT" then
			immediate = message:find("Native portal arrival stabilized", 1, true) ~= nil
			blocker = not immediate and message:find("Actual LocalData", 1, true) == nil
		end
		if kind == "DEPENDENCY" then blocker = message:find("=ERROR", 1, true) ~= nil end
		if kind == "PICKUP][CLEANUP_ERROR" then message = message:gsub("^id=[^|]+ | ", "") end
		if kind == "WORLD][BOTTLENECK" then
			blocker = true message = "Estimated funding time exceeds the configured horizon; earning-power review needed. Recommendations do not authorize purchases."
		end
		if not immediate and not blocker then return end
		if blocker and not immediate then
			self.ConsoleBlockers = self.ConsoleBlockers or {}
			local previous, now = self.ConsoleBlockers[kind], os.clock()
			if previous and previous.Message == message and now - previous.At < math.max(60, settings.MINIMUM_LOG_INTERVAL_SECONDS) then return end
			self.ConsoleBlockers[kind] = { Message = message, At = now } -- One record per existing diagnostic category, not per pickup ID.
		end
	end
	print("[OC][" .. kind .. "] " .. message)
end

function OCController:_reportSummary(status, now)
	local settings = self.Config.DIAGNOSTIC_SETTINGS
	if not settings.ENABLE_CONSOLE_LOGGING or settings.ENABLE_DEBUG_LOGGING then self.SummaryPrevious = nil return end
	local previous = self.SummaryPrevious
	if previous and now - previous.At < settings.SUMMARY_INTERVAL_SECONDS then return end
	local balances = status.Snapshot and status.Snapshot.Balances or {}
	self.SummaryPrevious = { At = now, Balances = table.clone(balances) }
	if not previous then return end -- Establish a baseline; never invent initial interval earnings.
	local ok, output = pcall(AccountPresentation.Summary, status, previous, now, self.Config)
	self:Log(ok and "SUMMARY" or "CONSOLE][ERROR", ok and output or "Summary formatting unavailable: " .. tostring(output))
end

function OCController:PrintPetTeam()
	return self.Pets:PrintTeam()
end

function OCController:PrintAccount(limit)
	if not self.Config.DIAGNOSTIC_SETTINGS.ENABLE_CONSOLE_LOGGING then return false, "Console logging is disabled" end
	limit = limit or self.Config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES
	assert(type(limit) == "number" and limit >= 1 and limit % 1 == 0, "PrintAccount limit must be a positive integer")
	local snapshot = self.Reader:GetSnapshot()
	self:Log("ACCOUNT", "Status=" .. snapshot.Status .. "; Ready=" .. tostring(snapshot.Ready) .. "; Revision=" .. snapshot.Revision, true)
	if snapshot.Source then self:Log("SOURCE", snapshot.Source, true) end
	local sections = AccountPresentation.Sections(snapshot, self.Config, limit)
	for _, name in ipairs({ "Balances", "Pets", "Inventory", "Worlds", "Upgrades", "Mastery" }) do
		self:Log(string.upper(name), "\n" .. sections[name], true)
	end
	for _, diagnostic in ipairs(snapshot.Diagnostics or {}) do self:Log("DIAGNOSTIC", diagnostic, true) end
	if snapshot.UnavailableFields and #snapshot.UnavailableFields > 0 then
		self:Log("UNAVAILABLE", table.concat(snapshot.UnavailableFields, ", "), true)
	end
	return true
end

function OCController:_diagnoseSnapshot(snapshot)
	local settings = self.Config.DIAGNOSTIC_SETTINGS
	if not settings.ENABLE_CONSOLE_LOGGING then return end
	self.LastDependencies = self.LastDependencies or {}
	if settings.LOG_DEPENDENCIES then
		for name, entry in pairs(snapshot.Dependencies or {}) do
			local description = entry.Status .. (entry.Error and " | " .. entry.Error or "")
			if self.LastDependencies[name] ~= description then
				self.LastDependencies[name] = description
				self:Log("DEPENDENCY", name .. "=" .. description .. " | " .. entry.Path)
			end
		end
	end
	if self.LastAccountStatus ~= snapshot.Status then
		self.LastAccountStatus = snapshot.Status
		self:Log("ACCOUNT", "Status=" .. snapshot.Status .. "; Ready=" .. tostring(snapshot.Ready))
		for _, message in ipairs(snapshot.Diagnostics or {}) do self:Log("DIAGNOSTIC", message) end
	end
	if not snapshot.Ready then return end
	if not settings.ENABLE_DEBUG_LOGGING then return end -- Only presentation: full account formatting is unnecessary in summary mode.
	if self.AccountLogThread then return end
	local delaySeconds = math.max(0, settings.MINIMUM_LOG_INTERVAL_SECONDS - (os.clock() - (self.LastAccountLogAt or -math.huge)))
	self.AccountLogThread = task.delay(delaySeconds, function()
		self.AccountLogThread = nil
		if self.Destroyed then return end
		if not settings.ENABLE_DEBUG_LOGGING then return end
		local latest = self.Reader:GetSnapshot()
		local sections = AccountPresentation.Sections(latest, self.Config, settings.MAXIMUM_LOG_ENTRIES)
		local summary = latest.Status .. "\n" .. sections.Balances
		if settings.LOG_ACCOUNT_DETAILS then
			for _, name in ipairs({ "Pets", "Inventory", "Worlds", "Upgrades", "Mastery" }) do summary ..= "\n" .. sections[name] end
		end
		if self.LastLoggedAccount ~= summary then
			self.LastLoggedAccount = summary
			self.LastAccountLogAt = os.clock()
			if settings.LOG_ACCOUNT_DETAILS then self:PrintAccount()
			else self:Log("BALANCES", sections.Balances) end
		end
	end)
end

function OCController:GetStatus()
	return { State = self.State, Snapshot = self.Reader:GetSnapshot(), Plan = self.Plan,
		Scheduler = self.Scheduler:GetStatus(), Farming = self.Farming:GetStatus(), WorldProgression = self.WorldProgression:GetStatus(),
		Pets = self.Pets and self.Pets:GetStatus(), Error = self.Error,
		EggTravel = self.EggTravel and self.EggTravel:GetStatus(), Rewards = self.Rewards and self.Rewards:GetStatus(),
		AntiAFK = self.AntiAFK and self.AntiAFK:GetStatus(),
		Phase = self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE and 4 or self.Config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION and 3 or 2 }
end

function OCController:_notify()
	if not self.Destroyed then
		local status = self:GetStatus()
		self:_reportSummary(status, os.clock())
		self.Changed:Fire(status)
	end
end

function OCController:_cancelReplan()
	if self.ReplanThread then pcall(task.cancel, self.ReplanThread) self.ReplanThread = nil end
end

function OCController:_requestPlan(force)
	if self.Destroyed or self.State ~= "RUNNING" then return end
	if force then self:_cancelReplan() end
	if self.ReplanThread then return end
	local delaySeconds = force and 0 or math.max(0, self.Config.GENERAL_SETTINGS.REPLAN_COOLDOWN_SECONDS - (os.clock() - self.LastPlanAt))
	local generation = self.Generation
	self.ReplanThread = task.delay(delaySeconds, function()
		self.ReplanThread = nil
		if self.Destroyed or self.State ~= "RUNNING" or generation ~= self.Generation then return end
		local snapshot = self.Reader:GetSnapshot()
		local accepted, reason = self.Scheduler:Submit({
			Id = "ANALYZE_ACCOUNT", Priority = 100,
			CanRun = function() return self.State == "RUNNING" and generation == self.Generation end,
			Execute = function(token)
				local result = self.Brain:Plan(snapshot, token)
				if result then result.Generation = generation end
				return result
			end,
			IsComplete = function(result) return type(result) == "table" and result.Objective ~= nil end,
		})
		if not accepted then self.Error = reason self:_notify() end
	end)
end

function OCController:Start()
	if self.Destroyed then return false, "Controller was destroyed" end
	if not self.Config.GENERAL_SETTINGS.OC_ENABLED then return false, "OC is disabled in OCConfig" end
	if not self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then return false, "Account reading is disabled" end
	if not self.Config.TASK_SETTINGS.ENABLE_TASK_SCHEDULER then return false, "Task scheduler is disabled" end
	if self.State == "RUNNING" then return true end
	if self.State == "PAUSED" then return self:Resume() end
	self.Generation += 1
	self.State = "RUNNING"
	self.Error = nil
	self.AntiAFK:Resume()
	self.Brain:Reset()
	self.LastObjectiveId = nil
	self.Reader:Refresh()
	self.Scheduler:Resume()
	self:_requestPlan(true)
	self:_notify()
	self:Log("CONTROL", "START | account analysis and Brain-selected tasks enabled by Config | phase=" .. tostring(self:GetStatus().Phase))
	return true
end

function OCController:Pause()
	if self.Destroyed or self.State ~= "RUNNING" then return false, "OC is not running" end
	self.Generation += 1
	self.State = "PAUSED"
	self:_cancelReplan()
	self.Scheduler:Pause()
	self.Farming:Halt(true)
	self.WorldProgression:Halt()
	self.Pets:Halt()
	self.EggTravel:Halt(false)
	self.Rewards:Halt(false)
	self.AntiAFK:Halt("Paused")
	self:_notify()
	self:Log("CONTROL", "PAUSE | recommendations paused; read-only account updates remain visible")
	return true
end

function OCController:Resume()
	if self.Destroyed or self.State ~= "PAUSED" then return false, "OC is not paused" end
	self.Generation += 1
	self.State = "RUNNING"
	self.AntiAFK:Resume()
	self.Reader:Refresh()
	self.Scheduler:Resume()
	self:_requestPlan(true)
	self:_notify()
	self:Log("CONTROL", "RESUME | selecting from a fresh account snapshot")
	return true
end

function OCController:Stop()
	if self.Destroyed then return false end
	self.Generation += 1
	self.State = "STOPPED"
	self:_cancelReplan()
	self.Scheduler:Stop()
	self.Farming:Halt()
	self.WorldProgression:Halt()
	self.Pets:Halt(true)
	self.EggTravel:Halt(true)
	self.Rewards:Halt(true)
	self.Farming.Mechanics:CancelRewardTransport()
	self.AntiAFK:Halt("Stopped")
	self.Plan = nil
	self.Error = nil
	self.Brain:Reset()
	self.LastObjectiveId = nil
	self:_notify()
	self:Log("CONTROL", "STOP | objective and pending analysis cleared; account reader remains available")
	return true
end

function OCController:Destroy()
	if self.Destroyed then return end
	self:Stop()
	self.Destroyed = true
	if self.AccountLogThread then pcall(task.cancel, self.AccountLogThread) end
	if self.Interface then self.Interface:Destroy() end
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	self.Reader:Destroy()
	self.Farming:Destroy()
	self.EggTravel:Destroy()
	self.Rewards:Destroy()
	self.AntiAFK:Destroy()
	self.Scheduler:Destroy()
	self.Changed:Destroy()
	self:Log("CONTROL", "DESTROY | panel, subscriptions, and reader cleaned up")
end

function OCController:MarkNonPickupReward(pending)
	self.RewardAttributionEpoch = (self.RewardAttributionEpoch or 0) + 1
	self.RewardQuietUntil = math.max(self.RewardQuietUntil or 0, os.clock() + 10)
	self.LastNonPickupReward = pending and pending.Kind or "REWARD_OPERATION"
	-- Discard overlapping models. Known pending/settling credits never become pickup income; later external grants remain uncertain.
	self.Farming.Metrics.Samples = {}
	self.Farming.Metrics.Active = nil
	self.Farming.Metrics.Last = { At = os.clock(), Balances = self.Reader:ReadBalances() }
	self.Farming.PickupEvidence = {}
	self.Farming.Cycle = nil
	self.Farming.Stationary.LastSampleAt = nil
	self.Farming.Stationary.LastSampleArea = nil
end

function OCController:RewardAttributionBlocked()
	return os.clock() < (self.RewardQuietUntil or 0)
		or self.Rewards and self.Rewards.AttributionBlocked and self.Rewards:AttributionBlocked() == true
end

return OCController

end

-- src/OCFoundation/OCInterface.luau
factories["OCInterface"] = function()
--!nonstrict
local AccountPresentation = requireOC("AccountPresentation")
local OCInterface = {}
OCInterface.__index = OCInterface

local function make(className, properties, parent)
	local instance = Instance.new(className)
	for key, value in pairs(properties) do instance[key] = value end
	instance.Parent = parent
	return instance
end

local function count(map)
	if type(map) ~= "table" then return "unavailable" end
	local total = 0 for _ in pairs(map) do total += 1 end
	return tostring(total)
end

function OCInterface.new(controller, playerGui)
	local settings = controller.Config.STATUS_UI_SETTINGS
	local self = setmetatable({ Controller = controller, Connections = {}, Destroyed = false }, OCInterface)
	if not settings.ENABLE_STATUS_UI then return self end
	self.Gui = make("ScreenGui", { Name = "OCFoundationPanel", ResetOnSpawn = false,
		DisplayOrder = 100, ZIndexBehavior = Enum.ZIndexBehavior.Sibling }, playerGui)
	self.Panel = make("Frame", { Name = "Panel", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -16, 0, 16),
		Size = UDim2.fromOffset(settings.PANEL_WIDTH_PIXELS, settings.PANEL_HEIGHT_PIXELS),
		BackgroundColor3 = Color3.fromRGB(20, 24, 35), BorderSizePixel = 0 }, self.Gui)
	make("UICorner", { CornerRadius = UDim.new(0, 14) }, self.Panel)
	make("UIStroke", { Color = Color3.fromRGB(65, 77, 97), Thickness = 1 }, self.Panel)
	make("UIPadding", { PaddingTop = UDim.new(0, 16), PaddingBottom = UDim.new(0, 14),
		PaddingLeft = UDim.new(0, 16), PaddingRight = UDim.new(0, 16) }, self.Panel)
	make("TextLabel", { Name = "Title", Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1,
		Text = "BUBBLE OC  /  PHASE " .. tostring(controller:GetStatus().Phase), TextSize = 18, Font = Enum.Font.GothamBold,
		TextColor3 = Color3.fromRGB(241, 246, 255), TextXAlignment = Enum.TextXAlignment.Left }, self.Panel)
	make("TextLabel", { Name = "Scope", Position = UDim2.fromOffset(0, 29), Size = UDim2.new(1, 0, 0, 20),
		BackgroundTransparency = 1, Text = controller.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE and "Pet team and egg intelligence" or "Intelligent farming, selling and upgrades", TextSize = 12,
		Font = Enum.Font.Gotham, TextColor3 = Color3.fromRGB(162, 178, 203), TextXAlignment = Enum.TextXAlignment.Left }, self.Panel)
	local controls = make("Frame", { Name = "Controls", Position = UDim2.fromOffset(0, 61), Size = UDim2.new(1, 0, 0, 36),
		BackgroundTransparency = 1 }, self.Panel)
	make("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 7), SortOrder = Enum.SortOrder.LayoutOrder }, controls)
	self.Buttons = {}
	for index, action in ipairs({ "Start", "Pause", "Resume", "Stop" }) do
		local button = make("TextButton", { Name = action, LayoutOrder = index, Size = UDim2.new(0.25, -5.25, 1, 0),
			BackgroundColor3 = Color3.fromRGB(50, 60, 79), BorderSizePixel = 0, Text = string.upper(action),
			TextSize = 12, Font = Enum.Font.GothamBold, TextColor3 = Color3.fromRGB(240, 246, 255) }, controls)
		make("UICorner", { CornerRadius = UDim.new(0, 8) }, button)
		self.Buttons[action] = button
		table.insert(self.Connections, button.Activated:Connect(function()
			local ok, reason = controller[action](controller)
			if not ok and reason then controller.Error = reason controller:_notify() end
		end))
	end
	local content = make("ScrollingFrame", { Name = "Status", Position = UDim2.fromOffset(0, 112),
		Size = UDim2.new(1, 0, 1, -112), BackgroundTransparency = 1, BorderSizePixel = 0,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3 }, self.Panel)
	make("UIListLayout", { Padding = UDim.new(0, 12), SortOrder = Enum.SortOrder.LayoutOrder }, content)
	self.Labels = {}
	for index, name in ipairs({ "State", "Objective", "Reason", "Prerequisites", "Farming", "Rates", "Islands", "Balances", "Progression", "Pets", "Inventory", "Worlds", "Upgrades", "Mastery", "Diagnostics" }) do
		self.Labels[name] = make("TextLabel", { Name = name, LayoutOrder = index, Size = UDim2.new(1, -8, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Text = "", TextWrapped = true,
			TextSize = name == "Objective" and 17 or 13, Font = name == "Objective" and Enum.Font.GothamBold or Enum.Font.Gotham,
			TextColor3 = name == "Objective" and Color3.fromRGB(137, 220, 213) or Color3.fromRGB(216, 226, 242),
			TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top }, content)
	end
	local function resize()
		local camera = workspace.CurrentCamera
		if not camera then return end
		local viewport = camera.ViewportSize
		self.Panel.Size = UDim2.fromOffset(math.min(settings.PANEL_WIDTH_PIXELS, math.max(200, viewport.X - 32)),
			math.min(settings.PANEL_HEIGHT_PIXELS, math.max(240, viewport.Y - 64)))
	end
	local cameraConnection
	local function hookCamera()
		if cameraConnection then cameraConnection:Disconnect() end
		if workspace.CurrentCamera then cameraConnection = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(resize) end
		resize()
	end
	table.insert(self.Connections, workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(hookCamera))
	self.DisconnectCamera = function() if cameraConnection then cameraConnection:Disconnect() end end
	hookCamera()
	table.insert(self.Connections, controller.Changed.Event:Connect(function(status) self:Render(status) end))
	self:Render(controller:GetStatus())
	return self
end

function OCInterface:Render(status)
	if self.Destroyed or not self.Gui then return end
	local settings = self.Controller.Config.STATUS_UI_SETTINGS
	local snapshot = status.Snapshot or {}
	local plan = status.Plan
	local objective = plan and plan.Objective
	self.Labels.State.Text = status.State .. "  ·  " .. (snapshot.Status or "NOT_STARTED")
	self.Labels.Objective.Text = objective and objective.Title or (status.State == "STOPPED" and "Press START to analyze your account" or "Analyzing account")
	self.Labels.Reason.Text = objective and objective.Reason or "Waiting for real account data and configured controls."
	self.Labels.Prerequisites.Visible = settings.SHOW_PREREQUISITES and objective ~= nil and #objective.Prerequisites > 0
	self.Labels.Prerequisites.Text = objective and "Prerequisites: " .. table.concat(objective.Prerequisites, " · ") or ""
	local sections = AccountPresentation.Sections(snapshot, self.Controller.Config, settings.MAXIMUM_DISPLAY_ENTRIES)
	self.Labels.Balances.Visible = settings.SHOW_ACCOUNT_BALANCES
	self.Labels.Balances.Text = sections.Balances
	for _, name in ipairs({ "Pets", "Inventory", "Worlds", "Upgrades", "Mastery" }) do
		self.Labels[name].Visible = settings["SHOW_" .. string.upper(name)]
		self.Labels[name].Text = string.upper(name) .. "\n" .. sections[name]
	end
	local pets = status.Pets
	if pets and pets.Enabled then
		local analysis = pets.Analysis
		local team = analysis and analysis.Team
		local egg = analysis and analysis.RecommendedEgg
		self.Labels.Pets.Text ..= "\nNative team: " .. (team and team.Status or "WAITING")
		if team and team.Status == "ESTIMATE" then
			self.Labels.Pets.Text ..= string.format(" | %s %.3f -> %.3f (estimate)", tostring(team.Currency), team.CurrentScore, team.ProjectedScore)
		elseif team then self.Labels.Pets.Text ..= " | " .. tostring(team.Reason) end
		self.Labels.Pets.Text ..= "\nEgg: " .. tostring(egg and egg.Name or "No useful affordable estimate")
			.. " | final odds/total time UNKNOWN\nOC hatch/equip: " .. tostring(self.Controller.Config.PET_SETTINGS.AUTO_HATCH)
			.. "/" .. tostring(self.Controller.Config.PET_SETTINGS.AUTO_EQUIP) .. " | destructive OFF"
		if pets.Fault then self.Labels.Pets.Text ..= "\n" .. pets.Fault end
	end
	self.Labels.Progression.Visible = settings.SHOW_PROGRESSION
	self.Labels.Progression.Text = "Progression: " .. (plan and plan.Progression or "UNDETERMINED")
		.. "\nWorlds: " .. count(snapshot.UnlockedWorlds) .. "   Areas: " .. count(snapshot.UnlockedIslands)
		.. (plan and "\n" .. plan.ProgressionEvidence or "")
	local farming = status.Farming or {}
	local decision = farming.Decision or {}
	self.Labels.Farming.Visible = settings.SHOW_FARMING
	local world = status.WorldProgression and status.WorldProgression.Decision
	self.Labels.Farming.Text = "ACTIVITY: " .. tostring(world and world.Kind or farming.Activity or decision.Mode or decision.Kind or "Waiting")
		.. (world and "\nProgression: " .. tostring(world.Reason) or "")
		.. "\nArea: " .. tostring(farming.Area or "unavailable") .. " | target: " .. tostring(decision.Currency or "unavailable")
		.. "\n" .. tostring(decision.Reason or "Observing accessible game mechanics")
		.. string.format("\nPickups: %d eligible / %d visible; %d unidentified | radius: %s", farming.EligiblePickups or 0, farming.VisiblePickups or 0,
			farming.UnknownPickups or 0, tostring(farming.Radius or "unavailable"))
		.. "\n" .. tostring(farming.CollectionMethod or "") .. "\n" .. tostring(farming.LastConfirmation or "")
		.. "\nObserved new models: " .. tostring(farming.ObservedSpawns or 0) .. "; respawn observations: " .. tostring(farming.RespawnObservations or 0)
		.. (farming.Scan and string.format("\nNative registry: %s; active IDs=%d, positions=%d; Chunker folders=%d", farming.Scan.RegistryAvailable and "available" or "unavailable", farming.Scan.RegistryActiveIds, farming.Scan.PositionsResolved, farming.Scan.ChunkerFolders) or "")
		.. (farming.CollectionBlocker and "\nCollection unavailable: " .. farming.CollectionBlocker or "")
		.. (farming.Stationary and string.format("\nStationary batches: %d requests; %d credited windows, %d uncredited\n%s", farming.Stationary.Requests,
			farming.Stationary.CreditWindows, farming.Stationary.UncreditedWindows, farming.Stationary.Blocker or "Continuous discovery; server acceptance remains unknown") or "")
	local rates = {}
	for mode, entry in pairs(farming.Rates or {}) do
		if mode == "PICKUPS" and farming.Rates.STATIONARY then continue end
		local values = {}
		for currency, value in pairs(entry.PerMinute) do table.insert(values, string.format("%.2f %s/min", value, currency)) end
		table.sort(values)
		table.insert(rates, mode .. " (" .. string.format("%.1fs", entry.Seconds) .. "): " .. (entry.Ready and (#values > 0 and table.concat(values, ", ") or "0 observed income") or "sampling"))
	end
	table.sort(rates)
	self.Labels.Rates.Visible = settings.SHOW_FARMING_RATES
	self.Labels.Rates.Text = "OBSERVED RATES (external rewards may affect attribution)\n" .. (#rates > 0 and table.concat(rates, "\n") or "No earning samples yet")
	local islands = {}
	for index, candidate in ipairs(decision.IslandCandidates or {}) do
		if index > settings.MAXIMUM_DISPLAY_ENTRIES then break end
		table.insert(islands, string.format("%s: %s %s/min | %s", candidate.Name,
			candidate.PerMinute and string.format("%.2f", candidate.PerMinute) or "unknown", candidate.Currency, candidate.Evidence))
	end
	self.Labels.Islands.Visible = settings.SHOW_ISLAND_CANDIDATES and #islands > 0
	self.Labels.Islands.Text = "ELIGIBLE ISLANDS\n" .. table.concat(islands, "\n")
	local diagnostics = {}
	if status.Error then table.insert(diagnostics, status.Error) end
	if farming.Error then table.insert(diagnostics, farming.Error) end
	if snapshot.UnavailableFields and #snapshot.UnavailableFields > 0 then
		table.insert(diagnostics, "Unavailable fields: " .. table.concat(snapshot.UnavailableFields, ", "))
	end
	for _, message in ipairs(snapshot.Diagnostics or {}) do table.insert(diagnostics, message) end
	self.Labels.Diagnostics.Visible = settings.SHOW_DIAGNOSTICS and #diagnostics > 0
	self.Labels.Diagnostics.Text = table.concat(diagnostics, "\n")
	local enabled = { Start = status.State == "STOPPED", Pause = status.State == "RUNNING",
		Resume = status.State == "PAUSED", Stop = status.State ~= "STOPPED" }
	for name, button in pairs(self.Buttons) do
		button.Interactable = enabled[name]
		button.AutoButtonColor = enabled[name]
		button.TextTransparency = enabled[name] and 0 or 0.55
		button.BackgroundColor3 = name == "Start" and enabled[name] and Color3.fromRGB(32, 121, 111) or Color3.fromRGB(50, 60, 79)
	end
end

function OCInterface:Destroy()
	if self.Destroyed then return end
	self.Destroyed = true
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	if self.DisconnectCamera then self.DisconnectCamera() end
	if self.Gui then self.Gui:Destroy() end
end

return OCInterface

end

-- src/OCFoundation/PetManager.luau
factories["PetManager"] = function()
--!nonstrict
-- Cooperative Phase 4 coordinator. Observations and action slices use the existing
-- Brain/scheduler; no hatching timer, movement loop or alternate account reader.
local Policy = requireOC("PetPolicy")
local HatchManager = requireOC("HatchManager")
local ProgressionGraph = requireOC("ProgressionGraph")
local PetManager = {}
PetManager.__index = PetManager

local function cloneRecords(inv)
	local result = {}
	for id, pet in pairs(inv.ById) do result[id] = table.clone(pet) end
	return result
end

local function copyFacts(value)
	if type(value) ~= "table" then return value end
	local result = {} for key, entry in pairs(value) do result[key] = copyFacts(entry) end
	return result
end

function PetManager.new(controller)
	local self = setmetatable({ Controller = controller, Config = controller.Config, EquipCommands = 0 }, PetManager)
	self.Hatch = HatchManager.new(controller)
	controller.Farming.Mechanics.HatchLocationProvider = function(area) return self:AtOwnedLocation(area) end
	controller.Farming.Mechanics.PetLocationOwnerProvider = function() return self.Hatch.Location ~= nil end
	return self
end

function PetManager:Fresh()
	local c = self.Controller
	local snapshot = c.Reader:GetSnapshot()
	local raw = c.Reader:GetLiveProfile()
	if raw then
		snapshot.Balances = c.Reader:ReadBalances()
		snapshot.UnlockedWorlds, snapshot.UnlockedIslands = raw.WorldsUnlocked, raw.AreasUnlocked
		-- Reserve all permanent progression definitions, independently of selected
		-- travel destinations or whether progression execution is enabled.
		local config = table.clone(self.Config) config.WORLD_SETTINGS = table.clone(config.WORLD_SETTINGS)
		config.WORLD_SETTINGS.SELECTED_WORLDS = {}
		snapshot.ProgressionGraph = ProgressionGraph.Build(config, snapshot, c.Knowledge:Get("Worlds"), snapshot.AvailableProgression)
	end
	local context = c.Knowledge:PetContext(snapshot, c.Plan, c.Farming.Tracker)
	return snapshot, context
end

function PetManager:Uncertain(reason)
	self.Fault = reason
	self.Controller:Log("PET][BLOCKER", reason)
	if self.Attempt and not self.Attempt.Ended then self:FinishAttempt("PARTIAL_OR_UNCONFIRMED", reason) end
end

function PetManager:FinishAttempt(status, reason)
	local attempt = self.Attempt
	if not attempt or attempt.Ended then return end
	attempt.Ended, attempt.Status, attempt.Reason = true, status, reason
	local _, context = self:Fresh()
	local inv = context.Inventory
	attempt.ActualTeamIndex, attempt.AfterIds = inv and inv.TeamIndex, inv and table.clone(inv.Team)
	attempt.AfterScore = inv and context.ScoreTeam and context.ScoreTeam(inv.Team) or nil
	attempt.ConfirmedTarget = inv ~= nil and inv.TeamIndex == attempt.TeamIndex and Policy.SameTeam(inv.Team, attempt.TargetIds or {})
	attempt.ActualPets = inv and context.ScoreTeam and Policy.Describe(self.Config, context, inv.Team) or nil
	attempt.Attribution = "Received LocalData membership/native client total; manual/external changes cannot be excluded; earnings gain unmeasured"
	self.Controller:Log("PET][EQUIP_RESULT", string.format("%s | team=%s -> %s | before IDs=%s | received IDs=%s | predicted %s -> %s; received native score=%s | commands=%d | %s | no more equip requests; earnings impact unmeasured",
		status, tostring(attempt.TeamIndex), tostring(attempt.ActualTeamIndex), table.concat(attempt.BeforeIds or {}, ","),
		attempt.AfterIds and table.concat(attempt.AfterIds, ",") or "UNKNOWN", tostring(attempt.BeforeScore or "UNKNOWN"), tostring(attempt.ProjectedScore or "UNKNOWN"),
		tostring(attempt.AfterScore or "UNKNOWN"), self.EquipCommands, reason))
end

function PetManager:PrintTeam()
	if not self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE then return false, "Pet intelligence disabled" end
	self:Analyze(true)
	self.Controller:Log("PET][TEAM_DETAILS", Policy.TeamText(self.Report.Team, true), true)
	return true
end

function PetManager:Observe()
	local raw = self.Controller.Reader:GetLiveProfile()
	self.Hatch:Observe(raw) -- A missing profile must still expire an outstanding acknowledgement deadline.
	if self.Hatch.LastResult and self.Hatch.LastResult ~= self.LastHatchEvaluated then
		self.LastHatchEvaluated = self.Hatch.LastResult
		local _, context = self:Fresh()
		local inv = context.Inventory
		local actual = inv and context.ScoreTeam and context.ScoreTeam(inv.Team)
		self.Hatch.LastResult.UsefulnessBaselineScore = actual
		self.Hatch.LastResult.UsefulnessBaselineIds = inv and table.clone(inv.Team)
		for _, change in ipairs(self.Hatch.LastResult.Changes or {}) do
			local pet = context.Inventory and context.Inventory.ById[change.Id]
			local score = pet and context.PetScore and context.PetScore(pet)
			local received = pet and context.ScoreReceivedPet and context.ScoreReceivedPet(change.Id, inv.Team)
			if self.Hatch.LastResult.Status == "INVENTORY_GAIN_OBSERVED" and Policy.Finite(actual) and Policy.Finite(received) then
				change.ActualIncrement = math.max(0, received - actual)
				change.Usefulness = change.ActualIncrement > 1e-6 and "USEFUL_NATIVE_TEAM_ESTIMATE" or "NO_CURRENT_TEAM_IMPROVEMENT"
			else change.Usefulness = "UNKNOWN" end
			if self.Hatch.LastResult.Status == "INVENTORY_GAIN_OBSERVED" and Policy.Finite(score)
				and (not self.Hatch.BestHatch or self.Hatch.BestHatch.Currency ~= context.Currency or score > self.Hatch.BestHatch.Score) then
				self.Hatch.BestHatch = { Id = change.Id, Name = change.Name, Score = score, Currency = context.Currency,
					Quantity = change.Quantity, Evidence = "Native score of actually received inventory gain; attribution qualified" }
			end
		end
		self.Controller:Log("HATCH_RESULT", self.Hatch:ResultText())
	end
	if self.Hatch.Fault then self.Fault = self.Hatch.Fault end
	local attempt = self.Attempt
	if attempt and not attempt.Ended then
		local inv = Policy.Inventory(raw)
		if os.clock() >= attempt.Deadline then self:Uncertain("One-time equipment wall-clock deadline expired; inspect partial/unknown team; no retry")
		elseif inv and (inv.TeamIndex ~= attempt.TeamIndex or not self.PendingEquip and not Policy.SameTeam(inv.Team, attempt.ExpectedIds)) then
			self:Uncertain("Manual/external team mismatch; frozen one-time plan abandoned")
		elseif not self.Config.PET_SETTINGS.AUTO_EQUIP or self.Config.PET_SETTINGS.AUTO_HATCH
			or not self.Config.PET_SETTINGS.EQUIP_OWNED_TEAM_ONCE then self:Uncertain("One-time equipment authorization changed; no further commands") end
	end
	if self.Transaction and not self.PendingEquip and os.clock() >= self.Transaction.Deadline then
		self:Uncertain("Equipment replacement continuation expired; inspect the actual partial team. No automatic restoration or retry")
		self.Transaction = nil
	end
	local pending = self.PendingEquip
	if not pending then return end
	local inv = Policy.Inventory(raw)
	if inv and inv.TeamIndex == pending.TeamIndex and Policy.SameTeam(inv.Team, pending.ExpectedIds) then
		self.PendingEquip = nil
		self.LastEquipment = { Status = "EQUIPPED_IDS_OBSERVED", Command = pending.Command, Id = pending.Id,
			BeforeIds = pending.BeforeIds, AfterIds = table.clone(inv.Team), TeamIndex = inv.TeamIndex,
			Attribution = "Exact received multiplicity observed; manual/external activity cannot be excluded" }
		self.Controller:Log("PET][VERIFIED", pending.Command .. " [" .. pending.Id .. "] | received IDs=" .. table.concat(inv.Team, ",") .. "; team=" .. tostring(inv.TeamIndex))
		if pending.Command == "EquipPet" then self.Transaction = nil end
		if attempt and not attempt.Ended then
			attempt.ExpectedIds = table.clone(inv.Team)
			if pending.Command == "EquipPet" then attempt.Step += 1 end
			if Policy.SameTeam(inv.Team, attempt.TargetIds) then self:FinishAttempt("TARGET_MEMBERSHIP_OBSERVED", "Frozen target multiplicity confirmed in LocalData") end
		end
		return
	end
	if attempt and not attempt.Ended and inv and (inv.TeamIndex ~= pending.TeamIndex
		or not Policy.SameTeam(inv.Team, pending.BeforeIds)) then
		self:Uncertain("Unexpected received equipment result/multiplicity; no retry or restoration")
		self.LastEquipment = { Status = "MISMATCH", AfterIds = table.clone(inv.Team), TeamIndex = inv.TeamIndex }
		self.PendingEquip, self.Transaction = nil, nil return
	end
	if os.clock() >= pending.Deadline then
		self:Uncertain("Equipment acknowledgement timed out; team result unknown. No retry; command budget retained")
		self.LastEquipment = { Status = "UNCONFIRMED", Command = pending.Command, Id = pending.Id }
		self.PendingEquip, self.Transaction = nil, nil
	end
end

function PetManager:State()
	return { Pending = self.Hatch.Pending or self.PendingEquip, Fault = self.Fault, Location = self.Hatch.Location,
		HatchOnce = self.Hatch.Once,
		SessionEnded = self.Hatch:Ended(), RequestCost = self.Hatch.RequestCost, RequestedHatches = self.Hatch.RequestedHatches,
		EquipCommands = self.EquipCommands, Attempt = self.Attempt, EquipmentContinuation = self.Transaction and not self.PendingEquip and not self.Fault and not (self.Attempt and self.Attempt.Ended)
			and { Kind = "TEAM_ADD", Transaction = self.Transaction, OwnsLocation = self.Hatch.Location ~= nil } or nil }
end

function PetManager:Analyze(force)
	local snapshot, context = self:Fresh()
	if force or not self.Report or os.clock() - (self.AnalysisAt or -math.huge) >= self.Config.PET_SETTINGS.ANALYSIS_INTERVAL_SECONDS then
		self.Report = self.Controller.Brain:AnalyzePets(snapshot, context)
		self.Report.Account = { Name = self.Controller.Reader.Player and self.Controller.Reader.Player.Name,
			UserId = self.Controller.Reader.Player and self.Controller.Reader.Player.UserId }
		self.AnalysisAt = os.clock()
		local team = self.Report.Team
		local message = team.Status == "ESTIMATE" and string.format("%s team: %d records / %d pets; equipped=%d; native score %.3f -> %.3f (estimate)",
			tostring(team.Currency), team.RecordCount, team.Quantity, team.EquippedCount, team.CurrentScore, team.ProjectedScore)
			or "Team analysis UNKNOWN: " .. tostring(team.Reason)
		message ..= " | hatch=" .. tostring(self.Config.PET_SETTINGS.AUTO_HATCH) .. "; equip=" .. tostring(self.Config.PET_SETTINGS.AUTO_EQUIP)
		if self.LastAnalysisMessage ~= message then self.Controller:Log("PET][ANALYSIS", message) self.LastAnalysisMessage = message end
		local eggPlan = Policy.EggPlanText(self.Config, self.Report, false)
		if self.LastEggPlan ~= eggPlan then
			self.Controller:Log("EGG_PLAN", eggPlan)
			if self.Config.HATCH_SETTINGS.LOG_EGG_DETAILS then self.Controller:Log("EGG_DETAILS", Policy.EggPlanText(self.Config, self.Report, true), true) end
			self.LastEggPlan = eggPlan
		end
		local teamMessage = Policy.TeamText(team, false)
		local details = Policy.TeamText(team, true)
		if self.LastTeamPlan ~= details then
			self.Controller:Log("PET][TEAM_PLAN", teamMessage)
			if self.Config.PET_SETTINGS.LOG_TEAM_DETAILS then self.Controller:Log("PET][TEAM_DETAILS", details, true) end
			self.LastTeamPlan = details
		end
	end
	return context
end

function PetManager:Select(plan)
	if not self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE then return false end
	self:Observe()
	if self.Hatch:Ended() and not self.Hatch.Pending then
		local presentation = self.Controller.Knowledge:Get("HatchPresentation")
		local ok, active = pcall(function() return presentation:IsHatching() end)
		if self.Hatch.Location and (not ok or active ~= false) and os.clock() - self.Hatch.StartedAt < self.Config.HATCH_SETTINGS.MAXIMUM_SESSION_SECONDS then
			self.Decision = { Kind = "OBSERVE", OwnsLocation = true, Reason = "Bounded session ended; waiting for native hatch presentation before releasing location" }
			return true, self.Decision
		end
		self.Hatch.Location = nil
	end
	self:Analyze(false)
	if not self.Config.PET_SETTINGS.AUTO_HATCH and not self.Config.PET_SETTINGS.AUTO_EQUIP then
		self.Decision = { Kind = "WAIT", OwnsLocation = false, Reason = "Read-only pet intelligence; hatch/equipment disabled" }
		return false, self.Decision
	end
	-- Action recommendations always use fresh native projections, not cached diagnostics.
	local snapshot, context = self:Fresh()
	local report = self.Controller.Brain:AnalyzePets(snapshot, context)
	local decision = self.Controller.Brain:PlanPets(report, context, self:State())
	if decision.Kind == "TEAM_ATTEMPT_START" or decision.Kind == "TEAM_ATTEMPT_END" then
		local team = report.Team
		self.Attempt = { Steps = decision.Steps or {}, Step = 1, TeamIndex = context.Inventory.TeamIndex,
			BeforeIds = table.clone(context.Inventory.Team), ExpectedIds = table.clone(context.Inventory.Team),
			TargetIds = table.clone(team.ProposedIds), BeforeScore = team.CurrentScore, ProjectedScore = team.ProjectedScore,
			Currency = context.Currency, MaxEquipped = context.MaxEquipped, BeforePets = team.CurrentPets,
			UserId = self.Controller.Reader.Player and self.Controller.Reader.Player.UserId,
			Deadline = os.clock() + self.Config.PET_SETTINGS.MAXIMUM_EQUIP_ATTEMPT_SECONDS }
		if decision.Kind == "TEAM_ATTEMPT_END" then self:FinishAttempt("NO_ACTION", decision.Reason)
		else self.Controller:Log("PET][TEAM_PLAN", "One authorized frozen owned-team attempt | commands required=" .. decision.RequiredCommands .. "; each result must be observed; no hatching/spending") end
		decision = self.Controller.Brain:PlanPets(report, context, self:State())
	end
	if decision.Kind == "HATCH" then
		self.Hatch.StartedAt = self.Hatch.StartedAt or os.clock()
		self.Hatch.UserId = self.Hatch.UserId or self.Controller.Reader.Player.UserId
		for _, egg in ipairs(context.Eggs) do
			if egg.Name == decision.EggName then self.Hatch.Location = self.Hatch.Location or
				{ EggName = egg.Name, Model = egg.Model, World = egg.World, Island = egg.Island } break end
		end
	end
	self.Decision = decision
	if decision.Kind == "WAIT" and not decision.OwnsLocation and not self.PendingEquip then self.Hatch.Location = nil end
	if decision.Reason and (decision.OwnsLocation or self.Config.PET_SETTINGS.AUTO_HATCH or self.Config.PET_SETTINGS.AUTO_EQUIP) then
		if self.LastReason ~= decision.Reason then self.Controller:Log("PET][BLOCKER", decision.Reason) self.LastReason = decision.Reason end
	end
	return decision.Kind ~= "WAIT" or decision.OwnsLocation, decision
end

function PetManager:AtOwnedLocation(area)
	local location = self.Hatch.Location
	if not location or not area or self.Controller.State ~= "RUNNING" or not self.Config.PET_SETTINGS.AUTO_HATCH
		or not self.Config.HATCH_SETTINGS.ENABLE_BACKGROUND_PICKUPS or self.Hatch:Ended() and not self.Hatch.Pending then return false end
	-- Manual movement updates eligible current area; never reposition the character.
	local model, root = location.Model, self.Controller.Farming.Tracker:Root()
	local part = model and model.Parent and model:IsDescendantOf(workspace) and model:FindFirstChild("Root")
	return part ~= nil and part:IsA("BasePart") and root ~= nil and (part.Position - root.Position).Magnitude <= 16
		and (location.Island or location.World) == area.Name and location.World == area.World
		and self.Controller.Farming.Mechanics:Unlocked(area.World, area.Name)
end

function PetManager:Prepare(decision, token)
	local config, c = self.Config, self.Controller
	if self.Fault or self.PendingEquip or self.Hatch.Pending then return nil, nil, nil, "Pending or uncertain result blocks dispatch" end
	if not config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE or not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS
		or config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then return nil, nil, nil, "Pet execution disabled" end
	local snapshot, context = self:Fresh()
	local inv = context.Inventory
	if not inv then return nil, nil, nil, context.Error end
	local function allowed()
		return c.State == "RUNNING" and (not token or not token:CheckCancelled())
	end
	if decision.Kind == "TEAM" or decision.Kind == "TEAM_ADD" then
		if self.Hatch.Once then return nil, nil, nil, "Isolated single-hatch controller never authorizes equipment" end
		if not config.PET_SETTINGS.AUTO_EQUIP then return nil, nil, nil, "Team changes disabled" end
		if config.PET_SETTINGS.EQUIP_OWNED_TEAM_ONCE and os.clock() < (self.NextEquipAt or -math.huge) then return nil, nil, nil, "OC equipment request pacing; no native server cooldown assumed" end
		if config.PET_SETTINGS.EQUIP_OWNED_TEAM_ONCE then
			local attempt = self.Attempt
			if not attempt or attempt.Ended then return nil, nil, nil, "One-time equipment attempt not active" end
			if os.clock() >= attempt.Deadline or context.Currency ~= attempt.Currency or context.MaxEquipped ~= attempt.MaxEquipped
				or c.Reader.Player.UserId ~= attempt.UserId or config.PET_SETTINGS.AUTO_HATCH then
				self:Uncertain("Account/objective/capacity/authorization changed during one-time attempt") return nil, nil, nil, self.Fault
			end
			local step = attempt.Steps[attempt.Step]
			if decision.Kind == "TEAM" and decision ~= step or decision.Kind == "TEAM_ADD" and self.Transaction ~= step then return nil, nil, nil, "Stale equipment step" end
			local desired = Policy.Counts(attempt.TargetIds)
			for id, count in pairs(desired) do
				local pet = inv.ById[id]
				if not pet or count > (pet.Amount or 1) then self:Uncertain("Frozen target ownership/quantity changed") return nil, nil, nil, self.Fault end
			end
		end
		local transaction = decision.Kind == "TEAM_ADD" and self.Transaction or decision
		if not transaction or inv.TeamIndex ~= transaction.TeamIndex then return nil, nil, nil, "Active team changed" end
		local expected = table.clone(transaction.BeforeIds)
		if decision.Kind == "TEAM_ADD" and transaction.RemoveId then table.remove(expected, table.find(expected, transaction.RemoveId)) end
		if not Policy.SameTeam(inv.Team, expected) then
			if self.Transaction then self:Uncertain("Manual/external equipment change interrupted replacement; no further command") self.Transaction = nil end
			return nil, nil, nil, "Equipped team changed; recompute before action"
		end
		local add, remove = inv.ById[transaction.AddId], inv.ById[transaction.RemoveId]
		if not add or add.Super or not (context.Pets or {})[add.Name] or not context.Pets[add.Name].Rarity then return nil, nil, nil, "Unsupported or unavailable replacement" end
		if table.find(config.PET_SETTINGS.PROTECTED_PET_IDS, add.Id) then self:Uncertain("Explicitly protected candidate cannot be touched") return nil, nil, nil, self.Fault end
		local final = transaction.AfterIds
		local score = context.ScoreTeam and context.ScoreTeam(final)
		local originalScore = context.ScoreTeam and context.ScoreTeam(transaction.BeforeIds)
		if not Policy.Finite(score) or not Policy.Finite(originalScore) or score <= originalScore + 1e-6 then return nil, nil, nil, "Replacement benefit no longer supported" end
		local counts = Policy.Counts(final)
		for id, count in pairs(counts) do if not inv.ById[id] or count > (inv.ById[id].Amount or 1) then return nil, nil, nil, "Owned replacement quantity changed" end end
		if not Policy.Finite(context.MaxEquipped) or #final > context.MaxEquipped then return nil, nil, nil, "Native team capacity changed" end
		local command, id, after = "EquipPet", add.Id, table.clone(final)
		if decision.Kind == "TEAM" and transaction.RemoveId then
			if not remove or remove.Super or Policy.Protected(config, remove, (context.Pets or {})[remove.Name]) then
				if self.Attempt then self:Uncertain("Protected pet cannot be removed: " .. tostring(remove and Policy.Protection(config, remove, context.Pets[remove.Name]))) end
				return nil, nil, nil, "Protected pet cannot be removed"
			end
			command, id, after = "UnequipPet", remove.Id, table.clone(inv.Team)
			table.remove(after, table.find(after, remove.Id))
		end
		local needed = command == "UnequipPet" and 2 or 1
		if self.EquipCommands + needed > config.PET_SETTINGS.MAXIMUM_SESSION_EQUIP_COMMANDS then return nil, nil, nil, "Equipment command budget exhausted" end
		if not allowed() then return nil, nil, nil, "Cancelled before dispatch" end
		local guarded, guardReason = c.Farming.Mechanics:Guard()
		if not guarded or not allowed() then return nil, nil, nil, guardReason or "Cancelled before dispatch" end
		-- Guards/helpers may yield. Compare the actual account records and membership
		-- again, with no yield between this final check, ledger creation and dispatch.
		local live = c.Reader:GetLiveProfile()
		local liveInv = Policy.Inventory(live)
		local attempt = self.Attempt
		local authorizationChanged = not config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE or not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS
			or config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST or not config.PET_SETTINGS.AUTO_EQUIP
			or table.find(config.PET_SETTINGS.PROTECTED_PET_IDS, add.Id) ~= nil
			or command == "UnequipPet" and Policy.Protected(config, remove, context.Pets[remove.Name])
			or self.EquipCommands + needed > config.PET_SETTINGS.MAXIMUM_SESSION_EQUIP_COMMANDS
			or attempt and (attempt.Ended or os.clock() >= attempt.Deadline or not config.PET_SETTINGS.EQUIP_OWNED_TEAM_ONCE
				or config.PET_SETTINGS.AUTO_HATCH or c.Reader.Player.UserId ~= attempt.UserId
				or Policy.Currency(config, c.Plan) ~= attempt.Currency)
		if not liveInv or liveInv.TeamIndex ~= inv.TeamIndex or not Policy.SameTeam(liveInv.Team, inv.Team)
			or not Policy.Equal(live, context.AccountFacts) or authorizationChanged or not allowed() then
			if self.Attempt then self:Uncertain("Account/equipment/protection changed during final native guards") end
			return nil, nil, nil, "Actual account changed before equipment dispatch"
		end
		self.EquipCommands += 1
		self.NextEquipAt = os.clock() + config.PET_SETTINGS.MINIMUM_EQUIP_COMMAND_INTERVAL_SECONDS
		if command == "UnequipPet" then
			transaction.Deadline = os.clock() + 2 * config.PET_SETTINGS.EQUIP_CONFIRMATION_TIMEOUT_SECONDS
			self.Transaction = transaction
		end
		self.PendingEquip = { Command = command, Id = id, BeforeIds = table.clone(inv.Team), ExpectedIds = after,
			TeamIndex = inv.TeamIndex, Deadline = os.clock() + config.PET_SETTINGS.EQUIP_CONFIRMATION_TIMEOUT_SECONDS }
		return command, id
	end
	if decision.Kind ~= "HATCH" or not config.PET_SETTINGS.AUTO_HATCH or self.Hatch:Ended() then return nil, nil, nil, "Hatch authorization/session ended" end
	if self.Hatch.Once then
		local reason = Policy.HatchIsolation(config)
		if reason then return nil, nil, nil, reason end
	end
	local authorization = copyFacts(config)
	local accountId = c.Reader.Player.UserId
	if self.Hatch.UserId and self.Hatch.UserId ~= accountId then return nil, nil, nil, "Hatch account changed; no dispatch" end
	local report = c.Brain:AnalyzePets(snapshot, context)
	local fresh = c.Brain:PlanPets(report, context, self:State())
	if fresh.Kind ~= "HATCH" or fresh.EggName ~= decision.EggName then return nil, nil, nil, "Fresh useful hatch/budget decision unavailable" end
	local egg for _, candidate in ipairs(context.Eggs) do if candidate.Name == decision.EggName then egg = candidate break end end
	if not egg or not egg.InRange then return nil, nil, nil, "Manual approach within native egg range required (unopened 6.5/opened 16 studs); location retained without teleport" end
	local settings = config.HATCH_SETTINGS
	local count = math.min(decision.Count, fresh.Count)
	if egg.Opened ~= true then count = math.min(count, 1) end -- Native first hatch is one egg.
	local time, presentation = c.Knowledge:Get("Time"), c.Knowledge:Get("HatchPresentation")
	local scripts = c.Reader.Player and c.Reader.Player:FindFirstChild("PlayerScripts")
	local client = scripts and scripts:FindFirstChild("ClientScript")
	local status = client and client:FindFirstChild("GetAutoHatchStatus")
	if not time or type(time.now) ~= "function" or not presentation or type(presentation.IsHatching) ~= "function"
		or not status or not status:IsA("BindableFunction") then return nil, nil, nil, "Native hatch/time/auto-hatch guards unavailable" end
	local okAuto, active = pcall(function() return status:Invoke() end)
	local okHatch, hatching = pcall(function() return presentation:IsHatching() end)
	local okTime, now = pcall(time.now)
	local nextAt = c.Reader.Player:GetAttribute("NextEggOpenAt")
	if not okAuto or active ~= nil or not okHatch or hatching ~= false then return nil, nil, nil, "Native auto hatch/presentation active or unknown; no competing hatch command" end
	if not okTime or not Policy.Finite(now) or nextAt ~= nil and not Policy.Finite(nextAt)
		or nextAt and nextAt > now or os.clock() < (self.Hatch.NextRequestAt or 0) then return nil, nil, nil, "Native/session hatch cooldown or unknown time" end
	-- Refresh again after the native BindableFunction; it may yield. Re-evaluate
	-- current modifiers, native cost, free space, balances and progression reserve.
	snapshot, context = self:Fresh()
	inv = context.Inventory
	report = c.Brain:AnalyzePets(snapshot, context)
	fresh = c.Brain:PlanPets(report, context, self:State())
	if not inv or fresh.Kind ~= "HATCH" or fresh.EggName ~= egg.Name then return nil, nil, nil, "Account/authorization changed during native hatch guards" end
	local currentEgg for _, candidate in ipairs(context.Eggs) do if candidate.Name == egg.Name then currentEgg = candidate break end end
	if not currentEgg or currentEgg.Model ~= egg.Model or not currentEgg.InRange then return nil, nil, nil, "Native egg location changed during guards" end
	egg, count = currentEgg, math.min(count, fresh.Count)
	local raw = c.Reader:GetLiveProfile()
	if not raw or type(raw.EggsOpened) ~= "table" then return nil, nil, nil, "Native egg counter map unavailable" end
	local counter = raw.EggsOpened[egg.Name] or 0
	if not Policy.Finite(counter) or counter % 1 ~= 0 then return nil, nil, nil, "Native egg counter unavailable" end
	local names = {} for _, entry in ipairs(egg.Pool) do names[entry.Item.Name] = true end
	if not allowed() then return nil, nil, nil, "Cancelled before dispatch" end
	local guarded, guardReason = c.Farming.Mechanics:Guard()
	if not guarded or not allowed() then return nil, nil, nil, guardReason or "Cancelled before dispatch" end
	-- Recheck native guards/cost after the general guard, which may yield. No
	-- invocation, animation or cost deduction is accepted as a received pet.
	local finalAutoOK, finalAuto = pcall(function() return status:Invoke() end)
	local finalHatchOK, finalHatch = pcall(function() return presentation:IsHatching() end)
	local finalTimeOK, finalTime = pcall(time.now)
	local stats = c.Knowledge:Get("StatsUtil")
	local worldUtil = c.Knowledge:Get("WorldUtil")
	local costOK, finalCost = pcall(function() return stats:GetEggCost(c.Reader.Player, context.AccountFacts, egg.Name) end)
	local worldOK, finalWorld = pcall(function() return worldUtil:GetPlayerWorld(c.Reader.Player) end)
	local capacityOK, capacityAllows = pcall(function()
		local facts = context.AccountFacts
		local digital = stats:HasDigitalStorage(facts)
		local free = stats:GetMaxPetStorage(facts) - stats:GetUsedPetStorage(facts)
		local maxHatches = stats:GetMaxEggHatches(facts)
		return stats:IsInventoryFull(facts) == false and type(digital) == "boolean" and Policy.Finite(maxHatches) and maxHatches >= count
			and (digital and count == 1 or not digital and free >= count)
	end)
	local live = c.Reader:GetLiveProfile()
	local finalNextAt = c.Reader.Player:GetAttribute("NextEggOpenAt")
	local part = egg.Model.Parent and egg.Model:IsDescendantOf(workspace) and egg.Model:FindFirstChild("Root")
	local root = c.Farming.Tracker:Root()
	if not allowed() or self.Hatch:Ended() or self.Hatch.Pending or self.PendingEquip or self.Fault
		or not Policy.Equal(config, authorization) or c.Reader.Player.UserId ~= accountId
		or not live or not Policy.Equal(live, context.AccountFacts) or live[egg.Cost.Currency] ~= snapshot.Balances[egg.Cost.Currency]
		then return nil, nil, nil, "Account/authorization changed during final hatch guards; no request" end
	if not capacityOK or capacityAllows ~= true then return nil, nil, nil, "Native inventory capacity changed during final guards; no request" end
	if not costOK or not Policy.Equal(finalCost, egg.Cost) or not worldOK or finalWorld ~= egg.World
		or not part or not part:IsA("BasePart") or not root or (part.Position - root.Position).Magnitude > egg.Range
		or egg.Model:GetAttribute("Unlocked") ~= egg.Unlocked then return nil, nil, nil, "Native egg/cost/range changed during final guards; approach manually" end
	if not finalAutoOK or finalAuto ~= nil or not finalHatchOK or finalHatch ~= false
		or not finalTimeOK or not Policy.Finite(finalTime) or finalNextAt ~= nil and not Policy.Finite(finalNextAt)
		or finalNextAt and finalNextAt > finalTime then return nil, nil, nil, "Native hatch/cooldown changed during final guards; no request" end
	if self.Hatch.Once and (count ~= 1 or Policy.HatchIsolation(config)) then return nil, nil, nil, "Single hatch authorization changed" end
	self.Hatch.UserId = accountId
	self.Hatch.StartedAt = self.Hatch.StartedAt or os.clock()
	self.Hatch.RequestedHatches += count self.Hatch.RequestCost += egg.Cost.Amount * count
	self.Hatch.NextRequestAt = os.clock() + math.max(settings.MINIMUM_REQUEST_INTERVAL_SECONDS, egg.Duration)
	local balances = {} for _, currency in ipairs({ "Coins", "Gems", "Tickets", "Pearls" }) do if Policy.Finite(live[currency]) then balances[currency] = live[currency] end end
	self.Hatch.Pending = { Before = cloneRecords(inv), Pool = names, Count = count, Counter = counter,
		EggName = egg.Name, Currency = egg.Cost.Currency, BeforeBalance = live[egg.Cost.Currency], BeforeBalances = balances,
		TeamBefore = table.clone(inv.Team), TeamIndex = inv.TeamIndex, Deadline = os.clock() + settings.CONFIRMATION_TIMEOUT_SECONDS }
	return "HatchEgg", egg.Name, count
end

function PetManager:Definition(decision, generation)
	local c = self.Controller
	return { Id = "OC_GAMEPLAY", Owner = "PETS", Generation = generation, Priority = 60,
		CanRun = function() return c.State == "RUNNING" and generation == c.Generation end,
		Execute = function(token)
			if token:CheckCancelled() then return nil end
			local owns, fresh = self:Select(c.Plan)
			if not owns then return { Reason = "Pet intent ended" } end
			if fresh.Kind == "HATCH" or fresh.Kind == "TEAM" or fresh.Kind == "TEAM_ADD" then
				local sent, reason = c.Farming.Mechanics:PetAction(self, fresh, token)
				self.LastAction = { Requested = sent, Reason = reason }
				if not sent and self.LastDispatchBlocker ~= reason then c:Log("PET][BLOCKER", reason) self.LastDispatchBlocker = reason end
			end
			self:Observe()
			local area = c.Farming.Tracker.Current
			if self:AtOwnedLocation(area) and c.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS then
				local cluster = c.Farming.Tracker:Cluster("Coins")
				if cluster then
					c.Farming.Stationary:Collect({ Mode = "HATCH_PICKUPS", Cluster = cluster, HatchSpending = self.Hatch.Pending ~= nil }, token,
						function() return self:AtOwnedLocation(c.Farming.Tracker.Current) end)
				end
			end
			if not token:CheckCancelled() then task.wait(1) end -- Cooperative slice; prevents an unconfirmed/approach hot loop.
			return { Reason = "Pet observation/action slice; results require received account changes" }
		end,
		IsComplete = function(result) return type(result) == "table" end }
end

function PetManager:Completed() self:Observe() end
function PetManager:Halt(stopped)
	self.Hatch.Location = nil -- Pause/Stop release the lease, never reset request/command ledgers.
	if stopped and self.Config.PET_SETTINGS.EQUIP_OWNED_TEAM_ONCE then
		self.Attempt = self.Attempt or { BeforeIds = {}, TargetIds = {} }
		self:FinishAttempt("STOPPED", "Owner stopped equipment test; any dispatched request may still be received; no automatic continuation")
	end
	if stopped and self.Hatch.Once then self.Hatch.EndReason = "Owner stopped single-hatch test; no new request; dispatched request cannot be recalled" end
	if self.Transaction and not self.PendingEquip and not self.Attempt then self.Transaction = nil end
end
function PetManager:GetStatus()
	return { Enabled = self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE, Analysis = self.Report, Decision = self.Decision,
		Hatch = self.Hatch:GetStatus(), EquipmentCommands = self.EquipCommands, PendingEquipment = self.PendingEquip,
		LastEquipment = self.LastEquipment, LastAction = self.LastAction, Fault = self.Fault,
		EquipmentAttempt = self.Attempt,
		DestructiveActions = "OFF", ActionVerification = "OWNER_LIVE_PENDING" }
end
return PetManager

end

-- src/OCFoundation/PetPolicy.luau
factories["PetPolicy"] = function()
--!nonstrict
-- Pure Phase 4 analysis. Native helper projections are estimates, never account writes.
local PetPolicy = {}

function PetPolicy.Finite(value)
	return type(value) == "number" and value == value and value >= 0 and value < math.huge
end

function PetPolicy.Counts(ids)
	local result = {}
	for _, id in ipairs(ids or {}) do result[id] = (result[id] or 0) + 1 end
	return result
end

function PetPolicy.SameTeam(a, b)
	if type(a) ~= "table" or type(b) ~= "table" or #a ~= #b then return false end
	local x, y = PetPolicy.Counts(a), PetPolicy.Counts(b)
	for id, count in pairs(x) do if y[id] ~= count then return false end end
	return true
end

function PetPolicy.Inventory(raw)
	if type(raw) ~= "table" or type(raw.Pets) ~= "table" or type(raw.Teams) ~= "table" then return nil, "Inventory/teams unavailable" end
	local team = raw.Teams[raw.TeamEquipped]
	if type(team) ~= "table" or type(team.Pets) ~= "table" then return nil, "Active team unavailable" end
	local teamLength = 0
	for index, id in pairs(team.Pets) do
		if type(index) ~= "number" or index % 1 ~= 0 or index < 1 or type(id) ~= "string" then return nil, "Invalid equipped ID array" end
		teamLength += 1
	end
	for index = 1, teamLength do if team.Pets[index] == nil then return nil, "Sparse equipped ID array" end end
	local result = { ById = {}, Records = 0, Quantity = 0, Team = table.clone(team.Pets), TeamIndex = raw.TeamEquipped }
	for _, pet in pairs(raw.Pets) do
		if type(pet) ~= "table" or type(pet.Id) ~= "string" or type(pet.Name) ~= "string"
			or pet.Amount ~= nil and type(pet.Amount) ~= "number" or not PetPolicy.Finite(pet.Amount or 1) or (pet.Amount or 1) < 1 or (pet.Amount or 1) % 1 ~= 0
			or result.ById[pet.Id] then return nil, "Invalid, duplicate or unknown pet record" end
		result.ById[pet.Id] = pet result.Records += 1 result.Quantity += pet.Amount or 1
	end
	for id, count in pairs(PetPolicy.Counts(result.Team)) do
		if not result.ById[id] or count > (result.ById[id].Amount or 1) then return nil, "Equipped multiplicity is inconsistent with inventory" end
	end
	return result
end

function PetPolicy.Protection(config, pet, definition)
	local p = config.PET_SETTINGS
	if table.find(p.PROTECTED_PET_IDS, pet.Id) then return "explicitly protected ID (no equipment changes)" end
	if pet.Locked then return "native Locked flag" end
	if table.find(p.FAVORITE_PET_IDS, pet.Id) then return "owner-designated favorite ID" end
	if pet.Favorite or pet.Favorited then return "received favorite marker; native pet-favorite contract unverified" end
	if table.find(p.SELECTED_PETS, pet.Name) then return "selected target name" end
	if table.find(p.VALUABLE_PET_IDS, pet.Id) then return "owner-designated valuable ID" end
	if pet.Super or pet.Shiny or pet.Mythic or pet.XL then return "valuable variant" end
	if definition and (definition.Rarity == "Secret" or definition.Rarity == "Infinity") then return "valuable native rarity" end
	return nil
end

function PetPolicy.Protected(config, pet, definition)
	return PetPolicy.Protection(config, pet, definition) ~= nil
end

function PetPolicy.Equal(a, b)
	if type(a) ~= type(b) then return false end
	if type(a) ~= "table" then return a == b end
	for k, v in pairs(a) do if not PetPolicy.Equal(v, b[k]) then return false end end
	for k in pairs(b) do if a[k] == nil then return false end end
	return true
end

function PetPolicy.Describe(config, context, ids)
	local rows, inv = {}, context.Inventory
	for slot, id in ipairs(ids or {}) do
		local pet = inv.ById[id]
		local def = (context.Pets or {})[pet.Name]
		local variants = {} for _, key in ipairs({ "Super", "XL", "Shiny", "Mythic" }) do if pet[key] then table.insert(variants, key) end end
		local stats = context.PetStats and context.PetStats(pet, ids)
		local value = context.PetScore and context.PetScore(pet, ids)
		local without = table.clone(ids) table.remove(without, slot)
		local whole, remainder = context.ScoreTeam(ids), context.ScoreTeam(without)
		table.insert(rows, { Slot = slot, Id = id, Name = pet.Name, Variant = #variants > 0 and table.concat(variants, " ") or "Normal",
			OwnedQuantity = pet.Amount or 1, EquippedCopies = PetPolicy.Counts(ids)[id], XP = pet.XP, Enchants = pet.Enchants,
			Rarity = def and def.Rarity or "UNKNOWN", NativeStats = stats, NativeRoleStat = value,
			RemovalMarginal = PetPolicy.Finite(whole) and PetPolicy.Finite(remainder) and whole - remainder or nil,
			Protection = PetPolicy.Protection(config, pet, def) })
	end
	return rows
end

function PetPolicy.TeamText(team, details)
	if team.Status ~= "ESTIMATE" then return "Team UNKNOWN: " .. tostring(team.Reason) end
	local function lineup(rows)
		local out = {} for _, r in ipairs(rows) do table.insert(out, r.Variant .. " " .. r.Name .. " [" .. r.Id .. "]") end
		return table.concat(out, ", ")
	end
	local header = string.format("%s | team=%s | equipped=%d/native limit=%d | %d records/%d pets | native estimate %.3f -> %.3f | bounded search %d%s",
		tostring(team.Currency), tostring(team.TeamIndex), team.EquippedCount, team.MaxEquipped, team.RecordCount, team.Quantity,
		team.CurrentScore, team.ProjectedScore, team.Evaluations, team.SearchBoundReached and " (limit reached)" or " (local optimum)")
	if not details then return header .. " | proposed: " .. lineup(team.ProposedPets) .. " | details: OC:PrintPetTeam(); earnings impact unmeasured" end
	local lines = { header, "Current: " .. lineup(team.CurrentPets), "Proposed: " .. lineup(team.ProposedPets) }
	for _, group in ipairs({ { "CURRENT", team.CurrentPets }, { "PROPOSED", team.ProposedPets } }) do
		for _, r in ipairs(group[2]) do table.insert(lines, string.format("%s slot %d | %s %s [%s] | owned=%d; team copies=%d | %s stat=%s; removal marginal=%s | XP=%s | protection=%s",
			group[1], r.Slot, r.Variant, r.Name, r.Id, r.OwnedQuantity, r.EquippedCopies, tostring(team.Currency),
			tostring(r.NativeRoleStat or "UNKNOWN"), tostring(r.RemovalMarginal or "UNKNOWN"), tostring(r.XP or "UNKNOWN"), r.Protection or "none")) end
	end
	for index, step in ipairs(team.Improvements) do table.insert(lines, string.format("Search improvement %d | %s replaces %s | native FULL-team %.3f -> %.3f (+%.3f); variants, enchants and account modifiers evaluated together",
		index, step.AddId, step.RemoveId or "free slot", step.BeforeScore, step.AfterScore, step.AfterScore - step.BeforeScore)) end
	for _, reason in ipairs(team.Unknowns) do table.insert(lines, "UNCERTAINTY | " .. reason) end
	table.insert(lines, "Stack copies reuse the actual base ID; no new inventory IDs. Per-pet marginals can overlap through enchants; they are not additive earnings rates.")
	return table.concat(lines, "\n")
end

function PetPolicy.Currency(config, plan)
	if config.PET_SETTINGS.OBJECTIVE_CURRENCY ~= "AUTO" then return config.PET_SETTINGS.OBJECTIVE_CURRENCY end
	local metadata = plan and plan.Objective and plan.Objective.Metadata or {}
	local currency = metadata.Requirement and metadata.Requirement.Currency or metadata.Cost and metadata.Cost.Currency
	if currency == "Coins" or currency == "Gems" or currency == "Tickets" or currency == "Pearls" or currency == "Seashells" then return currency end
	if metadata.Requirement and (metadata.Requirement.Type == "Bubbles" or metadata.Requirement.Type == "Sell") then return "Bubbles" end
	return nil -- No invented currency objective.
end

function PetPolicy.Reserve(config, snapshot, currency)
	local field = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[currency]
	if not field then return nil, "Currency reserve policy unavailable" end
	local reserve = config.RESOURCE_SETTINGS[field]
	if config.HATCH_SETTINGS.PRESERVE_PROGRESSION_RESERVE then
		local graph = snapshot.ProgressionGraph
		if not graph or graph.Blocker or type(graph.Worlds) ~= "table" or #graph.Worlds == 0 then return nil, "Native progression reserve unavailable" end
		for _, world in ipairs(graph.Worlds) do
			if world.Unlocked then continue end
			local cost = world.Cost
			if not cost or cost.Type ~= "Currency" or not PetPolicy.Finite(cost.Amount) then return nil, "Next world cost unknown; hatch reserve unresolved" end
			if cost.Currency == currency then reserve += cost.Amount end
			break
		end
	end
	return reserve
end

-- Bounded native full-team greedy improvement. Cross-pet enchants are evaluated by
-- the game's helper; this is explicitly a heuristic rather than an exhaustive optimum.
function PetPolicy.Team(config, context)
	local inv = context.Inventory
	local report = { Currency = context.Currency, Status = "UNKNOWN", Evidence = "Native full-team stat projection; greedy local search", Evaluations = 0,
		MaxEquipped = context.MaxEquipped, Improvements = {}, Unknowns = { "Server-only modifiers and actual earning-rate impact unverified; native helper totals are client estimates",
			"Bounded greedy local search is not a guaranteed global optimum with interacting enchants", "No native pet-favorite contract found; use FAVORITE_PET_IDS / PROTECTED_PET_IDS" } }
	if not inv or not context.Currency or not context.ScoreTeam or not PetPolicy.Finite(context.MaxEquipped)
		or context.MaxEquipped < 1 or context.MaxEquipped % 1 ~= 0 or #inv.Team > context.MaxEquipped then
		report.Reason = context.Error or "Account, objective or native stat/capacity helper unavailable" return report
	end
	report.RecordCount, report.Quantity, report.EquippedCount = inv.Records, inv.Quantity, #inv.Team
	report.TeamIndex, report.BeforeIds = inv.TeamIndex, table.clone(inv.Team)
	local function score(ids)
		report.Evaluations += 1
		local value = context.ScoreTeam(ids)
		return PetPolicy.Finite(value) and value or nil
	end
	local current = score(inv.Team)
	if not current then report.Reason = "Native team score failed; no guessed fallback" return report end
	report.CurrentScore, report.ProjectedScore, report.ProposedIds = current, current, table.clone(inv.Team)
	local candidates = {}
	for id, pet in pairs(inv.ById) do
		-- Super equip constraints are a separate native capacity: preserve existing
		-- Supers but never add or replace them in this initial executor.
		local definition = (context.Pets or {})[pet.Name]
		if not definition or not definition.Rarity then table.insert(report.Unknowns, pet.Name .. " [" .. id .. "]: definition/rarity UNKNOWN; preserved") continue end
		if pet.Super then continue end
		if table.find(config.PET_SETTINGS.PROTECTED_PET_IDS, id) then continue end
		local value = context.PetScore and context.PetScore(pet)
		if PetPolicy.Finite(value) then table.insert(candidates, { Id = id, Score = value })
		else table.insert(report.Unknowns, pet.Name .. " [" .. id .. "]: native pet stat failed; excluded") end
	end
	table.sort(candidates, function(a, b) return a.Score == b.Score and a.Id < b.Id or a.Score > b.Score end)
	local limit = config.PET_SETTINGS.MAXIMUM_TEAM_EVALUATIONS
	local exhausted = false
	while report.Evaluations < limit do
		local best, bestScore, improvement = nil, report.ProjectedScore, nil
		local counts = PetPolicy.Counts(report.ProposedIds)
		for _, candidate in ipairs(candidates) do
			if (counts[candidate.Id] or 0) >= (inv.ById[candidate.Id].Amount or 1) then continue end
			for slot = 1, #report.ProposedIds + (#report.ProposedIds < context.MaxEquipped and 1 or 0) do
				if report.Evaluations >= limit then exhausted = true break end
				local old = inv.ById[report.ProposedIds[slot]]
				if old and (old.Super or PetPolicy.Protected(config, old, (context.Pets or {})[old.Name]) or not (context.Pets or {})[old.Name] or not context.Pets[old.Name].Rarity) then continue end
				local ids = table.clone(report.ProposedIds) ids[slot] = candidate.Id
				local value = score(ids)
				if value and value > bestScore + 1e-6 then
					best, bestScore = ids, value
					improvement = { AddId = candidate.Id, RemoveId = old and old.Id, BeforeScore = report.ProjectedScore, AfterScore = value }
				elseif not value then report.ProjectionFailures = (report.ProjectionFailures or 0) + 1 end
			end
			if exhausted then break end
		end
		if not best then break end
		table.insert(report.Improvements, improvement)
		report.ProposedIds, report.ProjectedScore = best, bestScore
		if exhausted then break end
	end
	report.Status = "ESTIMATE" report.SearchBoundReached = exhausted or report.Evaluations >= limit
	report.Gain = report.ProjectedScore - current
	report.Reason = report.Gain > 0 and "A stronger owned team is available before hatching" or "No owned improvement found within bounded native projections"
	if report.SearchBoundReached then table.insert(report.Unknowns, "Search limit reached; stronger combinations may remain unevaluated") end
	if report.ProjectionFailures then table.insert(report.Unknowns, tostring(report.ProjectionFailures) .. " candidate full-team helper failures; results incomplete") end
	report.CurrentPets, report.ProposedPets = PetPolicy.Describe(config, context, report.BeforeIds), PetPolicy.Describe(config, context, report.ProposedIds)
	return report
end

function PetPolicy.HatchIsolation(config)
	local p, h = config.PET_SETTINGS, config.HATCH_SETTINGS
	if not p.ENABLE_PET_INTELLIGENCE or not p.AUTO_HATCH or p.AUTO_EQUIP or p.EQUIP_OWNED_TEAM_ONCE
		or p.OBJECTIVE_CURRENCY ~= "Coins" or not h.HATCH_ONE_EGG_ONCE then return "Single hatch requires explicit isolated Coins hatch authorization; equipment OFF" end
	if #h.SELECTED_EGGS ~= 1 or #h.ALLOWED_CURRENCIES ~= 1 or h.ALLOWED_CURRENCIES[1] ~= "Coins"
		or h.MAXIMUM_SESSION_HATCHES ~= 1 or h.MAXIMUM_BATCH_HATCHES ~= 1 or h.MAXIMUM_EGG_COST <= 0 or h.MAXIMUM_SESSION_COST <= 0
		or h.ENABLE_BACKGROUND_PICKUPS or not h.PRESERVE_PROGRESSION_RESERVE then return "Single hatch requires one egg, one request, positive explicit Coins ceilings, protected reserve and no background pickups" end
	for category, keys in pairs({
		WORLD_SETTINGS = { "ENABLE_WORLD_PROGRESSION", "AUTO_DISCOVER_ISLANDS", "AUTO_UNLOCK_WORLDS", "AUTO_TRAVEL_FOR_PROGRESSION", "AUTO_FARM_UNLOCK_REQUIREMENTS" },
		FARMING_SETTINGS = { "AUTO_RESOURCE_FARM", "AUTO_FARM_FALLBACK" },
		ISLAND_SETTINGS = { "AUTO_TRAVEL_BEST_ISLAND", "AUTO_EXPLORE_UNLOCKED_ISLANDS" },
		PICKUP_SETTINGS = { "BULK_COLLECT_PICKUPS", "STATIONARY_ISOLATED_TEST" },
		BUBBLE_SETTINGS = { "AUTO_BLOW_BUBBLES", "AUTO_SELL_BUBBLES", "AUTO_BUY_GUM", "AUTO_BUY_FLAVORS", "ENABLE_SIMULTANEOUS_BLOWING" },
		UPGRADE_SETTINGS = { "ENABLE_SMART_UPGRADES", "ENABLE_CAPACITY_UPGRADES", "ENABLE_FLAVOR_UPGRADES", "AUTO_EQUIP_OWNED_UPGRADES" },
		PET_SETTINGS = { "AUTO_DELETE_PETS", "AUTO_CRAFT_SHINY", "AUTO_FUSE_PETS" },
		FALL_EVENT_SETTINGS = { "ENABLE_FALL_EVENT", "AUTO_REBIRTH", "AUTO_BUY_REBIRTH_UPGRADES", "AUTO_USE_FALL_ELIXIRS", "AUTO_BUY_AUTUMN_SHOP_ITEMS" },
	}) do
		for _, key in ipairs(keys) do if config[category][key] then return "Single hatch requires " .. category .. "." .. key .. " OFF" end end
	end
	return nil
end

function PetPolicy.WorldAccess(profile, world)
	local map = type(profile) == "table" and profile.WorldsUnlocked
	local known = type(map) == "table"
	local present = known and map[world] ~= nil
	local rawValue
	if known then rawValue = map[world] end
	return { Name = world, Status = not known and "UNKNOWN" or present and "UNLOCKED" or "LOCKED",
		MapKnown = known, EntryPresent = present == true, RawValue = rawValue,
		Evidence = "Received LocalData.WorldsUnlocked; native gate/map access checks entry presence (ClientScript:2140, WorldMap:99); rejoin persistence unverified" }
end

function PetPolicy.FundEgg(config, snapshot, r)
	local h = config.HATCH_SETTINGS
	r.SpendingStatus = not config.PET_SETTINGS.AUTO_HATCH and "DISABLED_AUTO_HATCH" or (h.MAXIMUM_EGG_COST <= 0 or h.MAXIMUM_SESSION_COST <= 0) and "DISABLED_ZERO_BUDGET"
		or not table.find(h.SELECTED_EGGS, r.Name) and "NOT_SELECTED" or "AUTHORIZED_CONFIG"
	local cost = r.Cost
	if cost and cost.Type == "Currency" and PetPolicy.Finite(cost.Amount) and cost.Amount > 0 then
		r.Balance = snapshot.Balances and snapshot.Balances[cost.Currency]
		r.Reserve, r.ReserveReason = PetPolicy.Reserve(config, snapshot, cost.Currency)
		if PetPolicy.Finite(r.Balance) then r.FundsAffordable = r.Balance >= cost.Amount end
		if r.Reserve ~= nil and PetPolicy.Finite(r.Balance) then
			r.Spendable = math.max(0, r.Balance - r.Reserve)
			r.ReserveAllows = r.Spendable >= cost.Amount
		end
		r.Affordable = r.FundsAffordable == true and r.ReserveAllows == true
		r.FundingStatus = r.FundsAffordable == nil and "UNKNOWN_BALANCE" or not r.FundsAffordable and "INSUFFICIENT_FUNDS"
			or r.Reserve == nil and "UNKNOWN_RESERVE" or not r.ReserveAllows and "PROTECTED_RESERVE" or "AFFORDABLE"
		if r.SpendingStatus == "AUTHORIZED_CONFIG" then
			r.SpendingStatus = not table.find(h.ALLOWED_CURRENCIES, cost.Currency) and "CURRENCY_NOT_AUTHORIZED"
				or cost.Amount > h.MAXIMUM_EGG_COST and "EGG_COST_CEILING" or cost.Amount > h.MAXIMUM_SESSION_COST and "SESSION_COST_CEILING" or "AUTHORIZED_CONFIG"
		end
	else r.FundingStatus = "UNKNOWN_NATIVE_COST" end
	return r
end

function PetPolicy.Egg(config, snapshot, context, team, egg)
	local h = config.HATCH_SETTINGS
	local r = { Name = egg.Name, Status = "UNKNOWN", Eligible = egg.Accessible == true, InRange = egg.InRange == true,
		Loaded = egg.Loaded, AccessStatus = egg.AccessStatus or "UNKNOWN_ACCESS", World = egg.World, Island = egg.Island,
		Distance = egg.Distance, Range = egg.Range, ModelPath = egg.ModelPath, Position = egg.Position,
		Cost = egg.Cost, Reason = egg.Reason, ProbabilityEvidence = "CLIENT_UI_POOL_ESTIMATE",
		EffectiveServerOdds = "UNKNOWN", VariantOdds = "UNKNOWN", PityGuarantee = "UNKNOWN", TotalTimeSeconds = "UNKNOWN",
		TravelTimeSeconds = "UNKNOWN", VerificationTimeSeconds = "UNKNOWN", StorageUnit = context.StorageUnit,
		DurationSeconds = egg.Duration, NativeBatchCapacity = context.MaxHatches, Outcomes = {} }
	PetPolicy.FundEgg(config, snapshot, r)
	local cost = egg.Cost
	-- Funding/configuration/access are separate from the supported pool estimate.
	-- Never substitute the hypothetical improved owned team for the actual team.
	if egg.Loaded == false then r.Reason = egg.Reason return r end
	if not cost or cost.Type ~= "Currency" or not PetPolicy.Finite(cost.Amount) or cost.Amount <= 0 then r.Reason = "Native currency cost unavailable/unsupported" return r end
	if team.Status ~= "ESTIMATE" or not context.ScoreNewPet or type(egg.Pool) ~= "table" then r.Reason = "Insufficient native team/pool evidence" return r end
	local total = 0
	for _, entry in ipairs(egg.Pool) do
		if not PetPolicy.Finite(entry.Chance) then r.Reason = "Unknown pool weight" return r end
		total += entry.Chance
	end
	if total <= 0 then r.Reason = "Empty native pool" return r end
	local expected, improveChance, targetChance = 0, 0, 0
	for _, entry in ipairs(egg.Pool) do
		local item = entry.Item
		if entry.Chance == 0 then continue end
		if not item or item.Type ~= "Pet" or not (context.Pets or {})[item.Name] then r.Reason = "Unsupported pool outcome" return r end
		local value = context.ScoreNewPet(item.Name, team.BeforeIds)
		if not PetPolicy.Finite(value) then r.Reason = "Native pet contribution unavailable" return r end
		local probability = entry.Chance / total -- Inspected native weighted sampler; NOT verified server RNG.
		local gain = math.max(0, value - team.CurrentScore)
		expected += gain * probability
		if gain > 1e-6 then improveChance += probability end
		if table.find(config.PET_SETTINGS.SELECTED_PETS, item.Name) then targetChance += probability end
		table.insert(r.Outcomes, { Name = item.Name, ClientPoolProbability = probability, IncrementalGain = gain })
	end
	r.Status, r.ExpectedIncrement, r.ClientImprovementProbability, r.ClientTargetProbability = "ESTIMATE", expected, improveChance, targetChance
	r.BaselineScore, r.ExpectedIncrementPerCost = team.CurrentScore, expected / cost.Amount
	if PetPolicy.Finite(egg.Duration) and egg.Duration > 0 and PetPolicy.Finite(context.MaxHatches) and context.MaxHatches >= 1 then
		local batch = math.min(h.MAXIMUM_BATCH_HATCHES, context.MaxHatches, context.DigitalStorage and 1 or math.huge)
		r.EffectiveCycleSeconds = math.max(egg.Duration, h.MINIMUM_REQUEST_INTERVAL_SECONDS)
		r.ExpectedIncrementPerSecond = expected * batch / r.EffectiveCycleSeconds
		if improveChance > 0 then r.EstimatedSecondsToUsefulBasePet = r.EffectiveCycleSeconds / (batch * improveChance) end
	end
	r.Reason = expected > 1e-6 and "Useful base-pet estimate against ACTUAL equipped team" or "NO_USEFUL_IMPROVEMENT in evaluated base-pet pool"
	return r
end

function PetPolicy.EggBlocker(egg)
	if not egg.Eligible then return egg.AccessStatus .. ": " .. tostring(egg.Reason) end
	if egg.Status ~= "ESTIMATE" then return "INSUFFICIENT_EVIDENCE: " .. tostring(egg.Reason) end
	if egg.ExpectedIncrement <= 1e-6 then return "NO_USEFUL_IMPROVEMENT in evaluated base-pet pool" end
	if egg.FundingStatus ~= "AFFORDABLE" then return egg.FundingStatus .. (egg.ReserveReason and ": " .. egg.ReserveReason or "") end
	if egg.SpendingStatus ~= "AUTHORIZED_CONFIG" then return egg.SpendingStatus end
	return nil
end

function PetPolicy.Analyze(config, snapshot, context)
	local report = { Team = PetPolicy.Team(config, context), Eggs = {}, CoinsAvailability = {}, Currency = context.Currency,
		AccountRevision = snapshot.Revision, Coverage = context.EggCoverage, MinigameParadise = context.MinigameParadise }
	for _, egg in ipairs(context.EggAvailability or context.Eggs or {}) do
		if egg.Cost and egg.Cost.Type == "Currency" and egg.Cost.Currency == "Coins" or egg.Cost == nil and egg.DefinitionCurrency == "Coins" then
			table.insert(report.CoinsAvailability, PetPolicy.FundEgg(config, snapshot, { Name = egg.Name, Cost = egg.Cost,
				Loaded = egg.Loaded, Eligible = egg.Accessible == true, AccessStatus = egg.AccessStatus or "UNKNOWN_ACCESS", World = egg.World, Island = egg.Island }))
		end
	end
	table.sort(report.CoinsAvailability, function(a, b) return a.Name < b.Name end)
	for _, egg in ipairs(context.Eggs or {}) do table.insert(report.Eggs, PetPolicy.Egg(config, snapshot, context, report.Team, egg)) end
	table.sort(report.Eggs, function(a, b)
		local ac, bc = a.Cost and a.Cost.Currency or "UNKNOWN", b.Cost and b.Cost.Currency or "UNKNOWN"
		if ac ~= bc then
			local x, y = table.find(config.HATCH_SETTINGS.ALLOWED_CURRENCIES, ac), table.find(config.HATCH_SETTINGS.ALLOWED_CURRENCIES, bc)
			if (x ~= nil) ~= (y ~= nil) then return x ~= nil end
			return ac < bc -- Separate currency groups; never compare their numeric EV/cost.
		end
		local x = a.Status == "ESTIMATE" and a.Eligible and a.Affordable and a.ExpectedIncrementPerCost or -1
		local y = b.Status == "ESTIMATE" and b.Eligible and b.Affordable and b.ExpectedIncrementPerCost or -1
		if x == y then return a.Name < b.Name end
		return x > y
	end)
	for _, egg in ipairs(report.Eggs) do
		if egg.Status == "ESTIMATE" and egg.Eligible and egg.Affordable and table.find(config.HATCH_SETTINGS.ALLOWED_CURRENCIES, egg.Cost.Currency)
			and egg.ExpectedIncrement > 1e-6 then report.RecommendedEgg = egg break end
	end
	local egg = report.RecommendedEgg
	if egg then
		report.HatchTestPlan = { EggName = egg.Name, Currency = egg.Cost.Currency, NativePrice = egg.Cost.Amount,
			RequiredEggBudget = egg.Cost.Amount, RequiredSessionBudget = egg.Cost.Amount, HatchCount = 1,
			World = egg.World, Island = egg.Island, ModelPath = egg.ModelPath, Position = egg.Position, Distance = egg.Distance,
			Range = egg.Range, InRange = egg.InRange, Reserve = egg.Reserve, RequiredBalance = egg.Reserve + egg.Cost.Amount,
			SpendingPermission = config.PET_SETTINGS.AUTO_HATCH and "CONFIG_ENABLED; execution guards still required" or "OFF; owner authorization required",
			PriceEvidence = "StatsUtil:GetEggCost(player, detached current LocalData, egg); native client price; rechecked before any authorized request; server acceptance unverified" }
	end
	report.Comparison = "Cost efficiency within native currency only; no invented conversion. Client base odds/XP=0 estimates; final server/variant/Secret/Infinity odds and pity UNKNOWN; total travel/verification time UNKNOWN"
	return report
end

function PetPolicy.EggPlanText(config, report, details)
	local h, coverage = config.HATCH_SETTINGS, report.Coverage or {}
	local lines = { string.format("%s | actual equipped native score=%s | loaded=%s; pool analyses=%s/%s limit; native definitions=%s (%s permanent); limited loaded-model coverage | AUTO_HATCH=%s; egg/session budgets=%s/%s | recommendation=%s",
		tostring(report.Currency), tostring(report.Team.CurrentScore or "UNKNOWN"), tostring(coverage.LoadedModels or "UNKNOWN"), tostring(coverage.Evaluated or #report.Eggs),
		tostring(coverage.Limit or h.MAXIMUM_EGGS_ANALYZED), tostring(coverage.Definitions or "UNKNOWN"), tostring(coverage.PermanentDefinitions or "UNKNOWN"),
		tostring(config.PET_SETTINGS.AUTO_HATCH), tostring(h.MAXIMUM_EGG_COST), tostring(h.MAXIMUM_SESSION_COST), report.RecommendedEgg and report.RecommendedEgg.Name or "NONE within evaluated accessible affordable estimates") }
	local world = report.MinigameParadise or {}
	local entry = not world.MapKnown and "UNKNOWN" or not world.EntryPresent and "ABSENT" or tostring(world.RawValue)
	table.insert(lines, "Minigame Paradise=" .. (world.Status or "UNKNOWN") .. " | LocalData.WorldsUnlocked entry=" .. entry .. "; native access uses entry presence; saved persistence unverified")
	local available, blocked = {}, {}
	for _, egg in ipairs(report.CoinsAvailability or {}) do
		local text = string.format("%s (%s Coins; %s; %s)", egg.Name, tostring(egg.Cost and egg.Cost.Amount or "UNKNOWN"), egg.AccessStatus, egg.FundingStatus)
		table.insert(egg.Loaded == true and egg.Eligible and egg.Affordable and available or blocked, text)
	end
	table.insert(lines, "Available affordable Coins eggs (loaded native models, after reserves): " .. (#available > 0 and table.concat(available, ", ") or "NONE confirmed"))
	if #blocked > 0 then table.insert(lines, "Other loaded Coins candidates: " .. table.concat(blocked, ", ")) end
	if coverage.UnloadedCoinsDefinitions and #coverage.UnloadedCoinsDefinitions > 0 then
		table.insert(lines, "Coins definitions without a loaded native model (availability unverified): " .. table.concat(coverage.UnloadedCoinsDefinitions, ", "))
	end
	local testPlan = report.HatchTestPlan
	if testPlan then
		local position = testPlan.Position
		local coordinates = position and string.format("%.1f,%.1f,%.1f", position.X, position.Y, position.Z) or "UNKNOWN"
		table.insert(lines, string.format("One-hatch proposal: stand beside %s @ %s/%s | native model=%s; root=%s; distance=%s studs; native range=%s; in range=%s | native price=%s %s; required egg/session test budget=%s/%s %s; reserve=%s; required balance=%s | spending=%s; proposal does not modify Config",
			testPlan.EggName, tostring(testPlan.World or "UNKNOWN"), tostring(testPlan.Island or "ground/unknown"), tostring(testPlan.ModelPath or "UNKNOWN"), coordinates,
			PetPolicy.Finite(testPlan.Distance) and string.format("%.1f", testPlan.Distance) or "UNKNOWN", tostring(testPlan.Range or "UNKNOWN"), tostring(testPlan.InRange),
			testPlan.NativePrice, testPlan.Currency, testPlan.RequiredEggBudget, testPlan.RequiredSessionBudget, testPlan.Currency, testPlan.Reserve, testPlan.RequiredBalance, testPlan.SpendingPermission))
	end
	local display, seen = {}, {}
	-- Always explain the explicitly selected candidate, even when rejected/missing.
	for _, name in ipairs(h.SELECTED_EGGS) do for _, egg in ipairs(report.Eggs) do if egg.Name == name and not seen[name] then table.insert(display, egg) seen[name] = true end end end
	if report.RecommendedEgg and not seen[report.RecommendedEgg.Name] then table.insert(display, report.RecommendedEgg) seen[report.RecommendedEgg.Name] = true end
	for _, egg in ipairs(report.Eggs) do if not seen[egg.Name] then table.insert(display, egg) seen[egg.Name] = true end end
	for index, egg in ipairs(display) do
		if not details and index > h.MAXIMUM_PLAN_CANDIDATES then break end
		local useful = {}
		for _, outcome in ipairs(egg.Outcomes) do
			if details or outcome.IncrementalGain > 1e-6 then
				table.insert(useful, string.format("%s %.4g%% (+%.4g)", outcome.Name, outcome.ClientPoolProbability * 100, outcome.IncrementalGain))
			end
		end
		local cost = egg.Cost
		table.insert(lines, string.format("%s @ %s/%s | cost=%s %s | access=%s; funds=%s; reserve=%s; spendable=%s; funding=%s; config=%s | EV=%s native score/egg; useful odds=%s%%; cycle=%ss | %s | %s",
			egg.Name, tostring(egg.World or "UNKNOWN"), tostring(egg.Island or "ground/unknown"), tostring(cost and cost.Amount or "UNKNOWN"), tostring(cost and cost.Currency or "UNKNOWN"),
			egg.AccessStatus, tostring(egg.Balance or "UNKNOWN"), tostring(egg.Reserve or "UNKNOWN"), tostring(egg.Spendable or "UNKNOWN"), egg.FundingStatus, egg.SpendingStatus,
			egg.Status == "ESTIMATE" and string.format("%.5g", egg.ExpectedIncrement) or "UNKNOWN",
			egg.Status == "ESTIMATE" and string.format("%.5g", egg.ClientImprovementProbability * 100) or "UNKNOWN", tostring(egg.EffectiveCycleSeconds or "UNKNOWN"),
			#useful > 0 and "useful base outcomes: " .. table.concat(useful, ", ") or "no useful supported base outcomes", PetPolicy.EggBlocker(egg) or "Useful affordable estimate; eligible for explicitly bounded request"))
	end
	table.insert(lines, report.Comparison)
	return table.concat(lines, "\n")
end

return PetPolicy

end

-- src/OCFoundation/PickupTracker.luau
factories["PickupTracker"] = function()
--!nonstrict
-- Scene observation only. Native ClientScript owns pickup collection and credit.
local PickupTracker = {}
PickupTracker.__index = PickupTracker
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local GameKnowledge = requireOC("GameKnowledge")

local function allowed(list, value) return #list == 0 or table.find(list, value) ~= nil end
local function worldOf(instance)
	local worlds = workspace:FindFirstChild("Worlds")
	local node = instance
	while node and node ~= workspace do
		if node.Parent == worlds then return node.Name end
		node = node.Parent
	end
	return nil
end
local function vectorKey(vector)
	return string.format("%.4f,%.4f,%.4f", vector.X, vector.Y, vector.Z)
end
local function colorKey(color) return string.format("%.4f,%.4f,%.4f", color.R, color.G, color.B) end
local function fingerprint(model, meshOnly)
	local pieces = {}
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("MeshPart") then
			table.insert(pieces, part.Name .. ":" .. part.MeshId .. ":" .. part.TextureID .. (meshOnly and "" or ":" .. vectorKey(part.Size)))
		elseif part:IsA("SpecialMesh") then
			table.insert(pieces, part.Name .. ":" .. part.MeshId .. ":" .. part.TextureId .. (meshOnly and "" or ":" .. vectorKey(part.Scale)))
		elseif part:IsA("BasePart") then
			table.insert(pieces, part.Name .. ":" .. part.ClassName .. (meshOnly and "" or ":" .. vectorKey(part.Size)) .. ":" .. colorKey(part.Color))
		end
	end
	table.sort(pieces)
	return #pieces > 0 and table.concat(pieces, "|") or nil
end
local function spawnFor(area, world)
	local worlds = workspace:FindFirstChild("Worlds")
	local root = worlds and worlds:FindFirstChild(world or "")
	if not root then return nil end
	if area == world then
		local travel = root:FindFirstChild("FastTravel")
		-- PortalSpawn is the verified return destination used by native island portals.
		return (travel and travel:FindFirstChild("Spawn")) or root:FindFirstChild("PortalSpawn")
	end
	local islands = root:FindFirstChild("Islands")
	local island = islands and islands:FindFirstChild(area)
	local model = island and island:FindFirstChild("Island")
	local portal = model and model:FindFirstChild("Portal")
	return portal and portal:FindFirstChild("Spawn")
end

local function islandOf(instance, world)
	local worlds = workspace:FindFirstChild("Worlds")
	local root = worlds and worlds:FindFirstChild(world or "")
	local islands = root and root:FindFirstChild("Islands")
	local node = instance
	while node and node ~= workspace do
		if node.Parent == islands then return node.Name end
		node = node.Parent
	end
	return nil
end

function PickupTracker.new(config, reader, player, knowledge)
	return setmetatable({ Config = config, Reader = reader, Knowledge = knowledge or GameKnowledge.new(reader), Player = player, Zones = {}, Areas = {},
		Metadata = {}, Models = {}, ModelIds = {}, Backoff = {}, Connections = {}, Prefabs = nil,
		LastZoneRefresh = -math.huge, LastScan = -math.huge, ObservedSpawns = 0, Disappeared = 0,
		LastPrefabRefresh = -math.huge, IdentityCache = {}, PrefabRevision = 0,
		NativeSpawnEvents = 0, NativeSpawnRecords = 0,
		RespawnObservations = 0, Destroyed = false }, PickupTracker)
end

function PickupTracker:Root()
	local character = self.Player and self.Player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if root and humanoid and humanoid.Health > 0 then return root, humanoid end
	return nil
end

function PickupTracker:_hookSpawn()
	if self.SpawnConnection or not self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS or not self.Config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING then return end
	local remotes = ReplicatedStorage:FindFirstChild("Remotes")
	local pickups = remotes and remotes:FindFirstChild("Pickups")
	local spawn = pickups and pickups:FindFirstChild("SpawnPickups")
	if not spawn or not spawn:IsA("RemoteEvent") then return end
	self.SpawnConnection = spawn.OnClientEvent:Connect(function(payload)
		self.NativeSpawnEvents += 1
		if type(payload) ~= "table" then return end
		for _, entry in pairs(payload) do
			if type(entry) == "table" and (type(entry.Id) == "string" or (type(entry.Id) == "number" and entry.Id == entry.Id and math.abs(entry.Id) < math.huge)) and type(entry.Visual) == "string" then
				self.Metadata[tostring(entry.Id)] = { Root = entry.Root, Visual = entry.Visual, At = os.clock() }
				self.NativeSpawnRecords += 1
			end
		end
	end)
	table.insert(self.Connections, self.SpawnConnection)
end

function PickupTracker:_zones(now)
	if now - self.LastZoneRefresh < self.Config.PICKUP_SETTINGS.ZONE_REFRESH_SECONDS then return end
	local getZones = self.Knowledge:Get("GetPickupZones")
	if type(getZones) ~= "function" then self.Error = "GetPickupZones interface is unavailable" return end
	self.LastZoneRefresh = now
	local ok, zones = pcall(getZones)
	if not ok or type(zones) ~= "table" then self.Error = "Zone read failed: " .. tostring(zones) return end
	self.Zones = zones
	self.Error = nil
end

function PickupTracker:_prefabs(now)
	if now - self.LastPrefabRefresh < self.Config.PICKUP_SETTINGS.PREFAB_REFRESH_SECONDS then return end
	local pickups = self.Knowledge:Assets("Pickups")
	if not pickups then return end
	self.Prefabs, self.MeshPrefabs = {}, {}
	self.LastPrefabRefresh, self.PrefabRevision = now, self.PrefabRevision + 1
	local function insert(index, key, name)
		if not key then return end
		index[key] = index[key] or {}
		index[key][name] = true -- Duplicate assets with the same visual name are not different rewards.
	end
	for _, prefab in ipairs(pickups:GetChildren()) do
		if prefab:IsA("Model") then
			local ok, exact, meshes = pcall(function() return fingerprint(prefab), fingerprint(prefab, true) end)
			if ok then insert(self.Prefabs, exact, prefab.Name) insert(self.MeshPrefabs, meshes, prefab.Name) end
		end
	end
end

function PickupTracker:Refresh(snapshot, now)
	local hatch = self.Config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE and self.Config.PET_SETTINGS.AUTO_HATCH and self.Config.HATCH_SETTINGS.ENABLE_BACKGROUND_PICKUPS
	if self.Destroyed or not self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM and not hatch then return end
	self:_hookSpawn()
	self:_zones(now)
	local root = self:Root()
	local position = root and root.Position
	local profile = self.Reader:GetLiveProfile()
	local stats = self.Knowledge:Get("StatsUtil")
	local oldAreas, areas, current, currentDistance = self.Areas, {}, nil, math.huge
	self.ZoneAreas, self.ZoneInfo = {}, {}
	local catalog = (snapshot.AvailableProgression or {}).Islands or {}
	local function areaFor(name, world)
		local key = (world or "Live event") .. "/" .. name
		if areas[key] then return areas[key] end
		local prior = oldAreas[key]
		local area = { Key = key, Name = name, World = world, Zones = {}, Currencies = {}, Expected = {}, Available = {},
			VisibleCount = 0, EligibleCount = 0, UnknownCount = 0, ZoneCount = 0, ConfiguredCount = 0,
			LastDepletionAt = prior and prior.LastDepletionAt, RespawnSeconds = prior and prior.RespawnSeconds,
			LastSpawnAt = prior and prior.LastSpawnAt, TravelSeconds = prior and prior.TravelSeconds }
		areas[key] = area
		return area
	end
	-- Keep real catalog islands visible even when no tagged zone is loaded. This is not pickup availability.
	local function catalogIsland(name, world)
		local area = areaFor(name, world)
		area.CatalogKnown = true
		-- Native WorldMap sends this exact path without requiring a locally visible Portal.Spawn.
		area.DestinationPath = "Workspace.Worlds." .. world .. ".Islands." .. name .. ".Island.Portal.Spawn"
	end
	for _, island in ipairs(catalog) do catalogIsland(island.Name, island.World) end
	-- The Phase 1 progression catalog filters absent scene models. Still diagnose defined islands whose geometry is not loaded.
	local definitions = self.Knowledge:Get("Worlds")
	local areaWorlds = {}
	local function registerArea(name, world)
		if areaWorlds[name] == nil then areaWorlds[name] = world elseif areaWorlds[name] ~= world then areaWorlds[name] = false end
	end
	for world, definition in pairs(type(definitions) == "table" and definitions or {}) do
		if type(definition) == "table" and not definition.Removed and not definition.Event then
			registerArea(world, world)
			for _, island in ipairs(definition.Islands or {}) do catalogIsland(island.Name, world) registerArea(island.Name, world) end
		end
	end
	for _, island in ipairs(catalog) do registerArea(island.Name, island.World) end
	local stages = workspace:FindFirstChild("Stages")
	local multiplierCache = {}
	for zoneRoot, data in pairs(self.Zones) do
		if zoneRoot.Parent and zoneRoot:IsDescendantOf(workspace) and data.Zone and type(data.Area) == "string" and data.Area ~= "" then
			local physicalWorld = worldOf(zoneRoot)
			local world = physicalWorld or areaWorlds[data.Area] or nil
			local transit = stages ~= nil and zoneRoot:IsDescendantOf(stages)
			local physicalIsland = islandOf(zoneRoot, world)
			local area = areaFor(physicalIsland or data.Area, world)
			self.ZoneAreas[zoneRoot] = area
			area.AllZoneCount = (area.AllZoneCount or 0) + 1
			if transit then area.TransitZoneCount = (area.TransitZoneCount or 0) + 1 else
				area.ZoneCount += 1
				if type(data.Count) == "number" then area.ConfiguredCount += data.Count else area.UnknownZoneCount = true end
			end
			if physicalIsland and physicalIsland ~= data.Area then area.MappingWarning = "Physical island differs from native reward pool Area=" .. data.Area end
			local zoneInfo = { Root = zoneRoot, Data = data, IsTransit = transit }
			table.insert(area.Zones, zoneInfo) self.ZoneInfo[zoneRoot] = zoneInfo
			local sumChance = 0
			for _, pickup in ipairs(data.Pickups or {}) do sumChance += type(pickup.Chance) == "number" and pickup.Chance or 0 end
			for _, pickup in ipairs(data.Pickups or {}) do
				local item = pickup.Item and pickup.Item.Item
				if item and item.Type == "Currency" and type(item.Currency) == "string" and type(item.Amount) == "number" then
					if not transit then area.Currencies[item.Currency] = true end
					self.Reader:RegisterCurrency(item.Currency)
					local multiplier = multiplierCache[item.Currency]
					if multiplier == nil and profile and stats and type(stats.GetCurrencyMultiplier) == "function" then
						local success, value = pcall(stats.GetCurrencyMultiplier, stats, profile, item.Currency)
						if success and type(value) == "number" and value > 0 then multiplier = value end
						multiplierCache[item.Currency] = multiplier or false
					end
					if multiplier == false then multiplier = nil end
					area.Multipliers = area.Multipliers or {}
					area.Multipliers[item.Currency] = multiplier
					local count = type(data.Count) == "number" and data.Count or nil
					if not transit and count and multiplier and sumChance > 0 and type(pickup.Chance) == "number" then
						area.Expected[item.Currency] = (area.Expected[item.Currency] or 0) + count * pickup.Chance / sumChance * item.Amount * multiplier
					end
				end
			end
			if not transit and position and math.abs(position.Y - data.Zone.Height) <= self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS then
				local distance = data.Zone:GetDistanceToPoint(position)
				if distance < currentDistance and distance <= self.Config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS then
					current, currentDistance = area, distance
				end
			end
		end
	end
	for _, area in pairs(areas) do
		area.WorldUnlocked = area.World ~= nil and snapshot.UnlockedWorlds ~= nil and snapshot.UnlockedWorlds[area.World] ~= nil or false
		area.Discovered = snapshot.UnlockedIslands ~= nil and snapshot.UnlockedIslands[area.Name] ~= nil or false
		area.Unlocked = area.WorldUnlocked and (area.Name == area.World or area.Discovered)
		-- A live special zone may be farmed where the player already is, but no unverified event teleport is invented.
		area.AtCurrentLocation = area == current
		if area == current then area.Unlocked = true end
		area.Spawn = spawnFor(area.Name, area.World)
		if area.Spawn and not area.Spawn:IsA("BasePart") then area.Spawn = nil end
	end
	self.Areas, self.Current = areas, current
	if self.LastAreaKey ~= (current and current.Key) then self.LastAreaKey = current and current.Key self.ArrivedAt = now end
	if self.Config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING and now - self.LastScan >= self.Config.PICKUP_SETTINGS.COLLECTION_REFRESH_SECONDS then
		self.LastScan = now
		self:_scan(now)
	else
		-- Preserve counts between expensive scans, but rebuild zone eligibility each observation.
		for key, area in pairs(areas) do
			local previous = oldAreas[key]
			if previous then
				area.Available, area.VisibleCount, area.EligibleCount, area.UnknownCount = previous.Available, previous.VisibleCount, previous.EligibleCount, previous.UnknownCount
			end
		end
	end
end

function PickupTracker:_identity(model, zones, metadata)
	local pool = {}
	for _, zone in ipairs(zones) do
		for _, entry in ipairs(zone.Data.Pickups or {}) do
			if entry.Item and type(entry.Item.Visual) == "string" then pool[entry.Item.Visual] = true end
		end
	end
	if metadata and type(metadata.Visual) == "string" then return metadata.Visual, "SPAWN_METADATA" end
	local cached = self.IdentityCache[model]
	if not cached or cached.Revision ~= self.PrefabRevision then
		local ok, exact, meshes = pcall(function() return fingerprint(model), fingerprint(model, true) end)
		cached = { Revision = self.PrefabRevision, Exact = ok and exact or nil, Meshes = ok and meshes or nil, Error = not ok and tostring(exact) or nil }
		self.IdentityCache[model] = cached
	end
	if cached.Error then return nil, nil, "Prefab read failed: " .. cached.Error end
	local function unique(index, key)
		local name, count = nil, 0
		for visual in pairs((key and index and index[key]) or {}) do
			if pool[visual] then name = visual count += 1 end
		end
		return count == 1 and name or nil, count
	end
	local visual, count = unique(self.Prefabs, cached.Exact)
	if visual then return visual, "LIVE_PREFAB_GEOMETRY" end
	if count > 1 then return nil, nil, "Ambiguous prefab visuals in native pool" end
	visual, count = unique(self.MeshPrefabs, cached.Meshes)
	if visual then return visual, "LIVE_PREFAB_MESH_IDENTITY" end
	return nil, nil, count > 1 and "Ambiguous mesh visuals in native pool" or "No matching live prefab or spawn metadata"
end

local function nativeId(value)
	if type(value) == "string" and value ~= "" then return value end
	if type(value) == "number" and value == value and math.abs(value) < math.huge then return tostring(value) end
	return nil
end

local function guidShaped(name)
	local a, b, c, d, e = name:match("^(%x+)%-(%x+)%-(%x+)%-(%x+)%-(%x+)$")
	return a ~= nil and #a == 8 and #b == 4 and #c == 4 and #d == 4 and #e == 12
end

function PickupTracker:_discover(report, reject)
	local rendered = workspace:FindFirstChild("Rendered")
	local legacy = rendered and rendered:FindFirstChild("Pickups")
	local legacyObjects = legacy and legacy:GetChildren() or {}
	report.FolderPresent, report.LegacyObjects = legacy ~= nil, #legacyObjects
	report.RegistryEntries, report.RegistryActiveIds, report.ChunkerFolders, report.ChunkerObjects = 0, 0, 0, 0
	report.IdSources, report.CandidateIds, report.UnloadedEntries = {}, 0, 0
	report.NativeSpawnEvents, report.NativeSpawnRecords = self.NativeSpawnEvents, self.NativeSpawnRecords
	report.SpawnListener = self.SpawnConnection ~= nil
	local registry, registryStatus
	if self.Config.PICKUP_SETTINGS.ENABLE_NATIVE_REGISTRY_DISCOVERY then registry, registryStatus = self.Knowledge:ActivePickups()
	else registryStatus = "Native registry discovery disabled" end
	report.RegistryAvailable, report.RegistryStatus = registry ~= nil, registryStatus
	self.ActiveRegistry = registry
	local candidates, byModel, byId, collisions = {}, {}, {}, {}
	local function add(model, id, source, registryKey)
		local valid, isModel = pcall(function() return model:IsA("Model") end)
		if not valid or not isModel then
			if source == "LEGACY_PICKUP_MODEL" and valid then reject("Unexpected native pickup class " .. model.ClassName, model)
			else reject("Native source entry is not a Model", nil) end
			return
		end
		if not id or model.Name ~= id then reject("Native ID missing or registry key differs from Model.Name", model) return end
		if not model.Parent or not model:IsDescendantOf(workspace) then report.UnloadedEntries += 1 return end
		if byModel[model] then return end
		if byId[id] and byId[id] ~= model then collisions[id] = true end
		byId[id], byModel[model] = model, true
		table.insert(candidates, { Model = model, Id = id, IdSource = source, RegistryKey = registryKey })
		if source == "NATIVE_ACTIVE_REGISTRY" then report.RegistryActiveIds += 1 end
	end
	for id, model in pairs(registry or {}) do
		report.RegistryEntries += 1
		add(model, nativeId(id), "NATIVE_ACTIVE_REGISTRY", id)
	end
	if self.Config.PICKUP_SETTINGS.ENABLE_CHUNKER_DISCOVERY and rendered then
		-- Chunker owns multiple identically named folders; never use FindFirstChild here.
		for _, child in ipairs(rendered:GetChildren()) do
			if child.Name ~= "Chunker" or not child:IsA("Folder") then continue end
			report.ChunkerFolders += 1
			for _, model in ipairs(child:GetChildren()) do
				report.ChunkerObjects += 1
				local id = nativeId(model.Name)
				-- Chunkers also serve other game systems. A name alone never establishes currency.
				if id and (self.Metadata[id] or guidShaped(id)) then add(model, id, "NATIVE_CHUNKER_MODEL") end
			end
		end
	end
	for _, model in ipairs(legacyObjects) do add(model, nativeId(model.Name), "LEGACY_PICKUP_MODEL") end
	local objects = {}
	self.ModelIds = {}
	for _, candidate in ipairs(candidates) do
		if collisions[candidate.Id] then reject("Conflicting live Models share the same native ID", candidate.Model) continue end
		table.insert(objects, candidate.Model) self.ModelIds[candidate.Model] = candidate
		report.IdSources[candidate.IdSource] = (report.IdSources[candidate.IdSource] or 0) + 1
		report.CandidateIds += 1
	end
	report.RenderedObjects = #objects
	local metadataCount, unresolved = 0, 0
	for id in pairs(self.Metadata) do metadataCount += 1 if not byId[id] then unresolved += 1 end end
	report.MetadataIds, report.MetadataWithoutModel = metadataCount, unresolved
	return objects
end

function PickupTracker:IsActive(record)
	if not record.Model.Parent then return false end
	if record.IdSource and record.Model.Name ~= record.Id then return false end
	if record.IdSource == "NATIVE_ACTIVE_REGISTRY" then
		local registry = self.Knowledge:ActivePickups()
		return registry ~= nil and registry[record.RegistryKey or record.Id] == record.Model
	end
	return true
end

function PickupTracker:ForgetCollected(record)
	self.Models[record.Model], self.IdentityCache[record.Model], self.ModelIds[record.Model] = nil, nil, nil
	self.Metadata[record.Id], self.Backoff[record.Id] = nil, nil
end

function PickupTracker:_scan(now)
	if not self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS or not self.Config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING then return end
	self:_prefabs(now)
	local report = { At = now, Models = 0, CurrencyCount = 0, PositionsResolved = 0,
		Unidentified = 0, CurrentDetected = 0, CurrentCurrency = 0, Sources = {}, Rejected = {}, Examples = {}, Classes = {}, Currencies = {} }
	local function reject(reason, model)
		report.Rejected[reason] = (report.Rejected[reason] or 0) + 1
		if model and #report.Examples < 3 then table.insert(report.Examples, model:GetFullName() .. " | " .. reason) end
	end
	local objects = self:_discover(report, reject)
	local liveIds = {}
	for _, model in ipairs(objects) do liveIds[model.Name] = true end
	for id, metadata in pairs(self.Metadata) do
		if not liveIds[id] and now - metadata.At > 300 then self.Metadata[id] = nil end
	end
	local seen, root = {}, self:Root()
	for _, area in pairs(self.Areas) do
		area.Available = {} area.VisibleCount = 0 area.EligibleCount = 0 area.UnknownCount = 0 area.CurrencyCount = 0
	end
	for _, model in ipairs(objects) do
		report.Classes[model.ClassName] = (report.Classes[model.ClassName] or 0) + 1
		if not model:IsA("Model") then reject("Unexpected native pickup class " .. model.ClassName, model) continue end
		report.Models += 1
		local pivotOK, pivot = pcall(function() return model:GetPivot() end)
		if not pivotOK then reject("Model pivot unavailable", model) report.Unidentified += 1 continue end
		local position = pivot.Position
		report.PositionsResolved += 1
		local metadata = self.Metadata[model.Name]
		local nativeZone = metadata and self.ZoneInfo[metadata.Root]
		local area, zones = nativeZone and self.ZoneAreas[metadata.Root] or nil, {}
		if area then table.insert(zones, nativeZone) else
			local ambiguous = false
			for _, candidate in pairs(self.Areas) do
				for _, zone in ipairs(candidate.Zones) do
					local geometry = zone.Data.Zone
					if math.abs(position.Y - geometry.Height) <= self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS
						and geometry:GetDistanceToPoint(position) <= self.Config.PICKUP_SETTINGS.ZONE_MATCH_TOLERANCE_STUDS then
						if area and candidate ~= area then ambiguous = true end
						area = candidate table.insert(zones, zone)
					end
				end
			end
			if ambiguous then reject("Overlapping zones from different areas; metadata required", model) area = nil
			elseif not area then reject("Outside loaded native zone geometry/height", model) end
		end
		if not area then report.Unidentified += 1 continue end
		area.VisibleCount += 1
		if area == self.Current then report.CurrentDetected += 1 end
		local visual, source, identityReason = self:_identity(model, zones, metadata)
		local item, conflicting, transit = nil, false, true
		for _, zone in ipairs(zones) do
			if not zone.IsTransit then transit = false end
			for _, definition in ipairs(zone.Data.Pickups or {}) do
				if definition.Item and definition.Item.Visual == visual then
					local candidate = definition.Item.Item
					if item and (candidate.Type ~= item.Type or candidate.Currency ~= item.Currency or candidate.Amount ~= item.Amount) then conflicting = true end
					item = candidate
				end
			end
		end
		local discovery = self.ModelIds[model]
		local old = self.Models[model]
		if old and old.Id ~= discovery.Id then
			-- A changed native ID starts a new lifecycle, including a new frozen sweep.
			old = nil
			if self.Sweep then self.Sweep.Pending[model] = nil end
		end
		local record = old or { Model = model, Id = discovery.Id, FirstSeenAt = now }
		record.IdSource, record.RegistryKey = discovery.IdSource, discovery.RegistryKey
		record.Position, record.AreaKey, record.Visual, record.Source, record.IsTransit = position, area.Key, visual, source, transit
		record.Currency = not conflicting and item and item.Type == "Currency" and type(item.Currency) == "string" and item.Currency or nil
		record.Amount = record.Currency and type(item.Amount) == "number" and item.Amount or nil
		record.RouteEligible = record.Currency ~= nil and record.Amount ~= nil and not transit and allowed(self.Config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, record.Currency)
		if area == self.Current and root and math.abs(position.Y - root.Position.Y) > self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS then record.RouteEligible = false end
		seen[model] = true self.Models[model] = record
		if not old then
			self.ObservedSpawns += 1
			if area.LastDepletionAt then
				local interval = now - area.LastDepletionAt
				if interval > 0 then area.RespawnSeconds = interval self.RespawnObservations += 1 end
				area.LastDepletionAt = nil
			end
			area.LastSpawnAt = now
		end
		if record.Currency then
			report.CurrencyCount += 1 area.CurrencyCount += 1
			report.Currencies[record.Currency] = (report.Currencies[record.Currency] or 0) + 1
			if area == self.Current then report.CurrentCurrency += 1 end
			report.Sources[source or "UNKNOWN"] = (report.Sources[source or "UNKNOWN"] or 0) + 1
		else
			if not item or conflicting then report.Unidentified += 1 area.UnknownCount += 1 end
			reject(conflicting and "Conflicting native reward definitions" or (not item and (identityReason or "Visual absent from native zone pool") or "Native reward is not currency"), model)
		end
		if record.RouteEligible then
			area.EligibleCount += 1 area.Available[record.Currency] = (area.Available[record.Currency] or 0) + 1
		elseif record.Currency then
			reject(transit and "Jump-stage transit pickup; outside supported island surface" or (not allowed(self.Config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, record.Currency)
				and "Currency excluded by FARM_CURRENCY_TYPES" or "Invalid amount or incompatible current height"), model)
		end
	end
	for model, record in pairs(self.Models) do
		if not seen[model] then
			self.Disappeared += 1
			local area = self.Areas[record.AreaKey]
			if area and not model.Parent then area.LastDepletionAt = now end
			self.Models[model] = nil self.IdentityCache[model] = nil
			if self.Sweep then self.Sweep.Pending[model] = nil end
		end
	end
	for model in pairs(self.IdentityCache) do if not model.Parent then self.IdentityCache[model] = nil end end
	for id, metadata in pairs(self.Metadata) do if now - metadata.At > 300 then self.Metadata[id] = nil end end
	for id, failure in pairs(self.Backoff) do if now >= failure.Until then self.Backoff[id] = nil end end
	self.ScanReport = report
end

function PickupTracker:BackOff(records, seconds, reason)
	for _, record in ipairs(records) do
		self.Backoff[record.Id] = { Until = os.clock() + seconds, Reason = reason }
		if self.Sweep then self.Sweep.Pending[record.Model] = nil end
	end
end

function PickupTracker:ReadRange()
	local ok, range = pcall(function() return self.Knowledge:Get("StatsUtil"):GetPickupRange(self.Reader:GetLiveProfile()) end)
	self.Range = ok and type(range) == "number" and range > 0 and range < math.huge and range or nil
	self.RangeReason = self.Range and nil or "Actual StatsUtil pickup range unavailable"
	return self.Range
end

function PickupTracker:Cluster(currency)
	self.ClusterReason = nil
	local function unavailable(reason) self.ClusterReason = reason return nil end
	if not self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS or not self.Config.PICKUP_SETTINGS.ENABLE_CONTINUOUS_SCANNING then return unavailable("Collection/scanning disabled") end
	if not self:Root() or not self.Current then return unavailable("Character or current island geometry unavailable") end
	local range = self:ReadRange()
	local records = {}
	for _, record in pairs(self.Models) do
		if record.AreaKey == self.Current.Key and (record.Currency == "Coins" or record.Currency == "Gems")
			and allowed(self.Config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, record.Currency)
			and not record.IsTransit and self:IsActive(record) and not self.Backoff[record.Id] then table.insert(records, record) end
	end
	table.sort(records, function(a, b)
		if a.FirstSeenAt ~= b.FirstSeenAt then return (a.FirstSeenAt or 0) < (b.FirstSeenAt or 0) end
		return a.Id < b.Id
	end)
	if #records == 0 then return unavailable("No classified live current-island Coins/Gems IDs; stationary requests never approach pickups") end
	-- The compatibility name denotes a candidate set, never a navigation destination.
	return { Records = records, AreaKey = self.Current.Key, Currency = currency, Radius = range, ExperimentalStationary = true }
end

function PickupTracker:Destroy()
	self.Destroyed = true
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	table.clear(self.Models) table.clear(self.Metadata) table.clear(self.Backoff)
	table.clear(self.IdentityCache) table.clear(self.ModelIds)
end

return PickupTracker

end

-- src/OCFoundation/ProgressionGraph.luau
factories["ProgressionGraph"] = function()
--!nonstrict
-- Native definitions describe destinations/costs. LocalData alone confirms unlocks.
-- Height order is a travel frontier, never proof of a server prerequisite or a route.
local ProgressionGraph = {}

local function currencyReserve(config, currency)
	local key = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[currency]
	return key and config.RESOURCE_SETTINGS[key] or 0
end

function ProgressionGraph.Build(config, snapshot, definitions, observations)
	local graph = { Worlds = {}, Islands = {}, Capabilities = {}, Source = "Shared.Data.Worlds + LocalData + Workspace", Complete = false }
	if not snapshot.Ready or type(snapshot.UnlockedWorlds) ~= "table" or type(snapshot.UnlockedIslands) ~= "table" then
		graph.Blocker = "Real LocalData world/area unlock maps unavailable" return graph
	end
	if type(definitions) ~= "table" then graph.Blocker = "Native Worlds definitions unavailable" return graph end
	local observed, islandObservations = {}, {}
	for _, world in ipairs((observations or {}).Worlds or {}) do observed[world.Name] = world end
	for _, island in ipairs((observations or {}).Islands or {}) do islandObservations[island.World .. "/" .. island.Name] = island end
	local selected = {}
	for name, definition in pairs(definitions) do
		if type(definition) == "table" and not definition.Event and not definition.Removed
			and (#config.WORLD_SETTINGS.SELECTED_WORLDS == 0 or table.find(config.WORLD_SETTINGS.SELECTED_WORLDS, name)) then selected[name] = true end
	end
	-- Include actual gate-origin dependencies of requested destinations, not assumed world-order edges.
	local changed = true
	while changed do
		changed = false
		for name in pairs(selected) do
			local gate = observed[name] and observed[name].Gate
			local origin = gate and gate.OriginWorld
			local definition = origin and definitions[origin]
			if definition and not definition.Event and not definition.Removed and not selected[origin] then selected[origin], changed = true, true end
		end
	end
	for name in pairs(selected) do
		local definition, scene = definitions[name], observed[name]
		local world = { Id = name, Name = name, Order = definition.Order or 999, Kind = "WORLD",
			Unlocked = snapshot.UnlockedWorlds[name] ~= nil, UnlockKnown = true, Gate = scene and scene.Gate,
			ScenePresent = scene ~= nil, Cost = definition.UnlockCost, Islands = {},
			TravelAvailable = snapshot.UnlockedWorlds[name] ~= nil and scene ~= nil and scene.WorldTravelPath ~= nil,
			TravelPath = scene and scene.WorldTravelPath }
		world.State = world.Unlocked and "COMPLETE" or "BLOCKED"
		if not world.Unlocked then
			local gate, cost = world.Gate, world.Cost
			if not gate then world.Blocker = "Native WorldGate not observed; no unlock command inferred"
			elseif gate.Ambiguous then world.Blocker = "Multiple native WorldGate observations; destination contract ambiguous"
			elseif gate.ActivationObserved ~= true then world.Blocker = "Native gate Activation.Root unavailable; no supported unlock interaction observed"
			elseif not gate.OriginWorld or snapshot.UnlockedWorlds[gate.OriginWorld] == nil then world.Blocker = "Gate origin world is locked or unknown: " .. tostring(gate.OriginWorld)
			elseif gate.RequiredIsland and snapshot.UnlockedIslands[gate.RequiredIsland] == nil then world.Blocker = "Gate requires discovered island " .. gate.RequiredIsland
			elseif type(cost) ~= "table" or cost.Type ~= "Currency" or type(cost.Currency) ~= "string"
				or cost.Currency == "Robux" or type(cost.Amount) ~= "number" or cost.Amount ~= cost.Amount or cost.Amount < 0 or cost.Amount == math.huge then
				world.Blocker = "Native nonpremium currency cost unavailable"
			elseif type((snapshot.Balances or {})[cost.Currency]) ~= "number" or snapshot.Balances[cost.Currency] ~= snapshot.Balances[cost.Currency]
				or snapshot.Balances[cost.Currency] < 0 or snapshot.Balances[cost.Currency] == math.huge then world.Blocker = "Actual finite " .. cost.Currency .. " balance unavailable"
			else
				world.Reserve = currencyReserve(config, cost.Currency)
				world.Deficit = math.max(0, cost.Amount + world.Reserve - snapshot.Balances[cost.Currency])
				world.State = world.Deficit > 0 and "FUNDING" or "READY"
			end
		end
		for index, definitionIsland in ipairs(definition.Islands or {}) do
			local key = name .. "/" .. definitionIsland.Name
			local sceneIsland = islandObservations[key]
			local discovered = snapshot.UnlockedIslands[definitionIsland.Name] ~= nil
			local island = { Id = key, Name = definitionIsland.Name, World = name, Kind = "ISLAND", Index = index,
				Height = sceneIsland and sceneIsland.Height or definitionIsland.Height, DefinitionHeight = definitionIsland.Height,
				DiscoveryKnown = true, Discovered = discovered, NativePortalUnlocked = discovered,
				Reached = sceneIsland and sceneIsland.Reached or nil, -- position observation, independent of account discovery
				TravelAvailable = world.Unlocked and discovered and sceneIsland ~= nil and sceneIsland.TravelPath ~= nil,
				TravelPath = sceneIsland and sceneIsland.TravelPath, ScenePresent = sceneIsland ~= nil,
				DestinationPartObserved = sceneIsland and sceneIsland.DestinationPartObserved or false,
				Facilities = sceneIsland and sceneIsland.Facilities or {},
				State = discovered and "COMPLETE" or "BLOCKED",
				Blocker = not discovered and (world.Unlocked and (config.WORLD_SETTINGS.AUTO_DISCOVER_ISLANDS and name == "The Overworld"
					and "Undiscovered island: runtime contact capability and actual account acknowledgement must be checked"
					or "Undiscovered island: native ascent/discovery route and required bubble/jump capability unverified; manual discovery required") or "Origin world is locked") or nil }
			table.insert(world.Islands, island) table.insert(graph.Islands, island)
		end
		table.sort(world.Islands, function(a, b) return (a.Height or math.huge) < (b.Height or math.huge) end)
		table.insert(graph.Worlds, world)
	end
	table.sort(graph.Worlds, function(a, b) return a.Order == b.Order and a.Name < b.Name or a.Order < b.Order end)
	-- Discovery experiment uses the native definition array order, never scene child iteration.
	if config.WORLD_SETTINGS.AUTO_DISCOVER_ISLANDS then
		for _, world in ipairs(graph.Worlds) do
			if world.Name == "The Overworld" and world.Unlocked then
				local ordered = table.clone(world.Islands)
				table.sort(ordered, function(a, b) return a.Index < b.Index end)
				for _, island in ipairs(ordered) do if not island.Discovered then graph.Next = island break end end
			end
		end
	end
	-- Preserve the existing world-action policy when no experiment discovery remains.
	for _, state in ipairs({ "READY", "FUNDING" }) do
		if graph.Next then break end
		for _, world in ipairs(graph.Worlds) do if world.State == state then graph.Next = world break end end
		if graph.Next then break end
	end
	if not graph.Next then
		for _, world in ipairs(graph.Worlds) do
			if not world.Unlocked then graph.Next = world break end
			for _, island in ipairs(world.Islands) do if not island.Discovered then graph.Next = island break end end
			if graph.Next then break end
		end
	end
	if #graph.Worlds == 0 then graph.Blocker = "No selected permanent world has a verified native definition"
	else graph.Complete = graph.Next == nil end
	graph.Capabilities.Mastery = { Available = snapshot.UnlockedIslands["Outer Space"] ~= nil,
		Prerequisite = "AreasUnlocked[Outer Space]", Evidence = "ClientScript:2010 native Mastery visibility; executor deferred to Phase 5" }
	graph.Capabilities.Shops = (observations or {}).Upgrades or {}
	graph.Capabilities.WorldFacilities = { ["Minigame Paradise"] = { Available = snapshot.UnlockedWorlds["Minigame Paradise"] ~= nil, Features = { "Game Board", "Minigames" }, Executor = "DEFERRED" },
		["Seven Seas"] = { Available = snapshot.UnlockedWorlds["Seven Seas"] ~= nil, Features = { "Fishing", "Bounty quests" }, Executor = "DEFERRED" } }
	return graph
end

function ProgressionGraph.Goal(config, graph)
	if graph.Blocker then return { Id = "PROGRESSION:BLOCKED", Title = "Resolve progression evidence", Reason = graph.Blocker, State = "BLOCKED" } end
	local node = graph.Next
	if not node then return nil end
	local goal = { Id = "PROGRESSION:" .. node.Kind .. ":" .. node.Id, Title = (node.Kind == "WORLD" and "Unlock " or "Discover ") .. node.Name,
		State = node.State, Node = node, Reason = node.Blocker or string.format("Native gate requires %.0f %s; actual shortage=%.0f; origin/discovery prerequisites verified", node.Cost.Amount, node.Cost.Currency, node.Deficit) }
	if node.State == "FUNDING" and config.WORLD_SETTINGS.AUTO_FARM_UNLOCK_REQUIREMENTS then goal.Cost = node.Cost end
	return goal
end

return ProgressionGraph

end

-- src/OCFoundation/ResourceMetrics.luau
factories["ResourceMetrics"] = function()
--!nonstrict
-- Observed balance deltas, never pickup face values or predicted sale credit.
local ResourceMetrics = {}
ResourceMetrics.__index = ResourceMetrics

function ResourceMetrics.new(settings)
	return setmetatable({ Settings = settings, Samples = {}, Active = nil, Last = nil, Totals = {},
		ConfirmedCycles = 0, UnconfirmedCycles = 0, LastConfirmation = "No collection verified yet" }, ResourceMetrics)
end

function ResourceMetrics:Observe(balances, now)
	local previous = self.Last
	self.Last = { At = now, Balances = table.clone(balances) }
	if self.AttributionBlockedProvider and self.AttributionBlockedProvider() then return {} end
	if not previous or not self.Active then return {} end
	local dt = math.max(0, now - previous.At)
	local gains, spending = {}, false
	for currency, value in pairs(balances) do
		local old = previous.Balances[currency]
		if type(value) == "number" and type(old) == "number" then
			if value < old then spending = true end
			if value > old then gains[currency] = value - old end
		end
	end
	-- A purchase or externally observed spend makes this interval unsuitable for rate attribution.
	if spending then return {} end
	if dt > 0 then
		-- Combined income is recorded once, after a complete fill/sale/return cycle.
		if self.Active.Mode ~= "COMBINED" and self.Active.Mode ~= "STATIONARY" then
			table.insert(self.Samples, { At = now, Seconds = dt, Mode = self.Active.Mode,
				Scope = self.Active.Scope, Gains = gains })
		end
		for currency, value in pairs(gains) do self.Totals[currency] = (self.Totals[currency] or 0) + value end
	end
	self:Prune(now)
	return gains
end

function ResourceMetrics:AddSample(mode, scope, gains, seconds, now)
	if self.AttributionBlockedProvider and self.AttributionBlockedProvider() then return end
	if seconds <= 0 then return end
	table.insert(self.Samples, { At = now, Seconds = seconds, Mode = mode, Scope = scope, Gains = table.clone(gains) })
	self:Prune(now)
end

function ResourceMetrics:Prune(now)
	for index = #self.Samples, 1, -1 do
		if now - self.Samples[index].At > self.Settings.RATE_WINDOW_SECONDS then table.remove(self.Samples, index) end
	end
	while #self.Samples > 1024 do table.remove(self.Samples, 1) end
end

function ResourceMetrics:SetMode(mode, scope, balances, now)
	self:Observe(balances, now)
	if not mode then self.Active = nil return end
	if not self.Active or self.Active.Mode ~= mode or self.Active.Scope ~= scope then
		self.Active = { Mode = mode, Scope = scope, StartedAt = now }
	end
end

function ResourceMetrics:Rates(scope, now)
	self:Prune(now)
	local result = {}
	for _, sample in ipairs(self.Samples) do
		if sample.Scope == scope then
			local entry = result[sample.Mode] or { Seconds = 0, Earned = {}, PerMinute = {}, LastAt = sample.At }
			result[sample.Mode] = entry
			entry.Seconds += sample.Seconds
			entry.LastAt = math.max(entry.LastAt, sample.At)
			for currency, amount in pairs(sample.Gains) do entry.Earned[currency] = (entry.Earned[currency] or 0) + amount end
		end
	end
	for _, entry in pairs(result) do
		entry.Ready = entry.Seconds >= self.Settings.MINIMUM_RATE_SAMPLE_SECONDS
		if entry.Ready then
			for currency, amount in pairs(entry.Earned) do entry.PerMinute[currency] = amount * 60 / entry.Seconds end
		end
	end
	return result
end

function ResourceMetrics:ConfirmCycle(before, after, source)
	if self.AttributionBlockedProvider and self.AttributionBlockedProvider() then
		self.LastConfirmation = "Non-pickup reward attribution pending/uncertain; no farming credit published"
		return {}
	end
	local gains = {}
	for currency, value in pairs(after) do
		if type(before[currency]) == "number" and value > before[currency] then gains[currency] = value - before[currency] end
	end
	if next(gains) then
		self.ConfirmedCycles += 1
		local items = {}
		for currency, value in pairs(gains) do table.insert(items, string.format("+%.0f %s", value, currency)) end
		table.sort(items)
		self.LastConfirmation = source .. " | actual balance increased: " .. table.concat(items, ", ")
	else
		self.UnconfirmedCycles += 1
		self.LastConfirmation = source .. " | no positive balance change confirmed"
	end
	return gains
end

return ResourceMetrics

end

-- src/OCFoundation/RewardsManager.luau
factories["RewardsManager"] = function()
--!nonstrict
-- Narrow playtime/ordinary-box coordinator. Native commands/input remain in
-- GameMechanics; observation uses the existing reader and scheduler only.
local RewardsManager = {}
RewardsManager.__index = RewardsManager

local function finite(value)
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function count(value)
	return finite(value) and value >= 0 and value % 1 == 0
end

local function copy(value)
	if type(value) ~= "table" then return value end
	local result = {} for key, entry in pairs(value) do result[key] = copy(entry) end
	return result
end

local function facts(context)
	local raw, result = context.Raw or {}, { Balances = {}, Powerups = {}, Potions = {}, Pets = {}, Available = {} }
	result.Available.Balances = type(context.Balances) == "table"
	result.Available.Powerups = type(raw.Powerups) == "table"
	result.Available.Potions = type(raw.Potions) == "table"
	result.Available.Pets = type(raw.Pets) == "table"
	for name, value in pairs(context.Balances or {}) do if finite(value) then result.Balances[name] = value end end
	for name, value in pairs(type(raw.Powerups) == "table" and raw.Powerups or {}) do
		if count(value) then result.Powerups[name] = value end
	end
	for name, levels in pairs(type(raw.Potions) == "table" and raw.Potions or {}) do
		if type(levels) == "table" then
			for level, amount in pairs(levels) do if count(amount) then result.Potions[tostring(name) .. ":" .. tostring(level)] = amount end end
		end
	end
	for _, pet in pairs(type(raw.Pets) == "table" and raw.Pets or {}) do
		if type(pet) == "table" and type(pet.Id) == "string" and type(pet.Name) == "string" and count(pet.Amount or 1) then
			result.Pets[pet.Id] = { Name = pet.Name, Amount = pet.Amount or 1 }
		end
	end
	return result
end

local function deltas(before, after)
	local result = {}
	for _, category in ipairs({ "Balances", "Powerups", "Potions" }) do
		if not before.Available[category] or not after.Available[category] then continue end
		for name, value in pairs(after[category]) do
			local old = before[category][name]
			-- A missing inventory key can represent a newly received item; a missing
			-- currency baseline stays unknown, never substituted with zero.
			if old == nil and category ~= "Balances" then old = 0 end
			if finite(old) and value > old then table.insert(result, { Kind = category, Name = name, Amount = value - old }) end
		end
	end
	for id, pet in pairs(before.Available.Pets and after.Available.Pets and after.Pets or {}) do
		local old = before.Pets[id]
		if not old or old.Name == pet.Name then
			local gain = pet.Amount - (old and old.Amount or 0)
			if gain > 0 then table.insert(result, { Kind = "Pets", Id = id, Name = pet.Name, Amount = gain }) end
		end
	end
	table.sort(result, function(a, b) return a.Kind .. tostring(a.Id or a.Name) < b.Kind .. tostring(b.Id or b.Name) end)
	return result
end

function RewardsManager.new(controller)
	local self = setmetatable({ Controller = controller, Config = controller.Config, NextCheckAt = 0 }, RewardsManager)
	local player = controller.Reader and controller.Reader.Player
	self.UserId = player and player.UserId
	if not count(self.UserId) or self.UserId == 0 or type(shared) ~= "table" then
		self.Blocker = "Persistent account reward ledger unavailable; no reward dispatch"
		return self
	end
	local root = shared.__OC_LOCAL_REWARD_LEDGER
	if root ~= nil and (type(root) ~= "table" or root.Version ~= 1 or type(root.Accounts) ~= "table") then
		self.Blocker = "Existing reward ledger has an unknown schema; preserved without dispatch"
		self.UnknownBarrier = true
		return self
	end
	if not root then root = { Version = 1, Accounts = {} } shared.__OC_LOCAL_REWARD_LEDGER = root end
	local key = tostring(self.UserId)
	local ledger = root.Accounts[key]
	if ledger ~= nil and (type(ledger) ~= "table" or ledger.UserId ~= self.UserId or type(ledger.Sessions) ~= "table") then
		self.Blocker = "Existing account reward ledger is inconsistent; preserved without dispatch"
		self.UnknownBarrier = true
		return self
	end
	if not ledger then
		ledger = { UserId = self.UserId, Sessions = {}, ClaimsRequested = 0, ClaimsAcknowledged = 0, NextClaimAt = 0, NextBoxAt = 0 }
		root.Accounts[key] = ledger
	end
	local pending = ledger.Pending
	if pending ~= nil and (type(pending) ~= "table" or pending.UserId ~= self.UserId or not finite(pending.Deadline)
		or type(pending.Attempted) ~= "boolean" or type(pending.BeforeFacts) ~= "table" or type(pending.BeforeFacts.Available) ~= "table"
		or type(pending.BeforeFacts.Balances) ~= "table" or type(pending.BeforeFacts.Powerups) ~= "table"
		or type(pending.BeforeFacts.Potions) ~= "table" or type(pending.BeforeFacts.Pets) ~= "table"
		or pending.Kind ~= "PLAYTIME" and pending.Kind ~= "MYSTERY_BOX"
		or pending.Kind == "PLAYTIME" and (not count(pending.Index) or pending.Index < 1 or not finite(pending.CycleStart))
		or pending.Kind == "MYSTERY_BOX" and (pending.Count ~= 1 or not count(pending.BeforeOwned)
			or type(pending.BeforeGiftIds) ~= "table" or type(pending.SessionKey) ~= "string"
			or type(pending.GiftIdentityEpoch) ~= "string" or pending.GiftIdentityEpoch == "" or not count(pending.BeforeGiftRevision))) then
		self.Blocker, self.UnknownBarrier = "Malformed pending reward ledger preserved; no action or automatic retry", true
		return self
	end
	self.Ledger = ledger
	if pending and pending.Kind == "MYSTERY_BOX" then pending.GiftIdentityCurrent = false end
	return self
end

function RewardsManager:_context()
	local mechanics = self.Controller.Farming and self.Controller.Farming.Mechanics
	if not mechanics or type(mechanics.RewardsContext) ~= "function" then return nil, "Native reward context adapter unavailable" end
	local ok, context, reason = pcall(mechanics.RewardsContext, mechanics)
	if not ok or type(context) ~= "table" then return nil, tostring(reason or context or "Reward context unavailable") end
	if context.UserId ~= self.UserId or type(context.Raw) ~= "table" then return nil, "Ready reward account identity unavailable or changed" end
	return context
end

function RewardsManager:_session(key)
	if not self.Ledger then return nil end
	local session = self.Ledger.Sessions[key]
	if not session then session = { Requested = 0, Consumed = 0, OutcomesObserved = 0 } self.Ledger.Sessions[key] = session end
	return session
end

function RewardsManager:_playtime(context)
	if not self.Config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME then return nil end
	if context.CanClaim ~= true or context.HasPlaytime ~= true or context.IsTradingPlaza ~= false then return nil end
	if not finite(context.NativeNow) or type(context.PlaytimeGifts) ~= "table" then return nil end
	local playtime = context.Raw.PlaytimeRewards
	if type(playtime) ~= "table" or not finite(playtime.Start) or type(playtime.Claimed) ~= "table" then return nil end
	if context.NativeNow < playtime.Start then return nil end
	local eligible = {}
	for index, gift in pairs(context.PlaytimeGifts) do
		if count(index) and index >= 1 and type(gift) == "table" and finite(gift.Time) and gift.Time >= 0
			and playtime.Claimed[tostring(index)] == nil and context.NativeNow - playtime.Start >= gift.Time then
			table.insert(eligible, index)
		end
	end
	table.sort(eligible)
	if #eligible == 0 or os.clock() < (self.Ledger.NextClaimAt or 0) then return nil end
	return { Kind = "PLAYTIME", Index = eligible[1], CycleStart = playtime.Start, Reason = "Eligible sparse unclaimed playtime index" }
end

function RewardsManager:_box(context)
	local settings = self.Config.MYSTERY_BOX_SETTINGS
	if not settings.AUTO_OPEN_MYSTERY_BOXES or context.CanOpen ~= true or context.GiftCompletionAvailable ~= true then return nil end
	if context.GiftIdentityAvailable ~= true or type(context.GiftIdentityEpoch) ~= "string" or context.GiftIdentityEpoch == ""
		or not count(context.GiftRevision) then return nil end
	if context.IsTradingPlaza ~= false or not count(context.OwnedBoxes) or not count(context.GiftCount)
		or context.GiftCount ~= 0 or not count(context.MaxGiftCount) or context.MaxGiftCount < 1 or type(context.GiftIds) ~= "table" then return nil end
	if next(context.GiftIds) ~= nil then return nil end
	local session = self:_session(settings.SESSION_KEY)
	if not session or not count(session.Requested) or not count(settings.BOX_RESERVE) or not count(settings.MAXIMUM_SESSION_BOXES)
		or not count(settings.MAXIMUM_BATCH_BOXES) or settings.MAXIMUM_BATCH_BOXES < 1 then return nil end
	if not settings.ENABLE_AUTOMATIC_CONTINUATION and session.Requested > 0 then return nil end
	if os.clock() < (self.Ledger.NextBoxAt or 0) then return nil end
	-- Single boxes are the supported correlated operation. A higher maximum is
	-- a ceiling, not permission to assume multi-gift result correlation.
	local amount = math.min(1, context.OwnedBoxes - settings.BOX_RESERVE,
		settings.MAXIMUM_SESSION_BOXES - session.Requested, settings.MAXIMUM_BATCH_BOXES, context.MaxGiftCount)
	if amount < 1 then return nil end
	return { Kind = "MYSTERY_BOX", Count = amount, SessionKey = settings.SESSION_KEY, Reason = "Owned ordinary single box within protected allowance" }
end

function RewardsManager:Observe()
	if self.Destroyed or not self.Ledger then return end
	local pending = self.Ledger.Pending
	if not pending or not pending.Attempted then return end
	local context, reason = self:_context()
	if context then
		pending.RewardDeltas = deltas(pending.BeforeFacts, facts(context))
		pending.RewardObserved = #pending.RewardDeltas > 0
		if pending.Kind == "PLAYTIME" then
			local current = context.Raw.PlaytimeRewards
			if type(current) == "table" and current.Start == pending.CycleStart and type(current.Claimed) == "table"
				and current.Claimed[tostring(pending.Index)] ~= nil then
				pending.Acknowledged = true
				self.Ledger.ClaimsAcknowledged += 1
				pending.Status = "CLAIM_STATE_ACKNOWLEDGED"
				self:_finish(pending)
				return
			elseif type(current) == "table" and current.Start ~= pending.CycleStart then
				pending.Reason = "Playtime cycle changed before matching claim acknowledgement; no automatic retry"
			end
		else
			pending.GiftIdentityCurrent = false
			if not pending.ConsumptionAcknowledged and count(context.OwnedBoxes) and pending.BeforeOwned - context.OwnedBoxes >= pending.Count then
				pending.ConsumptionAcknowledged = true
				self:_session(pending.SessionKey).Consumed += pending.Count
			end
			local records = type(context.GiftRecords) == "table" and context.GiftRecords or {}
			local active = type(context.GiftIds) == "table" and context.GiftIds or nil
			local matches = {}
			local identityCurrent = context.GiftIdentityAvailable == true and context.GiftIdentityEpoch == pending.GiftIdentityEpoch
				and count(context.GiftRevision) and context.GiftRevision >= pending.BeforeGiftRevision
			if not identityCurrent then
				pending.InputBlocker = "Gift identity observer unavailable or reader lifetime changed; retained request will not be hit or resent"
			end
			if active and identityCurrent then
				for id in pairs(active) do
					local record = records[id]
					if type(id) == "string" and not pending.BeforeGiftIds[id] and type(record) == "table" and record.Id == id
						and record.Name == "Mystery Box" and record.IdentityEpoch == pending.GiftIdentityEpoch
						and count(record.Revision) and record.Revision > pending.BeforeGiftRevision and record.Revision <= context.GiftRevision then
						table.insert(matches, id)
					end
				end
			end
			for _, id in ipairs(matches) do
				if pending.GiftId and id ~= pending.GiftId then pending.AmbiguousGift = true end
			end
			if #matches > pending.Count then pending.Reason = "Multiple new ordinary gifts; request identity ambiguous; input disabled" pending.AmbiguousGift = true end
			if not pending.GiftId and #matches == 1 and not pending.AmbiguousGift then pending.GiftId = matches[1] pending.GiftSeen = true end
			if pending.GiftId and not pending.AmbiguousGift and table.find(matches, pending.GiftId) then pending.GiftIdentityCurrent = true end
			-- GiftCount is the native TOTAL registry count, not the loaded subset.
			-- A previously correlated ID may be observed gone after reload, but a
			-- new reader epoch never authorizes another Hit or a guessed identity.
			if pending.GiftSeen and active and context.GiftCount == 0 and active[pending.GiftId] == nil then pending.GiftFinished = true end
			if pending.ConsumptionAcknowledged and pending.GiftFinished and pending.RewardObserved and not pending.AmbiguousGift then
				pending.Acknowledged, pending.Status = true, "CONSUMPTION_AND_REWARD_DELTA_OBSERVED"
				local session = self:_session(pending.SessionKey)
				session.OutcomesObserved += 1
				self:_finish(pending)
				return
			end
		end
	else pending.Reason = reason pending.GiftIdentityCurrent = false end
	if os.clock() >= pending.Deadline then
		pending.Status = "UNCONFIRMED"
		pending.Reason = pending.Reason or (pending.ConsumptionAcknowledged and "Box consumed; completion/reward remains unknown, manual native completion may be required"
			or "Reward acknowledgement timed out; delivery/rejection unresolved; no automatic retry")
	end
end

function RewardsManager:_finish(pending)
	pending.FinishedAt = os.clock()
	pending.Attribution = "Observed in a non-pickup request window; manual/external rewards cannot be excluded; invocation is not receipt"
	self.Ledger.LastResult = copy(pending)
	-- Claimed acknowledgement is sufficient to advance playtime; a missing
	-- observed reward still makes earnings attribution unresolved across reload.
	if not pending.RewardObserved then self.Ledger.UnresolvedAttribution = true end
	self.Ledger.Pending = nil
	if pending.Kind == "PLAYTIME" then
		self.Ledger.NextClaimAt = math.max(self.Ledger.NextClaimAt or 0, os.clock() + self.Config.PLAYTIME_SETTINGS.CLAIM_INTERVAL_SECONDS)
	else
		self.Ledger.NextBoxAt = math.max(self.Ledger.NextBoxAt or 0, os.clock() + self.Config.MYSTERY_BOX_SETTINGS.OPEN_INTERVAL_SECONDS)
	end
	self.NextCheckAt = 0
	if type(self.Controller.MarkNonPickupReward) == "function" then self.Controller:MarkNonPickupReward({ Kind = "REWARD_SETTLED" }) end
	self:_report() -- Received results remain visible even when acknowledged during Pause.
end

function RewardsManager:Select(plan)
	if self.Destroyed then return false end
	local enabled = self.Config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME or self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES
	if not self.Ledger then
		if enabled then self:_blocker(self.Blocker) end
		return false, { Kind = "WAIT", Reason = self.Blocker }
	end
	if not enabled and not self.Ledger.Pending then return false, { Kind = "WAIT", Reason = "Reward actions disabled" } end
	self:Observe()
	local pending = self.Ledger.Pending
	if pending then
		return true, { Kind = "OBSERVE_REWARD", Reason = pending.Reason or "Awaiting one retained reward operation", Pending = pending }
	end
	local context, reason = self:_context()
	if not context then self:_blocker(reason) return false, { Kind = "WAIT", Reason = reason } end
	local playtime
	if os.clock() >= self.NextCheckAt then
		playtime = self:_playtime(context)
		self.NextCheckAt = os.clock() + self.Config.PLAYTIME_SETTINGS.CHECK_INTERVAL_SECONDS
	end
	local decision = playtime or self:_box(context)
	if decision then self.Blocker = nil
	else
		local blocker = context.Reason
		if not blocker and self.Config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME then
			if context.HasPlaytime ~= true then blocker = "Playtime capability unavailable or not unlocked"
			elseif context.CanClaim ~= true then blocker = "Native playtime interaction guards block claiming"
			elseif not finite(context.NativeNow) or type(context.Raw.PlaytimeRewards) ~= "table" then blocker = "Actual playtime clock/state unavailable" end
		end
		if not blocker and self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES then
			if context.GiftCompletionAvailable ~= true then blocker = "Verified native gift completion capability unavailable; no box consumed"
			elseif context.GiftIdentityAvailable ~= true or type(context.GiftIdentityEpoch) ~= "string" or context.GiftIdentityEpoch == ""
				or not count(context.GiftRevision) then blocker = "Public native gift identity observer unavailable; no box consumed"
			elseif not count(context.OwnedBoxes) then blocker = "Owned ordinary box count unavailable"
			elseif context.GiftCount ~= 0 then blocker = "Other gifts are active or gift count is unknown"
			elseif context.OwnedBoxes <= self.Config.MYSTERY_BOX_SETTINGS.BOX_RESERVE then blocker = "No owned ordinary box above reserve" end
		end
		self:_blocker(blocker)
	end
	return decision ~= nil, decision or { Kind = "WAIT", Reason = self.Blocker or "No eligible enabled reward action" }
end

function RewardsManager:_blocker(reason)
	self.Blocker = reason
	if reason and reason ~= self.LastLoggedBlocker then
		self.LastLoggedBlocker = reason
		self.Controller:Log("REWARD][BLOCKER", reason)
	end
end

function RewardsManager:Prepare(decision, token)
	if self.Destroyed or not self.Ledger or self.Ledger.Pending or token:CheckCancelled() or self.Controller.State ~= "RUNNING" then return nil end
	local context, reason = self:_context()
	if not context then return nil, nil, nil, reason end
	local fresh = decision.Kind == "PLAYTIME" and self:_playtime(context) or decision.Kind == "MYSTERY_BOX" and self:_box(context)
	if not fresh or fresh.Kind ~= decision.Kind or fresh.Index ~= decision.Index or fresh.CycleStart ~= decision.CycleStart
		or fresh.SessionKey ~= decision.SessionKey or fresh.Count ~= decision.Count then return nil, nil, nil, "Fresh reward eligibility/budget changed" end
	if token:CheckCancelled() then return nil end
	local settings = fresh.Kind == "PLAYTIME" and self.Config.PLAYTIME_SETTINGS or self.Config.MYSTERY_BOX_SETTINGS
	local pending = { Kind = fresh.Kind, Index = fresh.Index, CycleStart = fresh.CycleStart, Count = fresh.Count,
		SessionKey = fresh.SessionKey, UserId = self.UserId, BeforeFacts = facts(context), BeforeOwned = context.OwnedBoxes,
		BeforeGiftIds = copy(context.GiftIds or {}), StartedAt = os.clock(), Deadline = os.clock() + settings.CONFIRMATION_TIMEOUT_SECONDS,
		GiftIdentityEpoch = context.GiftIdentityEpoch, BeforeGiftRevision = context.GiftRevision,
		Status = "PREPARED", Attempted = false, RewardDeltas = {} }
	self.Ledger.Pending = pending
	if pending.Kind == "PLAYTIME" then return "ClaimPlaytime", pending.Index, nil, pending end
	return "UseGift", "Mystery Box", pending.Count, pending
end

function RewardsManager:MarkDispatched(pending)
	if not self.Ledger or self.Ledger.Pending ~= pending or pending.Attempted then return false end
	if pending.Kind == "MYSTERY_BOX" then
		local context = self:_context()
		local fresh = context and self:_box(context)
		if not fresh or fresh.SessionKey ~= pending.SessionKey or fresh.Count ~= pending.Count
			or context.GiftIdentityEpoch ~= pending.GiftIdentityEpoch or context.GiftRevision ~= pending.BeforeGiftRevision then return false end
	end
	pending.Attempted, pending.Status = true, "AWAITING_ACKNOWLEDGEMENT"
	if pending.Kind == "PLAYTIME" then
		self.Ledger.ClaimsRequested += 1
		self.Ledger.NextClaimAt = os.clock() + self.Config.PLAYTIME_SETTINGS.CLAIM_INTERVAL_SECONDS
	else
		self:_session(pending.SessionKey).Requested += pending.Count
		self.Ledger.NextBoxAt = os.clock() + self.Config.MYSTERY_BOX_SETTINGS.OPEN_INTERVAL_SECONDS
	end
	return true
end

function RewardsManager:AbortPreparation(pending, reason)
	if not self.Ledger or self.Ledger.Pending ~= pending or pending.Attempted then return false end
	self.Ledger.Pending = nil
	self:_blocker(reason or "Undispatched reward preparation released")
	return true
end

function RewardsManager:DispatchReturned(pending, invocationOk, result)
	if not self.Ledger or self.Ledger.Pending ~= pending then return end
	pending.InvocationOk = invocationOk
	-- Store a description, not a native profile/module/result handle in shared.
	pending.InvocationResultType = type(result)
	if not invocationOk then pending.Reason = "Reward invocation raised after attempt; delivery is uncertain; no automatic retry" end
	self:Observe()
end

function RewardsManager:Definition(decision, generation)
	if decision.Kind == "OBSERVE_REWARD" and decision.Pending and decision.Pending.Status == "UNCONFIRMED" then
		return nil -- Retain the barrier; existing received-state/five-second reader updates reconcile without a hot task cycle.
	end
	local timeout = decision.Kind == "PLAYTIME" and self.Config.PLAYTIME_SETTINGS.CONFIRMATION_TIMEOUT_SECONDS + 2 or 3
	return { Id = "OC_GAMEPLAY", Owner = "REWARDS", Generation = generation, Priority = 100,
		TimeoutSeconds = timeout,
		CanRun = function() return not self.Destroyed and self.Controller.State == "RUNNING" and self.Controller.Generation == generation end,
		Execute = function(token)
			if token:CheckCancelled() then return { Cancelled = true } end
			self:Observe()
			local mechanics = self.Controller.Farming.Mechanics
			local pending = self.Ledger and self.Ledger.Pending
			if not pending and decision.Kind ~= "OBSERVE_REWARD" then
				if type(mechanics.RewardAction) ~= "function" then return { Reason = "Native reward action adapter unavailable" } end
				mechanics:RewardAction(self, decision, token)
				pending = self.Ledger.Pending
			end
			local sliceEnd = os.clock() + 1
			while pending and pending.Attempted and pending.Kind == "MYSTERY_BOX" and pending.GiftId and not pending.AmbiguousGift
				and pending.GiftIdentityCurrent == true
				and pending.Status ~= "UNCONFIRMED" and self.Config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES
				and type(mechanics.AdvanceMysteryGift) == "function" and not token:CheckCancelled() and os.clock() < sliceEnd do
				local progressed, blocker = mechanics:AdvanceMysteryGift(pending, token)
				if not progressed and blocker then pending.InputBlocker = blocker break end
				self:Observe()
				if self.Ledger.Pending ~= pending or pending.GiftFinished then break end
				task.wait(0.1)
			end
			-- Controller replans after each slice. Keep unresolved observation paced
			-- inside that same foreground lease, including the no-gift and fault paths.
			if self.Ledger.Pending and not token:CheckCancelled() then task.wait(0.5) end
			self:Observe()
			return { Pending = self.Ledger.Pending ~= nil, LastResult = self.Ledger.LastResult, Reason = self.Ledger.Pending and self.Ledger.Pending.Reason }
		end,
		IsComplete = function(result) return type(result) == "table" end }
end

function RewardsManager:Completed(status, result, reason)
	self:Observe()
	self:_report()
end

function RewardsManager:_report()
	local last = self.Ledger and self.Ledger.LastResult
	if last and last.FinishedAt ~= self.LastLoggedResult then
		self.LastLoggedResult = last.FinishedAt
		local observed = {}
		for index, change in ipairs(last.RewardDeltas or {}) do
			if index > 10 then table.insert(observed, "additional deltas in GetStatus") break end
			table.insert(observed, string.format("%s:%s +%.2f", change.Kind, change.Name, change.Amount))
		end
		self.Controller:Log("REWARD][RESULT", string.format("%s | %s | claim acknowledgement=%s; box consumption=%s; reward delta observed=%s | %s | %s",
			last.Kind, last.Status, tostring(last.Kind == "PLAYTIME" and last.Acknowledged or false), tostring(last.ConsumptionAcknowledged or false),
			tostring(last.RewardObserved or false), #observed > 0 and table.concat(observed, "; ") or "No observed reward delta", last.Attribution))
	end
	local pending = self.Ledger and self.Ledger.Pending
	if pending and pending.Reason ~= self.LastLoggedReason then
		self.LastLoggedReason = pending.Reason
		if pending.Reason then self.Controller:Log("REWARD][UNCONFIRMED", pending.Reason) end
	end
end

function RewardsManager:AttributionBlocked()
	return self.UnknownBarrier == true or self.Ledger and (self.Ledger.Pending ~= nil or self.Ledger.UnresolvedAttribution == true) or false
end

function RewardsManager:Halt(stopped)
	-- Cancellation releases only a preparation that provably did not dispatch.
	-- Attempted requests, budgets and unknown outcomes survive every lifecycle.
	local pending = self.Ledger and self.Ledger.Pending
	if pending and not pending.Attempted then self.Ledger.Pending = nil end
	self:Observe()
end

function RewardsManager:Destroy()
	if self.Destroyed then return end
	self:Halt(true)
	self.Destroyed = true
end

function RewardsManager:GetStatus()
	local settings = self.Config.MYSTERY_BOX_SETTINGS
	local session = self.Ledger and self.Ledger.Sessions[settings.SESSION_KEY]
	local pending = self.Ledger and self.Ledger.Pending
	return { EnabledPlaytime = self.Config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME, EnabledBoxes = settings.AUTO_OPEN_MYSTERY_BOXES,
		SessionKey = settings.SESSION_KEY, BoxesRequested = session and session.Requested or 0, BoxesConsumed = session and session.Consumed or 0,
		BoxOutcomesObserved = session and session.OutcomesObserved or 0, ClaimsRequested = self.Ledger and self.Ledger.ClaimsRequested or 0,
		ClaimsAcknowledged = self.Ledger and self.Ledger.ClaimsAcknowledged or 0, AttributionBlocked = self:AttributionBlocked(), Blocker = self.Blocker,
		Pending = pending and { Kind = pending.Kind, Index = pending.Index, Count = pending.Count, Status = pending.Status,
			Deadline = pending.Deadline, Reason = pending.Reason, GiftId = pending.GiftId, ConsumptionAcknowledged = pending.ConsumptionAcknowledged,
			RewardObserved = pending.RewardObserved, InputBlocker = pending.InputBlocker },
		LastResult = self.Ledger and copy(self.Ledger.LastResult) }
end

return RewardsManager

end

-- src/OCFoundation/StationaryExperiment.luau
factories["StationaryExperiment"] = function()
--!nonstrict
-- Existing foreground collector, retained under its compatibility module name.
-- Discovery observes genuine Tutorial IDs; only the scheduler sends requests.
local StationaryExperiment = {}
StationaryExperiment.__index = StationaryExperiment

function StationaryExperiment.new(owner)
	return setmetatable({ Owner = owner, PerId = {}, Requests = 0, CreditWindows = 0, UncreditedWindows = 0, Gains = {} }, StationaryExperiment)
end

function StationaryExperiment:LimitReason()
	if os.clock() < (self.NextBatchAt or 0) then return "Stationary batch cooldown" end
	return nil
end

function StationaryExperiment:_eligible(record)
	local state = self.PerId[record.Id]
	if state and state.Model ~= record.Model then state = nil end -- A genuine replacement Model starts a new lifecycle.
	return record.Id ~= nil and (record.Currency == "Coins" or record.Currency == "Gems")
		and (not state or (not state.Dispatched and state.Attempts < self.Owner.Config.PICKUP_SETTINGS.STATIONARY_MAXIMUM_ATTEMPTS_PER_ID and os.clock() >= state.Until))
end

function StationaryExperiment:Candidate(cluster)
	local registry, now = self.Owner.Knowledge:ActivePickups(), os.clock()
	-- Preserve deduplication through short Chunker unloads, reclaim retired IDs.
	for id, state in pairs(self.PerId) do
		if registry and registry[state.Key] and registry[state.Key] ~= state.Model then self.PerId[id] = nil
		elseif registry and registry[state.Key] then state.LastSeen = now
		elseif registry and now - state.LastSeen > 60 then self.PerId[id] = nil end
	end
	local reason = self:LimitReason()
	if reason then return nil, reason end
	for _, record in ipairs(cluster and cluster.Records or {}) do
		if self:_eligible(record) then return record end
	end
	return nil, "Waiting for new genuine Coins/Gems IDs; existing requests are deduplicated"
end

function StationaryExperiment:Collect(decision, token, canContinue)
	local owner, settings = self.Owner, self.Owner.Config.PICKUP_SETTINGS
	if token:CheckCancelled() then return nil end
	local candidate, reason = self:Candidate(decision.Cluster)
	if not candidate then return { Verified = false, Reason = reason } end
	local before = owner.Reader:ReadBalances()
	if not owner.Tracker:Root() or type(before.Coins) ~= "number" or type(before.Gems) ~= "number" then return { Verified = false, Reason = "Ready LocalData Coins/Gems and root required; no request dispatched" } end
	local areaKey, started = owner.Tracker.Current.Key, os.clock()
	local rewardEpoch = owner.Controller.RewardAttributionEpoch or 0
	local deadline = started + owner.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS
	local raw = owner.Reader:GetLiveProfile()
	local initialBubble = raw and raw.Bubble and raw.Bubble.Amount
	local saleSequence, previousBubble = owner.SaleSequence or 0, initialBubble
	local previous, after = before, before
	local contaminated, missing, areaChanged = decision.HatchSpending == true, false, false
	local ids, currencies, outside, invocationSucceeded, cleaned = {}, {}, 0, true, 0
	local function observe()
		if rewardEpoch ~= (owner.Controller.RewardAttributionEpoch or 0)
			or owner.Controller.RewardAttributionBlocked and owner.Controller:RewardAttributionBlocked() then contaminated = true end
		after = owner.Reader:ReadBalances()
		for _, currency in ipairs({ "Coins", "Gems" }) do
			if type(after[currency]) ~= "number" then missing = true
			elseif type(previous[currency]) == "number" and after[currency] < previous[currency] then contaminated = true end
		end
		previous = after
		local live = owner.Reader:GetLiveProfile()
		local amount = live and live.Bubble and live.Bubble.Amount
		if owner.PendingSale or saleSequence ~= (owner.SaleSequence or 0) or (type(previousBubble) == "number" and type(amount) == "number" and amount < previousBubble) then contaminated = true end
		previousBubble = amount
		if owner.Cycle and type(initialBubble) == "number" and type(amount) == "number" and amount > initialBubble then owner.Cycle.GrowthAt = os.clock() end
		local current = owner.Tracker.Current
		if not owner.Tracker:Root() or not current or current.Key ~= areaKey then areaChanged = true end
	end
	for _, record in ipairs(decision.Cluster.Records) do
		if token:CheckCancelled() or os.clock() >= deadline or #ids >= settings.STATIONARY_MAXIMUM_BATCH_SIZE then break end
		if not self:_eligible(record) then continue end
		local delay = settings.STATIONARY_REQUEST_COOLDOWN_SECONDS - (os.clock() - (owner.Mechanics.LastPickupRequestAt or -math.huge))
		while delay > 1e-6 and not token:CheckCancelled() and os.clock() < deadline do
			task.wait(math.min(0.05, delay, deadline - os.clock())) observe()
			delay = settings.STATIONARY_REQUEST_COOLDOWN_SECONDS - (os.clock() - (owner.Mechanics.LastPickupRequestAt or -math.huge))
		end
		if token:CheckCancelled() or areaChanged or os.clock() >= deadline then break end
		if canContinue and not canContinue() then
			reason = "Active world funding shortage ended or is no longer verified; no further pickup dispatch"
			owner.Controller:Log("FARM][FUNDING", reason)
			break
		end
		local requested, invocation, evidence = owner.Mechanics:CollectStationary(record, token)
		if not requested then
			reason = invocation
			if owner.Mechanics.PendingPickupCleanup then break end
			continue
		end
		self.StartedAt = self.StartedAt or started
		self.Requests += 1
		local state = self.PerId[record.Id]
		if not state or state.Model ~= record.Model then state = setmetatable({ Attempts = 0, Key = record.RegistryKey or record.Id, Model = record.Model }, { __mode = "v" }) end
		self.PerId[record.Id] = state
		state.Attempts += 1 state.Until = os.clock() + settings.STATIONARY_ID_RETRY_SECONDS state.LastSeen = os.clock()
		state.Dispatched = evidence.InvocationSucceeded -- Invocation deduplication, never credit evidence.
		table.insert(ids, record.Id) currencies[record.Currency] = true
		if evidence.OutsideNativeRange then outside += 1 end
		invocationSucceeded = invocationSucceeded and evidence.InvocationSucceeded
		if evidence.VisualCleaned then cleaned += 1 end
		if evidence.CleanupError then owner.Controller:Log("PICKUP][CLEANUP_ERROR", "id=" .. tostring(record.Id) .. " | " .. evidence.CleanupError .. "; dispatch is not credit") end
		owner.Controller:Log("PICKUP][STATIONARY_REQUEST", string.format("id=%s currency=%s distance=%.2f radius=%s outsideNative=%s | %s",
			tostring(record.Id), record.Currency, evidence.Distance, tostring(evidence.Radius), tostring(evidence.OutsideNativeRange), invocation))
		observe()
		if decision.Mode == "COMBINED" and not settings.STATIONARY_ISOLATED_TEST then owner:_background(token) end
	end
	if #ids == 0 then return { Verified = false, Reason = reason or "No eligible live registry IDs dispatched" } end
	local processingSeconds = os.clock() - started
	self.NextBatchAt = os.clock() + settings.STATIONARY_BATCH_COOLDOWN_SECONDS
	owner.CollectionVisits += 1
	deadline = math.min(deadline, os.clock() + owner.Config.FARMING_SETTINGS.EARNINGS_CONFIRMATION_TIMEOUT_SECONDS)
	while not token:CheckCancelled() and not areaChanged do
		observe()
		if os.clock() >= deadline then break end
		if decision.Mode == "COMBINED" and not settings.STATIONARY_ISOLATED_TEST then owner:_background(token) end
		task.wait(math.min(0.1, deadline - os.clock()))
	end
	local cancelled = token:CheckCancelled()
	observe() -- Include the final available LocalData values even for a cancelled/inconclusive batch.
	local deltas = {}
	for _, currency in ipairs({ "Coins", "Gems" }) do
		if type(after[currency]) == "number" then deltas[currency] = after[currency] - before[currency] end
	end
	local gains, creditedAfter = {}, {}
	if not cancelled and not contaminated and not missing and not areaChanged then
		for currency in pairs(currencies) do
			local gain = after[currency] - before[currency]
			if gain > 0 then gains[currency] = gain creditedAfter[currency] = after[currency] end
		end
	end
	local credit = next(gains) ~= nil
	if cancelled then
		reason = "Cancelled; dispatched IDs retained and credit window discarded"
	elseif credit then
		self.CreditWindows += 1
		owner.Metrics:ConfirmCycle(before, creditedAfter, "Stationary batch LocalData credit observed; request/native/external attribution unproven")
		for currency, gain in pairs(gains) do
			self.Gains[currency] = (self.Gains[currency] or 0) + gain owner.PickupEvidence[areaKey .. ":" .. currency] = os.clock()
			if owner.PickupProbe and owner.PickupProbe.Currency == currency then owner.PickupProbe.Confirmed = true owner.PickupProbe.Attempts = (owner.PickupProbe.Attempts or 0) + 1 end
		end
		if decision.Mode == "COMBINED" and owner.Cycle then owner.Cycle.PickupAt = os.clock() end
	else
		self.UncreditedWindows += 1 owner.Metrics.UnconfirmedCycles += 1
		owner.Metrics.LastConfirmation = areaChanged and "Current credit window discarded after island/root change; farming resumes on eligible IDs"
			or contaminated and "Stationary window contaminated by sale/spending; credit unconfirmed"
			or missing and "LocalData unavailable; stationary credit unconfirmed" or "No matching LocalData credit; server acceptance unknown; no movement fallback"
	end
	if not cancelled and not contaminated and not missing and not areaChanged then
		local sampleStart = self.LastSampleArea == areaKey and self.LastSampleAt or started
		owner.Metrics:AddSample("STATIONARY", areaKey, gains, os.clock() - sampleStart, os.clock())
		self.LastSampleAt, self.LastSampleArea = os.clock(), areaKey
	end
	self.NextBatchAt = os.clock() + settings.STATIONARY_BATCH_COOLDOWN_SECONDS
	local outcome = cancelled and "CANCELLED_INCONCLUSIVE" or credit and "MATCHING_BALANCE_INCREASE"
		or (contaminated or missing or areaChanged) and "INCONCLUSIVE_WINDOW" or "INCONCLUSIVE_NO_MATCHING_CREDIT"
	self.LastResult = { Ids = ids, BatchSize = #ids, CreditObserved = credit, Gains = gains, Before = before, After = after,
		ObservedDeltas = deltas, ProcessingSeconds = processingSeconds, WindowSeconds = os.clock() - started, Outcome = outcome, Cancelled = cancelled,
		VisualsCleaned = cleaned, OutsideNativeRange = outside > 0, OutsideNativeCount = outside, Contaminated = contaminated or missing or areaChanged,
		InvocationSucceeded = invocationSucceeded, Reason = cancelled and reason or owner.Metrics.LastConfirmation, Attribution = "UNPROVEN: native collection/external rewards can contribute; OC playtime/box overlap excluded" }
	owner.Controller:Log("PICKUP][STATIONARY_RESULT", string.format("batch=%d visualsCleaned=%d processing=%.3fs window=%.3fs outcome=%s creditObserved=%s outsideNative=%d | Coins gained=%s (%s -> %s) | Gems gained=%s (%s -> %s) | %s",
		#ids, cleaned, processingSeconds, os.clock() - started, outcome, tostring(credit), outside, tostring(deltas.Coins or "UNKNOWN"), tostring(before.Coins), tostring(after.Coins),
		tostring(deltas.Gems or "UNKNOWN"), tostring(before.Gems), tostring(after.Gems), self.LastResult.Reason))
	if cancelled then return nil end
	return { Verified = credit, CreditObserved = credit, CombinedCreditObserved = credit and decision.Mode == "COMBINED", Gains = gains, Reason = owner.Metrics.LastConfirmation }
end

function StationaryExperiment:GetStatus()
	return { Experimental = true, Requests = self.Requests, StartedAt = self.StartedAt, CreditWindows = self.CreditWindows,
		BatchLimit = self.Owner.Config.PICKUP_SETTINGS.STATIONARY_MAXIMUM_BATCH_SIZE, Continuous = true,
		UncreditedWindows = self.UncreditedWindows, Gains = table.clone(self.Gains), LastResult = self.LastResult,
		Blocker = self:LimitReason(), ServerAcceptance = "UNKNOWN", MovementFallback = false }
end

return StationaryExperiment

end

-- src/OCFoundation/TaskScheduler.luau
factories["TaskScheduler"] = function()
--!nonstrict
-- Cooperative cancellation retains the foreground lease until Execute returns.
local TaskScheduler = {}
TaskScheduler.__index = TaskScheduler

function TaskScheduler.new(settings)
	local self = setmetatable({}, TaskScheduler)
	self.Settings = settings
	self.Changed = Instance.new("BindableEvent")
	self.Completed = Instance.new("BindableEvent")
	self.Queue = {}
	self.Active = nil
	self.Enabled = false
	self.Destroyed = false
	self.Sequence = 0
	return self
end

function TaskScheduler:GetStatus()
	return {
		ActiveTask = self.Active and self.Active.Definition.Id or nil,
		ActiveOwner = self.Active and self.Active.Definition.Owner or nil,
		CancellationPending = self.Active ~= nil and self.Active.Token.Cancelled,
		PendingCount = #self.Queue,
		Enabled = self.Enabled,
	}
end

function TaskScheduler:_pump()
	if self.Destroyed or not self.Enabled or self.Active or #self.Queue == 0 then return end
	table.sort(self.Queue, function(a, b)
		if a.Priority == b.Priority then return a.Sequence < b.Sequence end
		return a.Priority > b.Priority
	end)
	local definition = table.remove(self.Queue, 1)
	local token = { Cancelled = false, Reason = nil }
	function token:CheckCancelled()
		return self.Cancelled
	end
	local active = { Definition = definition, Token = token }
	self.Active = active
	self.Changed:Fire(self:GetStatus())
	active.TimeoutThread = task.delay(definition.TimeoutSeconds or self.Settings.TASK_TIMEOUT_SECONDS, function()
		if self.Active == active then self:CancelActive("Task timed out") end
	end)
	-- Defer so the timeout/thread handles are installed before a synchronous task finishes.
	active.Thread = task.defer(function()
		local skipped = false
		local ok, result = xpcall(function()
			if token.Cancelled then return nil end
			if definition.CanRun and not definition.CanRun() then skipped = true return nil end
			local output = definition.Execute(token)
			if token.Cancelled then return nil end
			if definition.IsComplete and not definition.IsComplete(output) then
				error("Task returned without satisfying its completion check")
			end
			return output
		end, debug.traceback)
		if active.TimeoutThread then pcall(task.cancel, active.TimeoutThread) end
		if self.Active == active then self.Active = nil end
		if self.Destroyed then return end
		local status = token.Cancelled and "CANCELLED" or (skipped and "SKIPPED" or (ok and "COMPLETED" or "FAILED"))
		self.Completed:Fire(definition.Id, status, result, token.Reason, definition)
		self.Changed:Fire(self:GetStatus())
		self:_pump()
	end)
end

function TaskScheduler:Submit(definition)
	if self.Destroyed or not self.Settings.ENABLE_TASK_SCHEDULER then return false, "Scheduler unavailable" end
	assert(type(definition.Id) == "string" and type(definition.Execute) == "function", "Invalid task")
	assert(type(definition.Priority) == "number", "Task priority must be numeric")
	for index, pending in ipairs(self.Queue) do
		if pending.Id == definition.Id then table.remove(self.Queue, index) break end
	end
	if #self.Queue >= self.Settings.MAXIMUM_PENDING_TASKS then return false, "Queue is full" end
	self.Sequence += 1
	definition.Sequence = self.Sequence
	table.insert(self.Queue, definition)
	self.Changed:Fire(self:GetStatus())
	self:_pump()
	return true
end

function TaskScheduler:CancelActive(reason)
	if not self.Active then return end
	self.Active.Token.Cancelled = true
	self.Active.Token.Reason = reason or "Cancelled"
	self.Changed:Fire(self:GetStatus())
end

function TaskScheduler:Pause()
	self.Enabled = false
	table.clear(self.Queue)
	self:CancelActive("Paused")
	self.Changed:Fire(self:GetStatus())
end

function TaskScheduler:Resume()
	if self.Destroyed or not self.Settings.ENABLE_TASK_SCHEDULER then return end
	self.Enabled = true
	self.Changed:Fire(self:GetStatus())
	self:_pump()
end

function TaskScheduler:Stop()
	self.Enabled = false
	table.clear(self.Queue)
	self:CancelActive("Stopped")
	self.Changed:Fire(self:GetStatus())
end

function TaskScheduler:Destroy()
	if self.Destroyed then return end
	self:Stop()
	self.Destroyed = true
	if self.Active then
		if self.Active.TimeoutThread then pcall(task.cancel, self.Active.TimeoutThread) end
		if self.Active.Thread then pcall(task.cancel, self.Active.Thread) end
		self.Active = nil
	end
	self.Changed:Destroy()
	self.Completed:Destroy()
end

return TaskScheduler

end

-- src/OCFoundation/TravelPlanner.luau
factories["TravelPlanner"] = function()
--!nonstrict
-- Pure Phase 3 action policy, called only by OCBrain. No character control or commands.
local TravelPlanner = {}

function TravelPlanner.Decide(config, snapshot, plan, context)
	local goal = plan and plan.Objective and plan.Objective.Metadata and plan.Objective.Metadata.Progression
	if not goal then return nil end -- Phase 2 retains its own approved decision path.
	local decision = { Kind = "WAIT", GoalId = plan.Objective.Id, Reason = goal.Reason, Node = goal.Node }
	if not goal.Node then return decision end
	local fresh = snapshot.ProgressionGraph and snapshot.ProgressionGraph.Next
	if not fresh or not goal.Node or fresh.Id ~= goal.Node.Id or fresh.Kind ~= goal.Node.Kind then
		decision.Reason = "Progression state changed; waiting for a fresh Brain objective" return decision
	end
	decision.Node = fresh
	if fresh.Kind == "ISLAND" and config.WORLD_SETTINGS.AUTO_DISCOVER_ISLANDS then
		if not context.CanInteract then decision.Reason = context.Blocker or "Native interaction guard blocks discovery"
		elseif not context.Discovery then decision.Reason = context.Blocker or "Loaded island discovery hitbox unavailable"
		elseif context.DiscoveryAttempts >= config.WORLD_SETTINGS.MAXIMUM_ISLAND_DISCOVERY_ATTEMPTS then decision.Reason = "Island contact attempt limit reached; no confirmed account discovery"
		elseif context.DiscoveryBackoff then decision.Reason = "Island discovery retry/global pacing; actual account flags still observed"
		else decision.Kind, decision.Reason = "DISCOVER_ISLAND", "Experimental runtime contact with the genuine island UnlockHitbox; awaiting correct LocalData acknowledgement" end
		return decision
	end
	if fresh.State == "BLOCKED" then decision.Reason = fresh.Blocker return decision end
	if fresh.State == "FUNDING" then
		if config.WORLD_SETTINGS.AUTO_FARM_UNLOCK_REQUIREMENTS then return nil end -- Existing goal-driven stationary collector.
		decision.Reason = "Actual world-cost shortage; AUTO_FARM_UNLOCK_REQUIREMENTS=false" return decision
	end
	if fresh.State ~= "READY" then return decision end
	local settings, cost = config.WORLD_SETTINGS, fresh.Cost
	if not settings.AUTO_UNLOCK_WORLDS then decision.Reason = "World affordable; AUTO_UNLOCK_WORLDS=false (no farming or spending)" return decision end
	if not table.find(settings.ALLOWED_UNLOCK_CURRENCIES, cost.Currency) or cost.Amount > settings.MAXIMUM_WORLD_UNLOCK_COST then
		decision.Reason = "World affordable; native cost/currency exceeds explicit unlock authorization" return decision
	end
	if context.SessionRequests >= settings.MAXIMUM_SESSION_WORLD_UNLOCKS then decision.Reason = "Controller lifetime unlock request limit reached" return decision end
	if context.UnlockAttempts >= settings.MAXIMUM_UNLOCK_ATTEMPTS then decision.Reason = "Per-world unlock request limit reached" return decision end
	if context.UnlockBackoff then decision.Reason = "World unlock request in retry backoff; actual acknowledgement still observed" return decision end
	if not context.Gate then decision.Reason = context.Blocker or "Live native gate unavailable" return decision end
	if not context.CanInteract then decision.Reason = context.Blocker or "Native interaction guard blocks progression" return decision end
	if context.Gate.InRange then decision.Kind, decision.Reason = "UNLOCK_WORLD", "Actual funds available and native gate activation range observed"
	elseif context.Gate.AtOriginIsland then
		local gate = context.Gate
		decision.GateApproach = { Status = "MANUAL_REQUIRED", HorizontalDistance = gate.HorizontalDistance,
			VerticalDifference = gate.VerticalDifference, HorizontalLimit = gate.HorizontalLimit, VerticalLimit = gate.VerticalLimit }
		decision.Reason = string.format("At discovered gate island, outside native Activation.Root range; manual gate approach required; horizontal=%s/%s studs, vertical=%s/%s studs; automatic walking is unsupported",
			tostring(gate.HorizontalDistance or "unknown"), tostring(gate.HorizontalLimit or "unknown"), tostring(gate.VerticalDifference or "unknown"), tostring(gate.VerticalLimit or "unknown"))
	elseif not settings.AUTO_TRAVEL_FOR_PROGRESSION then decision.Reason = "World affordable; native gate-island travel requires AUTO_TRAVEL_FOR_PROGRESSION=true"
	elseif context.TravelBackoff then decision.Reason = "Progression portal travel in retry backoff"
	elseif context.TravelFailures >= settings.MAXIMUM_TRAVEL_ATTEMPTS then decision.Reason = "Progression travel failure limit reached; manual travel required"
	elseif not context.Gate.Spawn and (not context.Gate.DestinationPath or #context.Gate.Zones == 0) then decision.Reason = "Native discovered-island portal arrival geometry unavailable; no unverified travel"
	else decision.Kind, decision.Reason = "TRAVEL_GATE_ISLAND", "Travel through the native portal to the already-discovered gate island" end
	return decision
end

return TravelPlanner

end

-- src/OCFoundation/UpgradePolicy.luau
factories["UpgradePolicy"] = function()
--!nonstrict
-- Pure catalog evaluation for the existing Brain. No purchases or profile mutations.
local UpgradePolicy = {}
local function allowed(list, name) return #list == 0 or table.find(list, name) ~= nil end
local function reserve(config, currency)
	local key = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[currency]
	return key and config.RESOURCE_SETTINGS[key] or 0
end

function UpgradePolicy.Evaluate(config, snapshot, plan, context, currency, mode, sell, goal)
	local settings, bubble, rows, best = config.UPGRADE_SETTINGS, snapshot.Bubble or {}, {}, nil
	for _, upgrade in ipairs((snapshot.AvailableProgression or {}).Upgrades or {}) do
		local row = { Name = upgrade.Name, Kind = upgrade.Kind, Cost = upgrade.Cost, Owned = upgrade.Owned, Reasons = {} }
		table.insert(rows, row)
		local function reject(reason) table.insert(row.Reasons, reason) end
		if not settings.ENABLE_SMART_UPGRADES then reject("ENABLE_SMART_UPGRADES=false") end
		if not config.BRAIN_SETTINGS.ENABLE_EARNING_RECOMMENDATIONS or not config.BUBBLE_SETTINGS.ENABLE_BUBBLE_RECOMMENDATIONS then reject("Upgrade recommendations disabled") end
		if upgrade.Kind == "Gum" and not settings.ENABLE_CAPACITY_UPGRADES then reject("ENABLE_CAPACITY_UPGRADES=false") end
		if upgrade.Kind == "Flavors" and not settings.ENABLE_FLAVOR_UPGRADES then reject("ENABLE_FLAVOR_UPGRADES=false") end
		if not upgrade.Accessible then reject(upgrade.AccessKnown == false and "Area access unknown" or "Required area locked") end
		if not upgrade.OwnershipKnown then reject("Ownership map unavailable") end
		if not allowed(settings.SELECTED_UPGRADES, upgrade.Name) then reject("Excluded by SELECTED_UPGRADES") end
		if not allowed(config.BRAIN_SETTINGS.SELECTED_UPGRADES, upgrade.Name) then reject("Excluded by BRAIN_SETTINGS.SELECTED_UPGRADES") end
		if (context.UpgradeBackoff or {})[upgrade.Name] then reject("Purchase/equip retry cooldown") end
		local current = upgrade.Kind == "Gum" and bubble.BaseCapacity or bubble.BaseOutput
		if not current or current <= 0 or not upgrade.BaseStat then reject("Actual equipped base stat or native candidate stat unavailable")
		else
			row.BaseGain = upgrade.BaseStat / current - 1
			if row.BaseGain < config.BRAIN_SETTINGS.MINIMUM_UPGRADE_GAIN_RATIO then reject("Base gain below MINIMUM_UPGRADE_GAIN_RATIO") end
		end
		row.BlowsPerFill = bubble.Capacity and bubble.PowerPerBlow and bubble.PowerPerBlow > 0 and bubble.Capacity / bubble.PowerPerBlow or nil
		row.CapacityUrgent = row.BlowsPerFill ~= nil and row.BlowsPerFill < config.BRAIN_SETTINGS.MINIMUM_BLOWS_PER_FILL
		-- This threshold describes urgency, not a ban on every economically useful gum upgrade.
		if upgrade.Owned then
			if not settings.AUTO_EQUIP_OWNED_UPGRADES then reject("AUTO_EQUIP_OWNED_UPGRADES=false") end
			if mode == "PICKUPS" then reject("Selected pickup-only strategy has no verified bubble benefit") end
			row.Payback = 0
		else
			local enabled = upgrade.Kind == "Gum" and config.BUBBLE_SETTINGS.AUTO_BUY_GUM or (upgrade.Kind == "Flavors" and config.BUBBLE_SETTINGS.AUTO_BUY_FLAVORS)
			if not enabled then reject(upgrade.Kind == "Gum" and "AUTO_BUY_GUM=false" or "AUTO_BUY_FLAVORS=false") end
			local cost = upgrade.Cost
			if not cost or cost.Type ~= "Currency" or type(cost.Amount) ~= "number" or cost.Amount < 0 or type(cost.Currency) ~= "string" then
				reject("Verified nonpremium currency cost unavailable")
			else
				if cost.Currency == "Robux" or not table.find(settings.ALLOWED_PURCHASE_CURRENCIES, cost.Currency) then reject("Purchase currency not explicitly authorized") end
				if cost.Currency ~= currency then reject("Purchase currency does not support current resource objective") end
				row.Balance, row.Reserve = snapshot.Balances[cost.Currency], reserve(config, cost.Currency)
				row.GoalReserve = 0
				if settings.ENABLE_GOAL_RESERVATION then
					for _, reserved in pairs({ plan.Objective, goal }) do
						local metadata = reserved and reserved.Metadata
						local goalCost = metadata and metadata.Cost
						if goalCost and not metadata.Upgrade and goalCost.Currency == cost.Currency then row.GoalReserve = math.max(row.GoalReserve, goalCost.Amount or 0) end
					end
					row.GoalReserve = math.min(row.GoalReserve, math.max(0, (row.Balance or 0) - row.Reserve) * settings.MAXIMUM_GOAL_RESERVE_BALANCE_FRACTION)
				end
				local major = plan.MajorUnlockReservation
				if major and major.Currency == cost.Currency then row.GoalReserve = math.max(row.GoalReserve, major.Amount or 0) end
				row.Spendable = math.max(0, (row.Balance or 0) - row.Reserve - row.GoalReserve)
				row.Budget = row.Spendable * config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION
				if row.Balance == nil then reject("Actual currency balance unavailable") end
				if cost.Amount > row.Budget then reject("Cost exceeds post-reserve balance fraction budget") end
				if cost.Amount > settings.MAXIMUM_PURCHASE_COST then reject("Cost exceeds MAXIMUM_PURCHASE_COST") end
				local sample = (context.Rates or {}).BUBBLES
				row.BubbleIncome = sample and sample.Ready and sample.PerMinute[cost.Currency] or nil
				if not row.BubbleIncome or row.BubbleIncome <= 0 then reject("Measured bubble sale income unavailable; complete a bubble-only trial") end
				local projection = (context.EffectiveUpgrades or {})[upgrade.Name]
				row.Projection = projection
				if not projection or not projection.Capacity or not projection.Power or projection.Power <= 0 or not bubble.Capacity
					or bubble.Capacity <= 0 or not bubble.PowerPerBlow or bubble.PowerPerBlow <= 0 then
					reject("Native effective-stat projection unavailable")
				else
					local fill = bubble.Capacity / bubble.PowerPerBlow * config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS
					local projectedFill = projection.Capacity / projection.Power * config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS
					local overhead = sell and sell.SellCycleSeconds or ((sell and (sell.TravelSeconds or sell.Distance / math.max(1, context.WalkSpeed or 16))
						or config.ISLAND_SETTINGS.UNMEASURED_TRAVEL_OVERHEAD_SECONDS) + 2)
					row.EffectiveRateGain = projection.Capacity / bubble.Capacity * (fill + overhead) / math.max(0.1, projectedFill + overhead) - 1
					row.IncrementalPerMinute = (row.BubbleIncome or 0) * math.max(0, row.EffectiveRateGain) * 0.5
					row.Payback = row.IncrementalPerMinute > 0 and cost.Amount * 60 / row.IncrementalPerMinute or math.huge
					if row.Payback > settings.MAXIMUM_PAYBACK_SECONDS then reject("Conservative estimated payback exceeds MAXIMUM_PAYBACK_SECONDS") end
					if mode == "PICKUPS" then
						local selected = (context.Rates or {}).PICKUPS
						local pickupIncome = selected and selected.Ready and selected.PerMinute[currency]
						if not pickupIncome or (row.BubbleIncome or 0) + row.IncrementalPerMinute <= pickupIncome * (1 + config.FARMING_SETTINGS.ACTIVITY_SWITCH_GAIN_RATIO) then
							reject("Projected bubble benefit does not beat the selected measured pickup strategy")
						end
					end
				end
			end
		end
		row.Eligible = #row.Reasons == 0
		if row.Eligible and (not best or row.Payback < best.Row.Payback or (row.Payback == best.Row.Payback and (upgrade.Cost.Amount < best.Upgrade.Cost.Amount
			or (upgrade.Cost.Amount == best.Upgrade.Cost.Amount and upgrade.Name < best.Upgrade.Name)))) then
			best = { Upgrade = table.clone(upgrade), Row = row }
			best.Upgrade.Reserve, best.Upgrade.GoalReserve = row.Reserve or 0, row.GoalReserve or 0
		end
	end
	table.sort(rows, function(a, b) if a.Name == b.Name then return a.Kind < b.Kind end return a.Name < b.Name end)
	return best, rows
end

return UpgradePolicy

end

-- src/OCFoundation/WorldProgressionManager.luau
factories["WorldProgressionManager"] = function()
--!nonstrict
-- Builds observations for OCBrain and executes its decision under the existing OC_GAMEPLAY lease.
local WorldProgressionManager = {}
WorldProgressionManager.__index = WorldProgressionManager

function WorldProgressionManager.new(controller)
	local self = setmetatable({ Controller = controller, Mechanics = controller.Farming.Mechanics, TravelFailures = {}, TravelRetryAt = {} }, WorldProgressionManager)
	self.Mechanics.ProgressionGoalProvider = function()
		local goal = controller.Plan and controller.Plan.Objective
		local progression = goal and goal.Metadata and goal.Metadata.Progression
		return controller.State == "RUNNING" and progression and progression.Node or nil
	end
	self.Mechanics.ProgressionReserveProvider = function()
		-- Fresh graph facts, independent of which competing blocker currently holds the objective.
		local graph = controller.Reader:GetSnapshot().ProgressionGraph
		local node = graph and graph.Next
		return node and node.Kind == "WORLD" and (node.State == "READY" or node.State == "FUNDING") and node.Cost or nil
	end
	return self
end

function WorldProgressionManager:Select(plan)
	local controller, mechanics = self.Controller, self.Mechanics
	if not controller.Config.WORLD_SETTINGS.ENABLE_WORLD_PROGRESSION then self.Economics = nil return false end
	if mechanics.PendingPickupCleanup or controller.Farming.ReturnKey then
		self.Decision, self.Economics = nil, nil return false -- Finish already-dispatched Phase 2 cleanup/saved sell-return through its existing scheduler path.
	end
	local goal = plan.Objective and plan.Objective.Metadata and plan.Objective.Metadata.Progression
	if not goal then
		local graph = controller.Reader:GetSnapshot().ProgressionGraph
		if graph and graph.Complete and not self.ReportedComplete then
			controller:Log("WORLD][GRAPH", "Selected permanent world/island flags already complete; no unlock replay. Other game systems and Phase 3 live approval remain separate.")
			self.ReportedComplete = true
		end
		self.Decision, self.Economics = nil, nil return false
	end
	self.ReportedComplete = false
	local now, current = os.clock(), controller.Farming.Tracker.Current
	local snapshot = table.clone(controller.Reader:GetSnapshot())
	-- Use the existing verified balance reader and approved sample ledger, not pickup face values.
	snapshot.Balances = controller.Reader:ReadBalances()
	self.Economics = controller.Brain:ProgressionEconomics(snapshot, plan, {
		Now = now, Current = current,
		Rate = current and controller.Farming:_pickupRates(current.Key, now).STATIONARY or nil,
	})
	local economics = self.Economics
	if economics then
		local signature = economics.GoalId .. ":" .. economics.Status .. ":" .. tostring(economics.Island)
		if signature ~= self.LastEconomicSignature or now - (self.LastEconomicLogAt or -math.huge) >= controller.Config.WORLD_SETTINGS.ECONOMIC_LOG_INTERVAL_SECONDS then
			self.LastEconomicSignature, self.LastEconomicLogAt = signature, now
			controller:Log("WORLD][ECONOMY", string.format("%s | status=%s | cost=%.0f %s | balance=%.0f | reserve=%.0f | shortage=%.0f | island=%s | rate=%s/min | sample=%ss | age=%ss | ETA=%s | horizon=%.1fh (diagnostic only) | %s",
				economics.World, economics.Status, economics.Cost, economics.Currency, economics.Balance, economics.Reserve, economics.Deficit,
				tostring(economics.Island or "unmeasured"), economics.PerMinute and string.format("%.2f", economics.PerMinute) or "unknown",
				economics.SampleSeconds and string.format("%.1f", economics.SampleSeconds) or "unknown", economics.SampleAgeSeconds and string.format("%.1f", economics.SampleAgeSeconds) or "unknown",
				economics.ETADays and string.format("%.2f days / %.1f hours", economics.ETADays, economics.ETAHours) or (economics.Status == "FUNDED" and "funded" or "unknown"),
				economics.HorizonHours, economics.Assumption))
			if economics.Status == "BOTTLENECK" then
				controller:Log("WORLD][BOTTLENECK", "Estimated funding time exceeds the configured horizon; earning-power review needed. Native pickup multiplier=" .. tostring(economics.NativePickupMultiplier or "unknown") .. " | equipped pets=" .. tostring(economics.EquippedPets or "unknown") .. " | " .. table.concat(economics.Recommendations, " | "))
			end
		end
	end
	local name = goal.Node and goal.Node.Name
	local gate, blocker
	if name and goal.Node.Kind == "WORLD" and goal.Node.State == "READY" then gate, blocker = mechanics:WorldGate(name) end
	local discovery
	if goal.Node and goal.Node.Kind == "ISLAND" and controller.Config.WORLD_SETTINGS.AUTO_DISCOVER_ISLANDS then
		discovery, blocker = mechanics:IslandDiscovery(goal.Node)
		if controller.Config.PICKUP_SETTINGS.STATIONARY_ISOLATED_TEST then discovery, blocker = nil, "Isolated pickup test blocks island discovery" end
	end
	local permitted, guardReason = mechanics:Guard(gate and gate.InRange and "World " .. tostring(gate.Order) or nil)
	local decision = controller.Brain:PlanProgression(controller.Reader:GetSnapshot(), plan, {
		Discovery = discovery, DiscoveryAttempts = goal.Node and mechanics.IslandDiscoveryAttempts[goal.Node.Id] or 0,
		DiscoveryBackoff = (goal.Node and not mechanics:Available("DISCOVER:" .. goal.Node.Id) or false)
			or os.clock()-mechanics.LastDiscoveryAt < controller.Config.WORLD_SETTINGS.ISLAND_DISCOVERY_INTERVAL_SECONDS,
		Gate = gate, Blocker = blocker or guardReason, CanInteract = permitted,
		SessionRequests = mechanics.SessionUnlockRequests or 0, UnlockAttempts = name and (mechanics.UnlockAttempts or {})[name] or 0,
		UnlockBackoff = name and not mechanics:Available("UNLOCK:" .. name) or false,
		TravelBackoff = (name and os.clock() < (self.TravelRetryAt[name] or 0) or false)
			or (gate and gate.DestinationPath and not mechanics:Available("TRAVEL:" .. gate.DestinationPath) or false)
			or os.clock() - mechanics.LastTravelAt < controller.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS,
		TravelFailures = name and self.TravelFailures[name] or 0,
	})
	self.Decision = decision
	if not decision then return false end
	local description = decision.Kind .. " | " .. plan.Objective.Id .. " | " .. decision.Reason
	if description ~= self.LastDescription then
		self.LastDescription = description controller:Log("WORLD][DECISION", description)
		if decision.GateApproach then controller:Log("WORLD][GATE_APPROACH", decision.Reason) end
	end
	return true, decision
end

function WorldProgressionManager:Definition(decision, generation)
	if not decision or decision.Kind == "WAIT" then return nil end
	local controller = self.Controller
	return { Id = "OC_GAMEPLAY", Owner = "WORLD_PROGRESSION", Priority = 100, Generation = generation,
		TimeoutSeconds = math.max(controller.Config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS,
			decision.Kind == "DISCOVER_ISLAND" and (controller.Config.WORLD_SETTINGS.ISLAND_DISCOVERY_CONFIRMATION_TIMEOUT_SECONDS
				+ controller.Config.WORLD_SETTINGS.ISLAND_DISCOVERY_CONTACT_SECONDS+1) or 0,
			controller.Config.WORLD_SETTINGS.UNLOCK_CONFIRMATION_TIMEOUT_SECONDS) + 2,
		CanRun = function() return controller.State == "RUNNING" and controller.Generation == generation
			and controller.Plan and controller.Plan.Objective.Id == decision.GoalId end,
		Execute = function(token)
			if token:CheckCancelled() or controller.State ~= "RUNNING" or controller.Generation ~= generation
				or not controller.Plan or controller.Plan.Objective.Id ~= decision.GoalId then return nil end
			controller.Farming:Halt(true) -- Release Phase 2 measurement/observer ownership, retaining native ID deduplication.
			local ok, reason, evidence
			if decision.Kind == "UNLOCK_WORLD" then ok, reason, evidence = self.Mechanics:UnlockWorld(decision.Node.Name, token)
			elseif decision.Kind == "DISCOVER_ISLAND" then
				local succeeded, output = xpcall(function() return table.pack(self.Mechanics:DiscoverIsland(decision.Node, token)) end, debug.traceback)
				self.Mechanics:EndIslandContact()
				if succeeded then ok, reason, evidence = table.unpack(output, 1, output.n) else ok, reason = false, tostring(output) end
			elseif decision.Kind == "TRAVEL_GATE_ISLAND" then
				local name = decision.Node.Name
				local requestsBefore = self.Mechanics.ProgressionTravelRequests or 0
				-- Install backoff before dispatch so Pause/Stop cannot erase an uncertain travel attempt.
				self.TravelRetryAt[name] = os.clock() + controller.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS
				ok, reason, evidence = self.Mechanics:TravelForProgression(name, token)
				if not ok and (self.Mechanics.ProgressionTravelRequests or 0) > requestsBefore then self.TravelFailures[name] = (self.TravelFailures[name] or 0) + 1
				else self.TravelRetryAt[name] = nil end
			end
			return { Verified = ok, Reason = reason, Evidence = evidence, Kind = decision.Kind, Name = decision.Node.Name }
		end,
		IsComplete = function(result) return type(result) == "table" end }
end

function WorldProgressionManager:Halt()
	self.Mechanics:EndIslandContact() -- Release an existing simulated contact; no new attempt.
	self.Decision = nil -- Cancellation belongs to TaskScheduler. Request/backoff ledgers deliberately survive controls.
	self.Economics = nil -- A stopped/paused estimate must not appear current; existing samples survive for reevaluation.
end

function WorldProgressionManager:Completed(status, result, reason)
	self.Controller:Log("WORLD][RESULT", status .. " | " .. tostring(result and result.Name or "") .. " | " .. tostring(result and result.Reason or reason))
end

function WorldProgressionManager:GetStatus()
	return { Decision = self.Decision, Economics = self.Economics, SessionUnlockRequests = self.Mechanics.SessionUnlockRequests or 0,
		UnlockAttempts = table.clone(self.Mechanics.UnlockAttempts or {}), TravelFailures = table.clone(self.TravelFailures),
		IslandDiscoveryAttempts = table.clone(self.Mechanics.IslandDiscoveryAttempts), DiscoveryCapability = self.Mechanics:IslandDiscoveryCapability() }
end

return WorldProgressionManager

end

-- src/OC.luau
local function entry()
--!nonstrict
-- The compiled bundle returns this initializer. It creates no Script or ModuleScript instances.
local Defaults = requireOC("OCConfig")
local ConfigResolver = requireOC("ConfigResolver")
local OCController = requireOC("OCController")
local OCInterface = requireOC("OCInterface")

return function(customConfig)
	local config = ConfigResolver.Resolve(Defaults, customConfig)
	assert(config.GENERAL_SETTINGS.OC_ENABLED, "[OC] OC_ENABLED=false; initialization is disabled")
	assert(game:GetService("RunService"):IsClient(), "[OC] OC requires a client runtime; server loadstring cannot read client LocalData")
	local players = game:GetService("Players")
	local player = players.LocalPlayer
	assert(player, "[OC] Players.LocalPlayer is unavailable; run after joining your authorized client test environment")
	local playerGui
	if config.STATUS_UI_SETTINGS.ENABLE_STATUS_UI then
		playerGui = player:WaitForChild("PlayerGui", config.ACCOUNT_SETTINGS.MODULE_LOAD_TIMEOUT_SECONDS)
		assert(playerGui, "[OC] PlayerGui did not load before the configured timeout")
	end
	local controller = OCController.new(config, player)
	local ok, result = xpcall(function()
		controller.Interface = OCInterface.new(controller, playerGui)
		controller:Log("INIT", "Phase " .. tostring(controller:GetStatus().Phase) .. " initialized | PlaceId=" .. tostring(game.PlaceId) .. " | build=005f77211830 | Overworld discovery owner-confirmed in session; rejoin persistence and world purchases pending")
		controller:Log("SCOPE", "One Brain/scheduler: configured progression and actual-shortage stationary Coins/Gems farming on The Void/Zen; bubbles require a real bubble objective.")
		if config.PET_SETTINGS.ENABLE_PET_INTELLIGENCE then controller:Log("SCOPE", "Phase 4: actual owned-team/native egg estimates; hatch and equipment require separate Config authorization; destructive actions OFF; final odds/total time may remain UNKNOWN.") end
		if config.EGG_TRAVEL_SETTINGS.ENABLE_SELECTED_EGG_TRAVEL or config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME
			or config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES or config.ANTIAFK_SETTINGS.ENABLE_ANTI_AFK then
			controller:Log("SCOPE", string.format("Local scoped features | selected-egg travel=%s; playtime=%s; owned ordinary box=%s; guarded ScrollLock anti-AFK=%s | no additional hatch/spend permission; owner live verification pending",
				tostring(config.EGG_TRAVEL_SETTINGS.ENABLE_SELECTED_EGG_TRAVEL), tostring(config.PLAYTIME_SETTINGS.AUTO_CLAIM_PLAYTIME),
				tostring(config.MYSTERY_BOX_SETTINGS.AUTO_OPEN_MYSTERY_BOXES), tostring(config.ANTIAFK_SETTINGS.ENABLE_ANTI_AFK)))
		end
		controller:Log("FARM][BULK", "Paced genuine loaded registry IDs, up to " .. tostring(config.PICKUP_SETTINGS.STATIONARY_MAXIMUM_BATCH_SIZE) .. " per stationary batch; distances observed, server validation unchanged; only LocalData balances verify credit.")
		-- Release the previous action authority before starting this instance.
		if type(shared) == "table" then
			local previous = shared.__OC_PHASE1_INSTANCE
			if previous and previous ~= controller and type(previous.Destroy) == "function" then previous:Destroy() end
			local oldMechanics = previous and previous.Farming and previous.Farming.Mechanics
			if oldMechanics and oldMechanics.AntiAFKHeldInput then
				local releasedOK, released, reason = pcall(oldMechanics.ReleaseAntiAFKInput, oldMechanics)
				assert(releasedOK and released == true and oldMechanics.AntiAFKHeldInput == nil,
					"Prior tracked ScrollLock release remains uncertain; replacement/start blocked: " .. tostring(releasedOK and reason or released))
			end
			shared.__OC_PHASE1_INSTANCE = controller
		end
		if config.GENERAL_SETTINGS.AUTO_START then
			local started, reason = controller:Start()
			if not started then controller.Error = reason controller:Log("CONTROL", reason) controller:_notify() end
		end
		return controller
	end, debug.traceback)
	if not ok then controller:Destroy() error("[OC] Initialization failed: " .. tostring(result), 0) end
	return result
end

end
return entry()
